-- Questões originais de estudo baseadas em Date, tradução da 8ª edição (2004).
-- Não são questões oficiais do CP-T nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens são rascunhos: revise no painel antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve os registros deste lote.
-- As explicações acompanham o contexto histórico da edição, quando pertinente.
-- Capítulos 2 a 27 — 520 questões. Não inclui nem modifica o piloto do capítulo 1.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('6887089b-55d2-5877-8a0a-bce01de4b5ff', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Fácil', 'Na arquitetura ANSI/SPARC, qual nível apresenta a visão global lógica dos dados?', '["De comunicação.","De dispositivos.","Conceitual.","Externo.","Interno."]'::jsonb, 2, 'O nível conceitual representa o conteúdo informacional da comunidade de usuários.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.2, páginas 82–86 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e27c48e2-b390-57d6-82f2-da95bb9f0c2b', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Fácil', 'Relatórios de setores diferentes apresentam subconjuntos distintos do mesmo cadastro. Isso corresponde principalmente ao nível:', '["Interno.","Externo.","Físico do dispositivo.","De recuperação de mídia.","De comunicação."]'::jsonb, 1, 'As visões externas representam as necessidades de usuários ou grupos específicos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.2, páginas 82–86 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dd3fbbfd-2321-5ce2-9cc9-8c100560182f', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Fácil', 'A descrição de registros armazenados e caminhos de acesso pertence principalmente ao esquema:', '["De apresentação.","De formulários.","De autorização do usuário final.","Externo.","Interno."]'::jsonb, 4, 'O esquema interno descreve a organização de armazenamento, sem ser uma interface de apresentação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.5, páginas 93–94 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('aa7e85fc-6703-5ab4-bec2-e77e0c1dd592', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Alterar a organização armazenada preservando o esquema conceitual exige ajustar qual correspondência?', '["Usuário/senha.","Aplicação/rede.","Externo/externo, exclusivamente.","Terminal/relatório.","Conceitual/interno."]'::jsonb, 4, 'Esse mapeamento isola mudanças internas e contribui para a independência física.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.6, páginas 95–96 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bbd5c620-224d-5339-b9f9-91bba0adbf30', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Preservar uma visão de usuário após reestruturar o esquema conceitual relaciona-se à independência:', '["De autenticação.","De energia.","De mídia, exclusivamente.","De transações.","Lógica."]'::jsonb, 4, 'Mapeamentos externos/conceituais podem proteger aplicações de mudanças lógicas compatíveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.6, páginas 95–96 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b70b6aaa-f11c-57f2-944b-0947108a6bbf', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'A linguagem hospedeira de uma aplicação contém chamadas para manipular dados. Qual papel cabe à sublinguagem de dados?', '["Expressar operações sobre o banco.","Executar apenas cálculos locais.","Definir o protocolo elétrico da rede.","Substituir o sistema operacional.","Converter discos em memória principal."]'::jsonb, 0, 'A sublinguagem trata dos dados; a linguagem hospedeira atende às demais tarefas da aplicação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.3, páginas 87–90 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('46d4c49d-f85e-539b-b85e-19a5bffddda1', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Um analista inclui endereços físicos de disco na descrição lógica global. Qual avaliação é adequada?', '["Descreveu somente uma visão externa.","Misturou decisões internas com o esquema conceitual.","Aumentou necessariamente a independência física.","Transformou o esquema em linguagem hospedeira.","Eliminou a necessidade de mapeamentos."]'::jsonb, 1, 'O esquema conceitual abstrai detalhes de armazenamento.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.4, páginas 91–92 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9f08d1a5-5471-5df8-873c-f7d89646a030', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Fácil', 'Quem implementa tecnicamente controles definidos pela política de administração de dados?', '["O gerente de comunicações, exclusivamente.","O fabricante do terminal.","Somente o usuário final.","O DBA.","O compilador da linguagem hospedeira."]'::jsonb, 3, 'O DBA traduz políticas em esquemas, controles e procedimentos técnicos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.7, páginas 97–99 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4f10b6f7-1662-56e3-abfc-4f5d11b1db70', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Planejar restauração e acompanhar desempenho são atribuições típicas de qual função?', '["Modelagem de telas, exclusivamente.","Administração do banco de dados.","Digitação de formulários.","Transporte de mensagens, exclusivamente.","Autoria de relatórios, exclusivamente."]'::jsonb, 1, 'O DBA cuida também da operação, disponibilidade e desempenho do sistema.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.7, páginas 97–99 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('999a934c-cd02-5156-add4-d5ffc8510a04', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Antes de executar uma solicitação, o SGBD consulta esquemas e mapeamentos para:', '["Delegar a integridade ao terminal.","Eliminar todas as estruturas físicas.","Relacionar a visão solicitada à organização dos dados armazenados.","Dispensar verificações de autorização.","Transformar cada consulta em alteração."]'::jsonb, 2, 'A solicitação lógica precisa ser interpretada com base nos descritores do banco.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.8, páginas 100–106 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('eadc11b6-61d3-5e59-9539-065ec88483fb', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Qual conteúdo caracteriza o catálogo de um SGBD?', '["Somente respostas temporárias de consultas.","Somente arquivos de programas executáveis.","Apenas cópias de documentos de usuários.","Descrições de objetos e restrições do banco.","Exclusivamente senhas da rede."]'::jsonb, 3, 'O catálogo mantém metadados necessários à interpretação e gestão dos objetos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.8, páginas 100–106 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6a719d80-3166-55a6-8b34-f96018edd83c', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Transportar mensagens entre a estação do usuário e o serviço de dados cabe principalmente ao:', '["Gerenciador de comunicações de dados.","Índice de uma tabela.","Esquema conceitual.","Predicado de integridade.","Gerador de relatórios."]'::jsonb, 0, 'Comunicação e gerenciamento dos dados têm responsabilidades diferentes, embora cooperem.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.9, páginas 107 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('87f93f70-e007-5c58-9100-1126a5c040b8', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Fácil', 'Na divisão cliente/servidor apresentada no capítulo, o back end corresponde ao:', '["Formulário executado pelo usuário.","Servidor que fornece os serviços de gerenciamento de dados.","Dispositivo de entrada.","Compilador de interfaces.","Documento impresso."]'::jsonb, 1, 'O servidor oferece funções do SGBD; clientes utilizam esses serviços.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.10, páginas 108–111 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f210f0f2-bb2d-5ed2-98a2-2e3f5530f758', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Uma aplicação gráfica e um gerador de relatórios acessam o mesmo servidor. Eles são:', '["Clientes distintos de um mesmo serviço de dados.","Uma única transação por definição.","Partes do hardware de armazenamento.","Dois esquemas internos idênticos.","Obrigatoriamente dois bancos distribuídos."]'::jsonb, 0, 'Múltiplos front ends podem consumir serviços do mesmo back end.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.10, páginas 108–111 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e789ca69-b72d-5579-a8c5-fb4827c6ecd8', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Separar cliente e servidor exige que eles executem em máquinas diferentes?', '["Não; a separação é funcional e pode existir na mesma máquina.","Não, porque cliente e servidor são o mesmo componente.","Sim, com sistemas operacionais distintos.","Sim, sempre em redes diferentes.","Sim, com bancos incompatíveis."]'::jsonb, 0, 'A divisão de responsabilidades não determina necessariamente a localização física.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.10, páginas 108–111 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('057aad5d-a1e2-55ee-9dff-d420766a8411', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Qual utilitário auxilia a criar a versão inicial do banco a partir de arquivos existentes?', '["Despachante de impressora.","Editor de texto.","Monitor de temperatura.","Rotina de carga.","Gerenciador de janelas."]'::jsonb, 3, 'Utilitários de carga transferem dados de fontes externas para o banco.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.11, páginas 112 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fb7cafb8-3d07-5004-b4ba-46311e56a45c', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Qual par de funções corresponde a dump/restore?', '["Compilação e edição.","Seleção de linhas e projeção de colunas.","Junção e divisão.","Descarga para cópia e recarga a partir dessa cópia.","Autenticação e autorização."]'::jsonb, 3, 'Descarga e recarga auxiliam operações de backup e restauração.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.11, páginas 112 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ca9c2dcd-ed70-567e-802d-b822b75e0497', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Uma tarefa envolve serviços executados em várias máquinas conectadas. Isso caracteriza:', '["Necessariamente um único arquivo físico compartilhado.","Acesso exclusivamente monousuário.","Processamento distribuído.","Eliminação de comunicação.","Independência de dados lógica, por definição."]'::jsonb, 2, 'Processamento pode ser distribuído sem que toda distribuição corresponda a um banco distribuído.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.12, páginas 113–118 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bf8f90bd-5996-50bc-983e-9ab489ff2698', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Um servidor central atende clientes remotos. Esse fato, isoladamente, comprova distribuição dos dados entre vários sites?', '["Sim, pois consultas são sempre transações distribuídas.","Não, porque clientes remotos não processam informações.","Não; distribuição do processamento não implica distribuição do banco.","Sim, pois todo cliente contém uma réplica.","Sim, pois a rede fragmenta automaticamente tabelas."]'::jsonb, 2, 'É preciso distinguir localização das aplicações e localização dos dados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.12, páginas 113–118 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b0b31d62-8b11-5b1a-b1bc-adc29c7a9b6f', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Qual afirmação respeita a arquitetura de três níveis?', '["O esquema externo deve expor todos os índices.","O nível conceitual é uma cópia física por usuário.","Cada usuário exige um esquema interno exclusivo.","Os mapeamentos substituem os dados armazenados.","Podem existir vários esquemas externos para um esquema conceitual."]'::jsonb, 4, 'A arquitetura permite visões particulares sobre uma descrição lógica global.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 2, seção 2.2, páginas 82–86 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5ce0d183-6a47-5a6e-b367-fc5569ad5dca', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Quais aspectos compõem a caracterização introdutória do modelo relacional?', '["Senha, backup e compilação.","Tela, rede e impressão.","Disco, processador e teclado.","Arquivo, diretório e terminal.","Estrutura, integridade e manipulação."]'::jsonb, 4, 'O modelo descreve estruturas, regras válidas e operadores sobre os dados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.2, páginas 128–134 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3bd1fe93-dd99-5783-a818-2cbe68fa8841', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Operadores relacionais recebem relações e devolvem relações. Essa propriedade é denominada:', '["Persistência.","Serialização de arquivos.","Criptografia.","Replicação.","Fechamento."]'::jsonb, 4, 'O fechamento permite usar resultados relacionais como operandos de novas expressões.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.2, páginas 128–134 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('990ca3c6-8df5-5fb8-8e44-b7952a332d5f', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Fácil', 'Uma consulta filtra estudantes por idade. Qual operador relacional representa o filtro de linhas?', '["Restrição ou seleção.","Renomeação.","Divisão.","União.","Projeção."]'::jsonb, 0, 'A restrição conserva apenas as tuplas que satisfazem o predicado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.2, páginas 128–134 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('790fa99f-bc13-555c-91de-a11eb5d575f9', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'Uma consulta retém apenas nome e matrícula de uma relação. Qual operador descreve isso?', '["Projeção.","Restrição.","Transação.","Produto cartesiano.","Diferença."]'::jsonb, 0, 'A projeção escolhe atributos do resultado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.2, páginas 128–134 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8bebf2d8-3631-5550-be63-a72016a52b92', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Combinar inscrições e cursos pelas identificações correspondentes é uma aplicação de:', '["Descarregamento.","Rollback.","Criptografia.","Autorização.","Junção."]'::jsonb, 4, 'A junção relaciona tuplas compatíveis segundo os atributos ou condições especificados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.2, páginas 128–134 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4dd4d53a-51ac-5131-b584-8a46b3c06709', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Fácil', 'Qual distinção entre relação e relvar está correta?', '["Relação designa somente um diagrama E/R.","A relação é um valor; a relvar é uma variável que pode assumir valores de relação.","A relação é um índice; a relvar é uma senha.","Ambas são obrigatoriamente arquivos físicos.","A relvar é imutável; a relação é uma variável."]'::jsonb, 1, 'Essa distinção separa o valor atual do objeto variável que recebe atualizações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.3, páginas 135–138 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8958b6f1-33ff-5fa0-9756-7f727872e215', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Após inserir uma inscrição em uma relvar, o que muda conceitualmente?', '["Necessariamente seu tipo.","Sua classificação como variável.","Seu valor de relação atual.","O significado de todos os atributos.","Obrigatoriamente seu nome."]'::jsonb, 2, 'Uma atualização atribui um novo valor compatível à relvar.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.3, páginas 135–138 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('abef5911-2789-51f4-b182-a58102e07998', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Os tipos associados aos atributos delimitam principalmente:', '["Os valores admissíveis e as operações aplicáveis.","O horário de execução do backup.","A posição física dos discos.","O endereço de rede do servidor.","O número de usuários conectados."]'::jsonb, 0, 'Tipos descrevem conjuntos de valores e operações; não são localizações físicas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.4, páginas 139–142 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('97e24f18-f19f-5070-a1d8-2483ae8d0791', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Uma tupla de uma relação pode ser interpretada como:', '["Um ponteiro físico para outra tabela.","Uma definição completa de todos os índices.","Uma autorização concedida ao usuário.","Uma proposição obtida ao preencher os parâmetros de um predicado.","Um comando obrigatório de exclusão."]'::jsonb, 3, 'O predicado dá significado à relação; cada tupla instancia uma afirmação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.4, páginas 139–142 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('997e97df-477a-5841-80a5-004d8e1361e9', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Uma linguagem relacional permite indicar o resultado desejado sem programar caminhos físicos. Isso favorece:', '["Obrigatoriedade de cursores.","Execução sem qualquer plano.","Navegação automática pelo sistema.","Dependência de endereços de disco.","Ausência de otimização."]'::jsonb, 2, 'O sistema escolhe meios de obter os dados, poupando navegação manual na aplicação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.5, páginas 143–145 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e8065793-631c-5883-9f36-f885409c7f04', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Duas expressões logicamente equivalentes têm custos diferentes. Qual função pode escolher sua execução eficiente?', '["Administrador de documentos.","Otimizador.","Editor de formulários.","Protocolo de impressão.","Gerador de senhas."]'::jsonb, 1, 'O otimizador usa alternativas de execução e informações sobre o banco.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.5, páginas 143–145 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9b126e49-7900-548f-ab61-97d36eef15aa', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Fácil', 'Descrições de relvars, índices e restrições são exemplos de:', '["Dados exclusivamente transitórios do terminal.","Código de máquina da aplicação.","Metadados mantidos no catálogo.","Resultados obrigatórios de toda consulta.","Registros que não podem ser consultados por nenhum meio."]'::jsonb, 2, 'Metadados descrevem objetos do sistema e apoiam sua administração.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.6, páginas 146–147 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d9454fec-fa52-574a-ae14-dc7c58039792', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Informações sobre índices no catálogo são especialmente úteis para:', '["Transformar qualquer dado inválido em válido.","Dispensar a definição de tipos.","Escolher caminhos de acesso durante a otimização.","Eliminar a necessidade de memória.","Substituir todas as transações."]'::jsonb, 2, 'Descritores físicos ajudam a avaliar alternativas de implementação das consultas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.6, páginas 146–147 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('eec36bae-8e1b-5e3e-ae0f-d5f26ebee3ae', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Uma visão definida por uma expressão sobre outras relvars é uma relvar:', '["Obrigatoriamente básica.","Virtual ou derivada.","Impossível de consultar.","Sem tipo.","Fisicamente independente de todas as fontes."]'::jsonb, 1, 'A visão tem definição derivada; não exige armazenamento próprio de seu conteúdo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.7, páginas 148–152 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ba2bbccc-497a-5e9a-8905-06230cc516e6', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Uma consulta usa uma visão, cujo nome é substituído pela expressão definidora. Esse mecanismo depende de:', '["Fechamento das expressões relacionais.","Conhecimento de endereços físicos pelo usuário.","Ausência de predicados.","Duplicação de todas as tabelas.","Uso exclusivo de dados escalares."]'::jsonb, 0, 'A substituição funciona porque a expressão definidora produz uma relação utilizável no contexto.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.7, páginas 148–152 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c4e8b2c4-e533-5ec7-ad50-5bf09b251c57', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Duas alterações devem compor uma unidade lógica de trabalho. Qual recurso delimita essa unidade?', '["Projeção.","Domínio escalar.","Catálogo de nomes.","Transação.","Cabeçalho."]'::jsonb, 3, 'Uma transação agrupa operações cujo resultado deve ser tratado de forma coordenada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.8, páginas 153–154 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e8d18db4-bd95-54f3-b15d-a5513d0cadb4', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Fácil', 'Qual operação encerra com sucesso uma transação, confirmando seus efeitos?', '["ROLLBACK.","RENAME.","DROP TYPE.","PROJECT.","COMMIT."]'::jsonb, 4, 'COMMIT confirma; ROLLBACK desfaz os efeitos não confirmados da transação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.8, páginas 153–154 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('30aac869-d852-5eb5-bec0-7cfc84770134', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Fácil', 'Uma validação falha antes da confirmação. Qual operação permite abandonar as alterações da transação?', '["GRANT.","CREATE VIEW.","COMMIT.","ROLLBACK.","SELECT."]'::jsonb, 3, 'ROLLBACK encerra a transação sem confirmar suas alterações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.8, páginas 153–154 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('18ad589e-0f8b-5cd4-be9c-30fcf5280ead', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Uma relação de associação liga prestadores a serviços. Para localizar nomes dos prestadores por serviço, normalmente é necessário:', '["Interpretar o nome do serviço como endereço físico.","Remover os identificadores antes de combinar os dados.","Transformar todos os nomes em chaves estrangeiras.","Combinar a associação com o cadastro de prestadores.","Substituir as relações por ponteiros visíveis."]'::jsonb, 3, 'A associação contém a ligação; a junção recupera atributos descritivos do cadastro.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.9, páginas 155–158 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3637bb84-e680-5bd6-8d46-aba5cc3e872d', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Uma tabela possui linhas e colunas, mas ignora restrições e operadores relacionais. A aparência tabular, sozinha:', '["Define uma transação atômica.","Não caracteriza todos os aspectos do modelo relacional.","Elimina a necessidade de integridade.","Impede qualquer duplicação em SQL.","Garante conformidade integral ao modelo."]'::jsonb, 1, 'A estrutura é apenas um dos aspectos; integridade e manipulação também importam.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 3, seção 3.2, páginas 128–134 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('958e3c5f-345c-5abc-a9cf-eab6749d9283', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Fácil', 'Qual instrução SQL define a estrutura de uma nova tabela?', '["COMMIT.","UPDATE.","DELETE FROM.","CREATE TABLE.","INSERT INTO."]'::jsonb, 3, 'CREATE TABLE é definição de dados; as demais opções não criam a estrutura de uma tabela.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.2, páginas 171–174 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a4d57e5c-deea-591f-8492-f948faa01ddf', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Fácil', 'Qual comando acrescenta linhas a uma tabela existente?', '["INSERT.","REVOKE.","ROLLBACK.","DROP.","ALTER."]'::jsonb, 0, 'INSERT faz parte da manipulação de dados e acrescenta novas linhas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.2, páginas 171–174 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6f7747b1-58cb-5f05-8277-f14fd33cf331', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Fácil', 'Qual operação modifica valores de linhas existentes?', '["UPDATE.","GRANT.","COMMIT.","DROP TYPE.","CREATE SCHEMA."]'::jsonb, 0, 'UPDATE altera dados existentes, normalmente delimitados por uma condição.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.2, páginas 171–174 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bdbe7d5b-65ec-5561-9d37-ea434160f2ca', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Em SQL, DELETE FROM item sem cláusula WHERE solicita:', '["Somente a exclusão da primeira linha.","Uma consulta sem alteração.","Somente a remoção dos índices.","A remoção da definição da tabela.","A exclusão de todas as linhas da tabela, sujeita às restrições aplicáveis."]'::jsonb, 4, 'DELETE remove linhas; DROP remove objetos de esquema.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.2, páginas 171–174 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('faa5f071-3b79-52a2-bf01-5c868ce57028', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Qual diferença entre DROP TABLE e DELETE FROM está correta?', '["DROP confirma uma consulta; DELETE inicia uma transação.","Ambos apenas ocultam linhas de uma visão.","DROP remove a tabela; DELETE remove linhas preservando sua definição.","DELETE remove o esquema; DROP limpa somente dados.","Ambos são sinônimos de projeção."]'::jsonb, 2, 'A distinção é entre remover um objeto e manipular seu conteúdo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.2, páginas 171–174 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9f4fc5c4-5759-524a-8b24-5c1824024752', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Fácil', 'Uma coluna deve impedir valores nulos. Qual declaração expressa diretamente isso?', '["DISTINCT.","NOT NULL.","ORDER BY.","GROUP BY.","UNION ALL."]'::jsonb, 1, 'NOT NULL restringe a presença de marcadores nulos nessa coluna.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.2, páginas 171–174 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0f2512f9-862a-59e3-bb59-c677875db70c', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Fácil', 'Uma coluna identifica unicamente cada linha e não admite nulos. Qual declaração é apropriada?', '["CHECK sem condição.","FOREIGN KEY sem referência.","DEFAULT NULL.","ORDER BY.","PRIMARY KEY."]'::jsonb, 4, 'Uma chave primária combina identificação única com não nulidade em SQL.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.2, páginas 171–174 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9d6337bd-8580-574a-b873-036c9746eb7c', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Para exigir que uma identificação de curso corresponda a um curso cadastrado, usa-se:', '["ORDER BY.","CREATE INDEX sem restrição.","SELECT DISTINCT.","COMMIT WORK.","FOREIGN KEY com REFERENCES."]'::jsonb, 4, 'A chave estrangeira expressa a referência entre as tabelas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.2, páginas 171–174 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('53d892cd-c002-51a3-8300-679c9603237f', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'No padrão SQL apresentado, o Information Schema fornece:', '["Descrições padronizadas de objetos do banco.","Somente valores das aplicações de negócio.","Cópias integrais de todos os backups.","Resultados de consultas anteriores.","Arquivos executáveis do servidor."]'::jsonb, 0, 'O Information Schema permite consultar metadados do banco.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.3, páginas 175–176 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3e99650a-3058-594c-b892-095a0d44e778', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'O que uma instrução CREATE VIEW ... AS SELECT define?', '["Uma cópia de segurança obrigatória.","Um novo servidor físico.","Uma transação já confirmada.","Um índice exclusivo por coluna.","Uma visão baseada no resultado de uma consulta."]'::jsonb, 4, 'A definição da visão especifica uma consulta e não exige copiar seus dados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.4, páginas 177–178 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('96794fa4-4457-5eba-bfcb-7f94eb226538', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Uma consulta à visão de alunos ativos inclui outro filtro por cidade. Conceitualmente, o resultado deve satisfazer:', '["Uma escolha aleatória entre os filtros.","Nenhum filtro, pois visões não aceitam condições.","Apenas o filtro da visão.","O filtro da visão e o filtro adicional.","Apenas o filtro por cidade."]'::jsonb, 3, 'A expansão da visão conserva sua condição e incorpora a condição da consulta.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.4, páginas 177–178 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5166e506-1feb-5fa7-b26a-3e97983a1f0b', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Fácil', 'Qual comando SQL confirma uma transação?', '["GRANT WORK.","CREATE VIEW.","DELETE WORK.","COMMIT WORK.","ROLLBACK WORK."]'::jsonb, 3, 'WORK é opcional no comando de confirmação apresentado no capítulo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.5, páginas 179 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('65119875-5edb-507a-9bce-5376aa1fee74', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Fácil', 'Qual comando SQL desfaz uma transação não confirmada?', '["SELECT WORK.","COMMIT WORK.","DROP WORK.","ROLLBACK WORK.","INSERT WORK."]'::jsonb, 3, 'ROLLBACK abandona as alterações da transação ainda não confirmada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.5, páginas 179 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0f56740c-f5ba-5576-a2f5-9b92599bcbab', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'O que caracteriza SQL embutida?', '["SQL executada somente por terminal interativo.","Um banco sem SGBD.","Instruções SQL integradas a um programa em linguagem hospedeira.","Uma tabela sem atributos.","Dados criptografados dentro de índices."]'::jsonb, 2, 'O programa combina sua linguagem de aplicação com operações SQL.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.6, páginas 180–189 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2ab9f741-ae34-5246-9d35-825de8e735df', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Uma variável do programa recebe um valor usado por uma instrução SQL embutida. Ela atua como:', '["Novo esquema interno.","Chave primária implícita.","Variável hospedeira.","Índice de agrupamento.","Arquivo de catálogo."]'::jsonb, 2, 'Variáveis hospedeiras fazem a ponte entre valores do programa e instruções SQL.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.6, páginas 180–189 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6816a79a-6cce-56e2-9f9c-0dfdd448f58e', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Por que cursores aparecem na discussão de SQL embutida?', '["Eliminam o processamento linha a linha.","Permitem percorrer resultados com várias linhas em interfaces orientadas a registros.","Convertem tabelas em índices físicos.","Garantem por si só a atomicidade.","Publicam automaticamente novas visões."]'::jsonb, 1, 'O cursor adapta um resultado tabular a operações de obtenção de linhas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.6, páginas 180–189 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1a8f5ec0-4b1d-509c-b7d6-6128ee913325', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Uma aplicação só conhece o texto da consulta durante a execução. Que recurso atende a esse caso?', '["SQL dinâmica.","Uma visão sem definição.","SQL exclusivamente estática.","Um backup completo.","Somente DDL previamente fixada."]'::jsonb, 0, 'SQL dinâmica permite preparar ou executar instruções determinadas em tempo de execução.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.7, páginas 190–194 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9d273b30-0a31-5801-a997-bfbee48643be', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Na execução dinâmica, PREPARE tem como finalidade principal:', '["Apagar o catálogo.","Preparar uma instrução cujo texto foi fornecido em tempo de execução.","Conceder privilégios a todos os usuários.","Persistir obrigatoriamente o resultado da consulta.","Confirmar toda transação aberta."]'::jsonb, 1, 'Preparação da instrução e confirmação da transação são operações distintas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.7, páginas 190–194 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('75bd503b-acf9-5c69-a392-033188a723ea', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'A SQL/CLI oferece principalmente uma interface de:', '["Execução sem conexão ou contexto de dados.","Chamadas de funções para acessar serviços SQL.","Gravação direta em setores de disco.","Impressão de documentos.","Diagramação E/R."]'::jsonb, 1, 'Uma interface de chamadas permite invocar funções SQL a partir de programas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.7, páginas 190–194 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3230b809-e604-5e61-8b33-9f24e37be67a', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Segundo a análise crítica de Date, implementar SQL significa realizar perfeitamente o modelo relacional?', '["Não, porque SQL só descreve hardware.","Sim, por definição normativa do modelo.","Não; o autor aponta divergências e limitações da linguagem.","Sim, porque qualquer tabela é uma relação matemática.","Sim, desde que o banco tenha uma única tabela."]'::jsonb, 2, 'O capítulo distingue a relevância prática da SQL de sua fidelidade ao modelo teórico.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 4, seção 4.8, páginas 195 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d0d4fa8d-6638-53ae-b674-bef45162175c', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Fácil', 'Após atribuir 12 a X e depois 19 a X, o que mudou?', '["Todo o domínio de X.","A identidade de todos os inteiros.","A definição do inteiro 19.","O valor matemático 12.","O valor atual da variável X."]'::jsonb, 4, 'Variáveis recebem valores diferentes; valores individuais não se transformam em outros valores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.2, páginas 215–217 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8c598b8f-19b2-5a11-bbef-a13f3f862ee1', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Fácil', 'Qual elemento representa uma constante individual, independentemente de seu armazenamento?', '["Uma variável atualizável.","Um valor.","Uma sessão do usuário.","Um cursor aberto.","Um endereço de disco."]'::jsonb, 1, 'O valor é abstrato; sua codificação na memória é uma representação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.2, páginas 215–217 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d9e7e324-2f7b-54ef-a7fa-68724e5d5a50', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Um identificador é armazenado como caracteres. Isso autoriza qualquer operação textual sobre ele?', '["Não, porque identificadores não possuem tipos.","Sim, mas apenas se houver um índice.","Sim, qualquer codificação define todos os operadores.","Sim, inclusive operações sem significado no domínio.","Não; os operadores aplicáveis dependem do tipo lógico."]'::jsonb, 4, 'A representação física não deve determinar a semântica do tipo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.3, páginas 218–224 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ea598dcc-6b5c-53bd-85ef-0deb188250cb', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Alterar a codificação interna de um tipo preservando seus operadores públicos ilustra:', '["Ausência de abstração.","Separação entre tipo e representação.","Mudança obrigatória de todos os valores abstratos.","Transformação do tipo em relvar.","Eliminação do domínio."]'::jsonb, 1, 'A interface lógica pode permanecer estável apesar da mudança de representação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.3, páginas 218–224 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ce5df646-6c5f-5226-a8ba-8e2b3644159f', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Um tipo TEMPERATURA_POSITIVA admite apenas valores acima de zero. A condição delimita:', '["A quantidade de transações.","O conjunto de valores do tipo.","A localização do catálogo.","A sequência física das linhas.","O número de usuários autorizados."]'::jsonb, 1, 'Restrições de tipo determinam quais valores pertencem ao domínio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.4, páginas 225–228 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4de156e2-9216-55a0-8375-6edf45c470f5', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'Um seletor de valores de um tipo tem como papel:', '["Produzir um valor do tipo a partir dos argumentos apropriados.","Liberar bloqueios exclusivos.","Excluir atributos do catálogo.","Escolher obrigatoriamente linhas de uma relvar.","Confirmar uma transação."]'::jsonb, 0, 'Seletores de tipo não se confundem com o operador relacional de seleção.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.4, páginas 225–228 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('05af6dc9-2195-5d6a-9ea1-fe275fdb8cef', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Duas representações possíveis descrevem coordenadas cartesianas e polares do mesmo ponto. Elas necessariamente definem dois tipos distintos?', '["Sim, cada representação física define um tipo.","Sim, porque um valor só admite uma descrição.","Não, porque pontos não podem ser valores.","Não; um tipo pode admitir representações possíveis diferentes.","Sim, se houver operadores de leitura."]'::jsonb, 3, 'O valor abstrato pode ser descrito por representações possíveis distintas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.3, páginas 218–224 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('78303112-92bc-5811-a12d-84b72f439aca', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Qual operador é somente de leitura?', '["Um que calcula um resultado sem atualizar variáveis por efeito da invocação.","Um que altera um argumento recebido.","Um que exclui uma relvar.","Um que troca o conteúdo de duas variáveis.","Um que sempre confirma transações."]'::jsonb, 0, 'Operadores de leitura calculam resultados; operadores de atualização podem modificar variáveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.5, páginas 229–236 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c25ad7ec-109c-52b9-98c3-28fdc16609e8', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Uma operação incrementa diretamente uma variável passada como argumento. Ela é classificada como:', '["Cabeçalho relacional.","Operador de atualização.","Literal.","Gerador de tipos, necessariamente.","Valor constante."]'::jsonb, 1, 'A classificação considera o efeito sobre variáveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.5, páginas 229–236 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c31abd85-7b8c-5508-a683-31160a8d08cf', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Por que os tipos dos parâmetros fazem parte da definição de um operador?', '["Eles tornam desnecessário um resultado.","Eles determinam a senha do usuário.","Eles substituem a semântica do operador.","Eles definem o endereço físico do código.","Eles especificam argumentos admissíveis e ajudam a determinar sua aplicação."]'::jsonb, 4, 'Assinaturas de operadores incluem informação de tipagem relevante à sua utilização.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.5, páginas 229–236 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('15ce7d87-8bc6-50d0-af74-e4ff7df21068', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Fácil', 'Um gerador de tipos distingue-se por produzir:', '["Uma autorização de acesso.","Um arquivo de backup.","Somente um valor inteiro.","Um tipo a partir de seus parâmetros.","Uma confirmação de transação."]'::jsonb, 3, 'Geradores como TUPLE e RELATION constroem tipos, não apenas valores de negócio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.6, páginas 237–239 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b34aaa36-7b9e-564e-89b9-792b991b216a', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'O gerador TUPLE recebe uma especificação de atributos. Seu resultado é:', '["Um tipo de tupla.","Um índice físico.","Uma lista de transações confirmadas.","Uma sessão de usuário.","Uma tupla de dados obrigatoriamente existente."]'::jsonb, 0, 'É preciso distinguir gerar um tipo de selecionar um valor desse tipo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.6, páginas 237–239 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6e14f26c-6c28-5bb7-8aee-155cb6816c15', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'O gerador RELATION permite definir:', '["Apenas inteiros positivos.","Somente arquivos sequenciais.","Planos físicos de junção.","Tipos de relação com atributos especificados.","Permissões de rede."]'::jsonb, 3, 'O tipo de relação descreve o cabeçalho dos valores relacionais admitidos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.6, páginas 237–239 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('48360c2f-828e-5647-8ec9-c24416f750ab', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Um atributo pode possuir um valor que também seja uma relação?', '["Não, porque todo atributo precisa ser texto.","Não, porque o modelo exige apenas inteiros.","Não, pois relações não são valores.","Sim, mas somente como ponteiro sem tipo.","Sim, mediante um tipo relacional apropriado."]'::jsonb, 4, 'Tipos não escalares incluem tipos de relação; o valor continua sendo um único valor do tipo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.6, páginas 237–239 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e3dd8634-8a17-540f-8579-e213feb58f2a', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Expor o formato interno de armazenamento como contrato obrigatório para aplicações reduz:', '["A quantidade de operadores necessariamente.","A possibilidade de definir variáveis.","A liberdade de alterar a implementação sem afetar clientes.","A necessidade de autenticação.","O significado das constantes matemáticas."]'::jsonb, 2, 'O encapsulamento da representação protege aplicações de mudanças internas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.3, páginas 218–224 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('13fd210f-4432-5249-93ed-18f279e82f5d', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Um valor fora da restrição de um tipo deve ser tratado como:', '["Um valor válido após renomear a variável.","Válido se tiver a mesma quantidade de bytes.","Não pertencente ao conjunto de valores desse tipo.","Uma nova chave primária automática.","Uma transação já confirmada."]'::jsonb, 2, 'Compatibilidade de armazenamento não substitui validade semântica.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.4, páginas 225–228 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fde0a948-c043-5402-ac02-53140bf06ae5', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Fácil', 'Qual tipo SQL é mais diretamente voltado a valores exatos com precisão e escala declaradas?', '["BOOLEAN.","BLOB.","CHARACTER LARGE OBJECT.","NUMERIC(p,q).","DATE."]'::jsonb, 3, 'NUMERIC permite especificar precisão e escala para números exatos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.7, páginas 240–250 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('547bd27e-922a-5bd6-b0aa-771cfec3b1ef', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Fácil', 'Qual categoria SQL atende a grandes conteúdos binários?', '["INTERVAL.","DATE.","BLOB.","BOOLEAN.","SMALLINT."]'::jsonb, 2, 'BLOB representa grandes objetos binários, não um domínio de números ou datas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.7, páginas 240–250 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f5ce6f9c-6bab-5cbd-a141-fbe681c5e340', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Um tipo definido pelo usuário deve ser confundido com uma tabela que armazena seus valores?', '["Não; o tipo define valores admissíveis e a tabela armazena dados tipados.","Sim, se o tipo tiver operadores.","Não, porque tipos definidos pelo usuário não podem ser usados em atributos.","Sim, pois cada tipo precisa de uma tabela exclusiva.","Sim, ambos são relvars por definição."]'::jsonb, 0, 'Definição de domínio e definição de variável de relação são operações conceitualmente distintas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.7, páginas 240–250 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6eaccaf9-1c46-5666-9854-48b4242794bb', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Copiar o valor de X para Y torna X e Y a mesma variável?', '["Sim, qualquer igualdade de valores unifica variáveis.","Sim, mas somente para inteiros.","Não; variáveis distintas podem ter o mesmo valor atual.","Sim, até o encerramento da transação.","Não, porque valores nunca podem ser copiados."]'::jsonb, 2, 'Igualdade de valores não implica identidade de variáveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 5, seção 5.2, páginas 215–217 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('227b23e9-7e19-5a38-84d8-278cfa56df28', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Fácil', 'Uma tupla com quatro atributos possui grau:', '["8.","1.","Dependente do número de linhas.","0.","4."]'::jsonb, 4, 'O grau de uma tupla é a quantidade de seus atributos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.2, páginas 261–266 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bb099c45-9105-59f8-a544-9684816f291e', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Cada atributo de uma tupla contém:', '["Um endereço físico obrigatório.","Uma sequência obrigatória de linhas.","Exatamente um valor do tipo correspondente.","Uma quantidade arbitrária de valores sem tipo.","Uma tabela separada obrigatória."]'::jsonb, 2, 'O valor pode ser complexo, mas deve pertencer ao tipo do atributo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.2, páginas 261–266 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6b25fe47-171a-5d87-b7e2-a307ea736aba', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Trocar a ordem de apresentação dos atributos altera uma tupla no modelo relacional?', '["Não, porque tuplas não têm valores.","Não, se nomes, tipos e valores correspondentes forem preservados.","Sim, porque a primeira posição sempre é chave.","Sim, porque atributos não possuem nomes.","Sim, pois a ordem faz parte do cabeçalho matemático."]'::jsonb, 1, 'Atributos são identificados por nomes, não por uma posição de apresentação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.2, páginas 261–266 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('407fc5bb-2b99-5fda-875d-40b3925f4f6a', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'Quais partes constituem um valor de relação?', '["Programa e terminal.","Cabeçalho e corpo.","Log e backup.","Índice e senha.","Cursor e sessão."]'::jsonb, 1, 'O cabeçalho descreve atributos; o corpo é um conjunto de tuplas desse cabeçalho.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.3, páginas 267–269 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d0261a91-6c1d-5cc6-bec3-2eed9cce9c76', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'O corpo de uma relação é um:', '["Conjunto de tuplas com o mesmo cabeçalho.","Programa que percorre ponteiros.","Arquivo físico ordenado por inserção.","Multiconjunto obrigatório de linhas heterogêneas.","Conjunto de esquemas externos."]'::jsonb, 0, 'O corpo relacional é um conjunto homogêneo de tuplas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.3, páginas 267–269 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('df7d3555-8bca-521e-a3cd-a2ff951df089', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Fácil', 'Uma relação possui seis atributos e onze tuplas. Seu grau e sua cardinalidade são:', '["6 e 11.","11 e 66.","6 e 66.","17 e 6.","11 e 6."]'::jsonb, 0, 'Grau conta atributos; cardinalidade conta tuplas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.4, páginas 270–281 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('19c9fb98-22c1-500d-8cbf-0968ded580dd', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Duas tuplas iguais podem aparecer duas vezes no corpo de uma relação matemática?', '["Sim, quando inseridas em horários diferentes.","Sim, se houver chaves estrangeiras.","Não; o corpo é um conjunto.","Não, porque relações admitem apenas uma tupla.","Sim, se estiverem em páginas distintas."]'::jsonb, 2, 'Conjuntos não preservam multiplicidade de elementos iguais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.4, páginas 270–281 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('586868c4-1fa4-5510-8fac-0027fdb163e6', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Reordenar visualmente as tuplas modifica o valor da relação?', '["Sim, toda relação é uma lista ordenada.","Não, porque as tuplas não pertencem ao corpo.","Sim, apenas quando não houver índice.","Não, se o conjunto de tuplas permanecer igual.","Sim, pois a primeira tupla define o tipo."]'::jsonb, 3, 'A ordem de apresentação das tuplas não faz parte do valor relacional.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.4, páginas 270–281 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b03fe69b-d7ae-555f-a1af-f086116c12a0', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Fácil', 'Uma relação sem tuplas, mas com três atributos, tem cardinalidade e grau:', '["3 e 3.","1 e 3.","3 e 0.","0 e 3.","0 e 0."]'::jsonb, 3, 'A ausência de tuplas não elimina o cabeçalho.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.4, páginas 270–281 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e6e91cb9-0398-52db-a254-1899b72db885', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Quantos valores relacionais distintos existem para um cabeçalho sem atributos?', '["Um para cada usuário.","Cinco, conforme a cardinalidade física.","Dois: um sem tuplas e outro com a tupla vazia.","Nenhum, pois o grau deve ser positivo.","Infinitos, um para cada ordenação."]'::jsonb, 2, 'Sem atributos existe uma única tupla possível; seu conjunto pode estar vazio ou contê-la.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.4, páginas 270–281 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4e15474b-f5a1-50b9-94a9-7ec86eb21912', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Qual propriedade caracteriza TABLE_DUM?', '["Relação com uma coluna obrigatória.","Relação de grau zero e cardinalidade zero.","Relação de grau zero e cardinalidade um.","Tabela SQL sem nome.","Relação com tuplas duplicadas."]'::jsonb, 1, 'TABLE_DUM não contém a tupla vazia; TABLE_DEE a contém.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.4, páginas 270–281 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('502dd6d5-301a-50cd-9e01-c9ae0f9f0025', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Qual propriedade caracteriza TABLE_DEE?', '["Relação com uma coluna booleana.","Relação necessariamente infinita.","Relação de cardinalidade zero.","Relação sem cabeçalho válido.","Relação de grau zero contendo a tupla vazia."]'::jsonb, 4, 'A tupla vazia é um valor de tupla válido e pode formar um corpo unitário.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.4, páginas 270–281 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3500a2c6-ab08-5a47-82fc-798cd561d38d', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'A definição de uma relvar estabelece principalmente:', '["Uma cópia por usuário.","Uma ordem permanente de impressão.","Uma representação binária universal.","O tipo de seus valores e as restrições aplicáveis.","Um resultado de consulta imutável."]'::jsonb, 3, 'A relvar recebe valores de relação compatíveis com sua declaração.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.5, páginas 282–288 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('02b6950c-ea62-580a-b3ab-faf213f04895', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Inserir, excluir e atualizar tuplas em uma relvar pode ser entendido como:', '["Renomear o catálogo.","Alterar a definição de todos os tipos envolvidos.","Atribuir um novo valor de relação à variável.","Modificar valores matemáticos constantes.","Trocar obrigatoriamente o esquema interno."]'::jsonb, 2, 'As operações mudam o valor atual da relvar, preservadas suas restrições.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.5, páginas 282–288 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('81103c6a-53b5-5bd7-b948-1585e796e73c', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Duas relvars distintas podem conter a mesma relação em determinado instante?', '["Sim, mas deixam de ser variáveis distintas.","Não, porque uma relação só pode pertencer a uma variável.","Não, porque nomes diferentes exigem conteúdos diferentes.","Sim, somente se não houver atributos.","Sim; igualdade de valores não implica identidade das variáveis."]'::jsonb, 4, 'A distinção valor/variável também se aplica às relações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.5, páginas 282–288 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1c147a20-234d-59ab-a827-d24e32d0d942', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Um atributo possui um valor composto de tipo definido pelo usuário. Isso, isoladamente, viola a ideia de um valor por atributo?', '["Não; a unidade é relativa ao tipo do atributo.","Sim, somente inteiros são atômicos.","Não, porque tipos não importam no modelo.","Sim, todo tipo composto exige linhas duplicadas.","Sim, todo valor deve ser um caractere."]'::jsonb, 0, 'Complexidade interna não significa presença de vários valores independentes no atributo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.4, páginas 270–281 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5a484fec-4df1-57c4-b1d7-335255d9b66b', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Uma tupla contém um atributo extra ausente do cabeçalho de R. Ela pode integrar diretamente o corpo de R?', '["Não, porque R não pode ter corpo.","Sim, porque cabeçalhos são apenas decoração.","Sim, desde que seja texto.","Sim, se o atributo extra estiver ao final.","Não, pois não possui o cabeçalho requerido."]'::jsonb, 4, 'O corpo exige tuplas do mesmo tipo definido pelo cabeçalho.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.3, páginas 267–269 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2f4af7e7-4aa5-529c-8091-41f29c82c4dd', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Qual diferença entre SQL e relações matemáticas é destacada no capítulo?', '["SQL não possui colunas.","SQL pode admitir linhas duplicadas.","Relações matemáticas têm ordem de inserção obrigatória.","Relações matemáticas exigem duplicatas.","SQL não permite restrições."]'::jsonb, 1, 'Tabelas SQL e relações não devem ser tratadas como conceitos perfeitamente idênticos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.6, páginas 289–297 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('64a06671-68f1-556f-b9ae-fb04d4a9de10', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Por que não se deve generalizar a posição ordinal de colunas SQL para atributos relacionais?', '["Porque linhas SQL são sempre conjuntos matemáticos.","Porque SQL só trabalha com uma coluna.","Porque atributos relacionais não possuem tipos.","No modelo relacional, a identidade do atributo é nominal, não posicional.","Porque a ordem elimina duplicatas."]'::jsonb, 3, 'O capítulo distingue o tratamento de linhas SQL e o de tuplas relacionais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.6, páginas 289–297 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('47ee590c-366e-59fc-887f-4329db06d36e', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'R e S têm o mesmo cabeçalho e exatamente as mesmas tuplas, exibidas em ordens diferentes. Logo:', '["R e S são relações iguais.","A igualdade exige os mesmos índices.","R e S possuem necessariamente tipos diferentes.","Sua igualdade depende do primeiro registro físico.","Apenas uma delas pode ser relação."]'::jsonb, 0, 'Igualdade relacional depende de cabeçalho e corpo, não de ordenação ou armazenamento.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 6, seção 6.4, páginas 270–281 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d7910369-cd99-5f2d-9504-8b65edced0f6', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Por que o fechamento é importante para expressões relacionais aninhadas?', '["Todas as operações passam a ter custo igual.","Todo resultado se torna automaticamente persistente.","O resultado de uma operação pode servir de entrada a outra.","Impede consultas sobre relações vazias.","Dispensa nomes de atributos."]'::jsonb, 2, 'O fechamento sustenta a composição de operadores relacionais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.2, páginas 315–317 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2b039bcc-cf96-5f95-ad34-bb675b22f451', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Uma autojunção precisa distinguir dois atributos originalmente homônimos. Qual operador auxilia?', '["COMMIT.","ROLLBACK.","RENAME.","DELETE.","GRANT."]'::jsonb, 2, 'A renomeação evita conflitos e explicita correspondências de atributos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.3, páginas 318–321 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b821485b-e439-532d-ac20-5d10bffc4c1e', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Fácil', 'R={1,2} e S={2,3} são relações unárias compatíveis. Qual é R UNION S?', '["{2}.","{1,2,3}.","{3}.","{1,2,2,3}.","{1}."]'::jsonb, 1, 'A união contém as tuplas presentes em qualquer operando, sem multiplicidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('50afad9a-9897-511c-b4b7-a1405ef880f0', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'R={1,2} e S={2,3}, com mesmo cabeçalho. Qual é R INTERSECT S?', '["{1}.","{2}.","{1,2,3}.","Vazio.","{3}."]'::jsonb, 1, 'A interseção conserva apenas tuplas presentes nos dois operandos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fd121816-43bb-59e2-83f9-a73df8aa7a66', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Fácil', 'R={1,2} e S={2,3}, com mesmo cabeçalho. Qual é R MINUS S?', '["{2}.","{3}.","{2,3}.","{1,2,3}.","{1}."]'::jsonb, 4, 'A diferença conserva tuplas do primeiro operando ausentes do segundo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a454f649-8f47-57e8-9432-87b6514ce6ff', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'União relacional exige que seus operandos possuam:', '["Cabeçalhos compatíveis segundo as regras de tipagem.","Os mesmos índices.","A mesma localização física.","Uma tupla em comum.","A mesma cardinalidade."]'::jsonb, 0, 'A união precisa produzir uma relação homogênea, preservando o fechamento.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cab5d505-cceb-5cb0-960b-8417dd1b2650', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'R tem três tuplas e S quatro, com atributos disjuntos. R TIMES S terá quantas tuplas?', '["7.","1.","3.","12.","4."]'::jsonb, 3, 'O produto cartesiano combina cada tupla de R com cada tupla de S.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f4f060b6-d958-53b3-8906-fffa04086a28', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Uma restrição sobre R pode aumentar sua cardinalidade?', '["Sim, quando o predicado é falso.","Não, porque remove todos os atributos.","Sim, sempre duplica tuplas aprovadas.","Não; seu corpo é subconjunto do corpo de R.","Sim, se houver índices."]'::jsonb, 3, 'Seleção filtra tuplas sem criar novas combinações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8d2fc26e-9cb4-55ed-9e0b-7f24c8c209ae', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Projetar R sobre menos atributos pode reduzir sua cardinalidade por quê?', '["A projeção acrescenta valores nulos.","Tuplas antes distintas podem produzir a mesma tupla projetada.","O grau deve ser igual à cardinalidade.","Todo atributo removido exclui uma linha.","A projeção ordena fisicamente os registros."]'::jsonb, 1, 'A projeção relacional elimina multiplicidade porque seu resultado é um conjunto.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('768b28d6-40d1-5e2b-b192-7c8463b42a58', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Uma junção natural usa atributos comuns para:', '["Combinar tuplas cujos valores nesses atributos coincidam.","Criar duas cópias de cada atributo comum.","Escolher somente a primeira tupla de cada relação.","Somar automaticamente seus valores.","Remover todos os atributos não comuns."]'::jsonb, 0, 'A correspondência ocorre nos atributos comuns compatíveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4b323774-2dfd-50b2-a196-33aec0ab828d', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Uma consulta pede candidatos inscritos em todos os cursos de um conjunto. Qual operador clássico corresponde ao requisito universal?', '["Divisão.","Renomeação.","União.","Restrição sem condição.","Produto sem filtro."]'::jsonb, 0, 'Divisão modela consultas em que se exige associação com todos os elementos de um conjunto.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.4, páginas 322–336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0b4cd2d1-b953-558e-bda8-3264d8419e51', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Qual operador, em geral, não é comutativo?', '["União.","Produto com atributos disjuntos.","Junção natural.","Diferença.","Interseção."]'::jsonb, 3, 'R MINUS S e S MINUS R podem produzir resultados diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.7, páginas 344–346 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('354bdf7a-fb4d-543f-8159-f804e58c9dd9', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Para relações compatíveis, R UNION R resulta em:', '["Um valor escalar.","Uma relação de grau dobrado.","Uma relação com o dobro das tuplas.","R.","Uma relação vazia."]'::jsonb, 3, 'A união é idempotente no modelo de conjuntos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.7, páginas 344–346 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f34f7a33-ad37-5883-ae6a-7123e9012a22', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Uma semijunção de R com S retorna:', '["Apenas tuplas de S sem correspondência.","Uma contagem escalar sem cabeçalho.","O produto integral sem filtro.","Todos os atributos de R e S obrigatoriamente.","Tuplas de R que encontram correspondência em S, preservando o cabeçalho de R."]'::jsonb, 4, 'A semijunção testa existência de associação sem incorporar os atributos exclusivos de S.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.8, páginas 347–357 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('07f2307e-6319-56d2-a442-3887c3d6a08b', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Para obter entidades de R sem correspondência em S, o operador adicional apropriado é:', '["SEMIMINUS.","RENAME.","SEMIJOIN.","SUMMARIZE.","EXTEND."]'::jsonb, 0, 'A semidiferença conserva as tuplas do primeiro operando que não encontram correspondência.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.8, páginas 347–357 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('adb6631b-303b-5696-83f3-cf9f79f254f0', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Qual operador acrescenta atributos calculados a partir dos existentes?', '["COMMIT.","EXTEND.","RENAME, exclusivamente.","INTERSECT.","MINUS."]'::jsonb, 1, 'EXTEND deriva novos valores e amplia o cabeçalho do resultado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.8, páginas 347–357 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3ada7214-f1cd-5d7f-b28d-bf462b87b441', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Qual operador permite produzir totais por grupos?', '["RENAME.","ROLLBACK.","SUMMARIZE.","MINUS, exclusivamente.","TIMES, exclusivamente."]'::jsonb, 2, 'Totalização calcula agregados para os grupos especificados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.8, páginas 347–357 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('144b9458-ab15-5b0d-b85a-e12e689d6adf', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'A partir de ligações diretas entre cidades, qual operador adicional pode calcular alcançabilidade transitiva?', '["RENAME.","EXTEND sem recursão.","TCLOSE.","UNION de uma relação consigo mesma.","PROJECT sobre um atributo."]'::jsonb, 2, 'O fechamento transitivo inclui ligações obtidas por caminhos de vários passos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.8, páginas 347–357 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c66e9167-c727-57b4-be2f-b7e6421496a3', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'GROUP pode reunir atributos de várias tuplas em:', '["Uma senha compartilhada.","Um novo índice externo.","Uma transação sem commit.","Um ponteiro físico obrigatório.","Um atributo cujo valor é uma relação."]'::jsonb, 4, 'Agrupamento relacional permite construir valores relacionais aninhados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.9, páginas 358–361 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6c4fd3c1-54fb-5124-8eef-4b00fee2a846', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Qual operação faz o movimento inverso ao agrupamento de um atributo relacional?', '["COMMIT.","RENAME.","DROP TYPE.","REVOKE.","UNGROUP."]'::jsonb, 4, 'O desagrupamento expande o conteúdo do atributo relacional para o resultado correspondente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 7, seção 7.9, páginas 358–361 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('954da477-9e67-5579-bd6b-ef145ca70f46', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'O cálculo relacional expressa uma consulta principalmente por meio de:', '["Condições que definem as tuplas desejadas.","Permissões de rede.","Procedimentos de backup.","Endereços físicos de registros.","Sequências obrigatórias de leitura de disco."]'::jsonb, 0, 'O cálculo descreve propriedades do resultado, em vez de explicitar uma composição algébrica.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.1, páginas 374–376 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2fa32339-5352-5bf8-9356-7858bc4df38c', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Nas formulações relacionais consideradas no capítulo, álgebra e cálculo são:', '["Equivalentes em custo físico de execução.","Idênticos em sintaxe.","Equivalentes em poder de expressão.","Distintos porque só a álgebra consulta dados.","Distintos porque só o cálculo produz relações."]'::jsonb, 2, 'Equivalência expressiva não implica sintaxe ou planos físicos idênticos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.4, páginas 392–397 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('12775ab7-eda2-5cc5-a8b4-cc5b4076ecec', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'No cálculo de tuplas, variáveis de intervalo representam:', '["Comandos de autorização.","Transações em execução.","Tuplas das relações sobre as quais variam.","Somente nomes de índices.","Somente valores de endereço físico."]'::jsonb, 2, 'As variáveis permitem formular condições sobre atributos das tuplas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.2, páginas 377–387 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('55bb7396-a087-5766-a86b-30fcc269701b', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'No cálculo de domínios, as variáveis variam sobre:', '["Valores dos domínios correspondentes.","Usuários autorizados.","Relvars completas, exclusivamente.","Planos de execução.","Páginas de armazenamento."]'::jsonb, 0, 'Essa é a distinção principal em relação às variáveis de tuplas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.7, páginas 413–416 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4b0a8697-6bc0-51d9-8e6c-bfa4b1fc2928', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Fácil', 'O quantificador EXISTS expressa que uma condição vale para:', '["Todas as atribuições, obrigatoriamente.","Nenhuma atribuição.","Exatamente duas atribuições.","Apenas a primeira linha física.","Pelo menos uma atribuição da variável quantificada."]'::jsonb, 4, 'A existência não impõe unicidade nem depende da ordem de armazenamento.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.2, páginas 377–387 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8c6ce916-26b1-5456-b9e9-cf474903632f', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Fácil', 'O quantificador FORALL expressa que uma condição vale para:', '["Pelo menos uma, sem outra exigência.","Somente a atribuição de maior valor.","Uma atribuição escolhida aleatoriamente.","Todas as atribuições no domínio de quantificação.","Nenhuma atribuição."]'::jsonb, 3, 'A quantificação universal exige que não exista contraexemplo no domínio considerado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.2, páginas 377–387 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8e221f1f-585e-5190-9289-b22d9a264699', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Difícil', 'Em lógica bivalorada, qual forma equivale a FORALL x P(x)?', '["EXISTS x P(x).","P(x) AND NOT P(x).","NOT EXISTS x NOT P(x).","NOT EXISTS x P(x).","EXISTS x NOT P(x)."]'::jsonb, 2, 'Afirmar que todos satisfazem P equivale a negar a existência de um contraexemplo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.2, páginas 377–387 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6064ac7e-2fee-5f81-b991-d3a9c649bc3b', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Em EXISTS x P(x), a ocorrência de x sob esse quantificador é:', '["Uma constante escalar.","Livre.","Um nome de índice.","Ligada.","Uma relvar básica."]'::jsonb, 3, 'O quantificador vincula as ocorrências de sua variável dentro do respectivo escopo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.2, páginas 377–387 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('93779510-4763-52c8-a9e7-40d85f6560da', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Uma variável livre em uma expressão de consulta não deve ser confundida com:', '["Um símbolo que precisa de interpretação.","Uma variável citada em uma condição.","Uma referência sujeita às regras de escopo.","Uma variável cuja ocorrência está ligada por um quantificador.","Um elemento que pode participar da definição do resultado."]'::jsonb, 3, 'A distinção depende do escopo de quantificação, não do nome escolhido.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.2, páginas 377–387 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f629ec7e-5c90-5940-b72a-c4a8bd7b7919', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Para selecionar alunos com idade acima de 18 e matrícula ativa, a condição deve usar:', '["Igualdade entre nome e idade.","Quantificação existencial sem predicado.","Negação dos dois requisitos.","Disjunção obrigatória.","Conjunção entre os dois requisitos."]'::jsonb, 4, 'AND exige o atendimento simultâneo das condições.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.2, páginas 377–387 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8475aaae-0582-5445-bac8-834f4654762c', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Para obter alunos sem inscrições, qual condição de existência é adequada?', '["Existe um aluno sem nome.","Existe qualquer inscrição de qualquer aluno.","Toda inscrição pertence a outro curso, sem relacioná-la ao aluno.","O total geral de inscrições é positivo.","Não existe inscrição ligada ao aluno."]'::jsonb, 4, 'A negação de existência deve correlacionar a inscrição ao aluno candidato ao resultado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.3, páginas 388–391 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3a2bedaa-36d4-563e-966d-638a56b6be38', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Para obter alunos inscritos em algum curso de redes, a consulta precisa:', '["Comparar somente a quantidade de tabelas.","Relacionar aluno, inscrição e curso e exigir existência de correspondência.","Excluir os alunos que possuem inscrições.","Exigir que todos os cursos sejam de redes.","Consultar nomes sem identificar a associação."]'::jsonb, 1, 'O predicado existencial precisa representar as ligações relevantes do domínio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.3, páginas 388–391 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5ff8d4ac-1a08-5d6d-aacd-398493f80b37', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Uma consulta exige todos os cursos obrigatórios. Se um aluno não tem inscrição em um deles, ele:', '["É um contraexemplo à condição universal e deve ser excluído.","Deve ser incluído por ter alguma inscrição.","Deve receber inscrição automática.","Passa a ser uma constante lógica.","Só pode ser excluído se houver duplicatas."]'::jsonb, 0, 'Uma única falha no conjunto exigido torna falsa a condição universal para esse aluno.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.3, páginas 388–391 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b4e95329-7f35-5e94-8047-c6c42cf0e99f', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Difícil', 'Considere o requisito: todo elemento de um conjunto vazio satisfaz P. Em lógica clássica, ele é:', '["Verdadeiro somente se P for falso.","Verdadeiro por vacuidade.","Indefinido por ausência de linhas físicas.","Equivalente a existir exatamente um elemento.","Sempre falso."]'::jsonb, 1, 'Não há elemento no conjunto vazio que viole P.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.3, páginas 388–391 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('66d8408b-65e1-5bf5-a040-4341b5c31cf9', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Converter uma expressão do cálculo em uma expressão algébrica equivalente deve preservar:', '["O resultado lógico para os mesmos dados.","A quantidade de acessos a disco.","O algoritmo de junção específico.","O texto original.","A ordem de leitura física."]'::jsonb, 0, 'A tradução preserva significado, mas pode admitir diferentes implementações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.4, páginas 392–397 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9f206358-87b4-5733-bb4c-74d2b4c8d0df', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Uma expressão no resultado calcula preço multiplicado por quantidade. Isso ilustra:', '["Impossibilidade de tipar o resultado.","Ausência de fechamento.","Obrigação de usar apenas atributos sem cálculos.","Atualização automática da relação de origem.","Capacidade de produzir valores derivados nas expressões do cálculo."]'::jsonb, 4, 'Expressões e operadores escalares permitem calcular valores a partir dos dados consultados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.5, páginas 398–399 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('00605379-d263-5def-bd19-98c7eb01bf2f', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'O SQL, na análise de Date, deriva exclusivamente do cálculo relacional?', '["Sim, inclusive nos detalhes físicos.","Sim, sem qualquer influência algébrica.","Não; reúne características de cálculo, álgebra e outras construções.","Sim, porque JOIN não é algébrico.","Não, porque não permite consultas."]'::jsonb, 2, 'A linguagem SQL não é uma transcrição pura de um único formalismo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.6, páginas 400–412 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4374dd17-db4d-5e74-9d47-73e5737244fb', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Fácil', 'Uma condição de pertinência no cálculo de domínios testa principalmente:', '["Se um índice está fisicamente ordenado.","Se existe tupla na relação com os valores especificados.","Se duas máquinas estão conectadas.","Se toda transação foi confirmada.","Se o usuário conhece uma senha."]'::jsonb, 1, 'A condição relaciona valores de domínio às tuplas de uma relação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.7, páginas 413–416 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('04d43332-9711-5bfb-a0e6-233d56bdf681', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Qual linguagem é associada no capítulo principalmente ao cálculo de domínios?', '["Uma ferramenta de backup.","Query-by-Example.","Um sistema de arquivos.","Uma linguagem de montagem.","Um protocolo de rede."]'::jsonb, 1, 'QBE usa modelos de tabelas e elementos de exemplo para expressar consultas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.8, páginas 417–422 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d9bd029c-c89b-5102-b736-aac219617f70', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Em QBE, repetir um mesmo elemento de exemplo em campos relacionados permite:', '["Duplicar fisicamente todas as linhas.","Confirmar alterações pendentes.","Substituir o tipo de todos os atributos.","Expressar correspondência entre os valores desses campos.","Criar automaticamente um índice exclusivo."]'::jsonb, 3, 'A repetição de variáveis permite estabelecer condições entre tabelas do exemplo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 8, seção 8.8, páginas 417–422 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fb803f47-4443-5ea6-b0af-75b26e61429c', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Uma restrição com parâmetros ainda não substituídos por valores é um:', '["Predicado.","Plano de disco.","Cursor.","Commit.","Backup."]'::jsonb, 0, 'Ao instanciar parâmetros, o predicado dá origem a uma proposição avaliável.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.3, páginas 441–442 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('28df7380-ff27-5eaa-bde6-e91e927f7730', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'O predicado de uma relvar combina suas restrições por:', '["Ordenação física.","Conjunção lógica.","Concatenação de nomes.","Soma de cardinalidades.","Disjunção exclusiva."]'::jsonb, 1, 'Todas as restrições aplicáveis devem ser simultaneamente satisfeitas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.4, páginas 443–444 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4d3c5689-c7f5-524f-aac8-eff3d8616da6', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'A Regra Áurea da integridade impede uma atualização que:', '["Modifique uma tabela vazia.","Use uma expressão aninhada.","Altere qualquer valor persistente.","Faça o predicado do banco resultar falso.","Consulte mais de uma relvar."]'::jsonb, 3, 'Atualizações são admissíveis apenas se preservarem as restrições do banco.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.4, páginas 443–444 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('eff531fc-fa7a-5708-a4bc-b18bee6779d6', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Uma restrição interna é suficiente para garantir correspondência perfeita com o mundo real?', '["Sim, desde que exista uma chave primária.","Não; o sistema verifica o que foi formalizado, não toda a realidade externa.","Não, porque restrições nunca são verificáveis.","Sim, pois consistência e verdade externa são idênticas.","Sim, se houver apenas uma tabela."]'::jsonb, 1, 'As regras declaradas podem não capturar erros ou mudanças da realidade externa.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.6, páginas 447–449 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('883e8123-e156-52c5-8704-1a0d69174296', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Um banco satisfaz todas as regras declaradas, mas contém o telefone antigo de uma pessoa. Ele pode estar:', '["Correto externamente, pois possui formato válido.","Necessariamente normalizado até 5FN.","Inconsistente por definição, ainda que nenhuma regra seja violada.","Sem qualquer predicado.","Consistente internamente e incorreto em relação à realidade."]'::jsonb, 4, 'Consistência com restrições não garante que cada fato corresponda à situação real.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.7, páginas 450–451 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4a873623-3cb4-5469-b2c6-850d6a802f4e', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'A condição saldo maior ou igual a zero em uma relvar é exemplo de:', '["Descrição de rede.","Permissão de acesso por usuário.","Operação de backup.","Restrição sobre os dados admissíveis.","Plano físico de busca."]'::jsonb, 3, 'Integridade trata da validade dos estados, diferentemente de autorização.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.9, páginas 454–457 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('be3ecf5b-e537-51a3-841d-a06cd25ffc15', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Fácil', 'Uma chave candidata é uma superchave que também possui:', '["Uma referência externa obrigatória.","Exatamente um atributo.","Irredutibilidade.","Ordenação física.","Tipo numérico obrigatório."]'::jsonb, 2, 'Nenhum subconjunto próprio da chave candidata mantém a identificação única.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('75122044-b18b-50d1-9906-b848928e67d8', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Se {A} já identifica unicamente as tuplas, {A,B} é necessariamente uma chave candidata?', '["Sim, pois mais atributos aumentam a minimalidade.","Não, porque superchaves são proibidas.","Sim, desde que B seja texto.","Sim, todo conjunto único é candidato.","Não; ela é uma superchave não mínima."]'::jsonb, 4, 'Acrescentar B preserva unicidade, mas destrói a irredutibilidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cf27f673-bd22-5bd3-a31a-3b8303f66dca', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Fácil', 'Uma relvar pode possuir duas chaves candidatas diferentes?', '["Não, porque todos os atributos precisam ser numéricos.","Não; só existe uma combinação única possível.","Sim; uma delas pode ser designada primária.","Sim, somente se tiver uma tupla.","Sim, mas ambas deixam de ser candidatas."]'::jsonb, 2, 'A escolha de chave primária não elimina outras chaves candidatas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2c1414ca-5a8e-511e-b5be-0e3df4c841c7', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Qual característica de uma chave candidata é independente da escolha da chave primária?', '["Possuir o menor número de bytes entre todas as chaves.","Ser sempre a primeira coluna.","Estar fisicamente ordenada.","Ser criada automaticamente por uma junção.","Identificar unicamente as tuplas com um conjunto irredutível de atributos."]'::jsonb, 4, 'Irredutibilidade não significa escolher a chave de menor tamanho físico.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c7a63035-961b-5ce4-abb4-687052e76a86', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Fácil', 'Uma chave estrangeira expressa principalmente:', '["Uma exigência de correspondência com uma chave referenciada.","Uma garantia de confidencialidade.","Uma permissão de exclusão.","Uma obrigação de ordenar o arquivo.","Uma cópia integral de outra relação."]'::jsonb, 0, 'A integridade referencial impede referências incompatíveis com o estado da relação referenciada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('25309e77-a2fe-557b-862f-5ac6c79db82a', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Um item referencia um pedido inexistente. Qual categoria de integridade é diretamente afetada?', '["Somente a ordenação de saída.","Referencial.","Somente a duração da transação.","Somente a codificação física.","Somente a segurança de leitura."]'::jsonb, 1, 'A referência precisa corresponder ao objeto admitido pela restrição declarada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bf27c216-bc16-5a3c-a84d-e85a5be83c93', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Uma exclusão com regra RESTRICT deve fazer o quê quando existirem dependentes impeditivos?', '["Substituir todas as chaves por zero.","Excluir silenciosamente os dependentes.","Rejeitar a exclusão.","Desativar a chave estrangeira.","Confirmar antes de verificar referências."]'::jsonb, 2, 'RESTRICT bloqueia a operação que violaria a referência, em vez de propagá-la.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1ea07c02-35ba-5dd5-9724-c63841d4b3e9', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Uma regra ON DELETE CASCADE determina:', '["Propagação da exclusão aos registros dependentes alcançados pela regra.","Rejeição de toda exclusão, mesmo sem dependentes.","Cópia do registro para outra tabela.","Propagação de permissões a todos os usuários.","Conversão de todas as referências em índices."]'::jsonb, 0, 'A ação em cascata integra a política de manutenção da integridade referencial.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('91114071-69b9-5be8-9c25-93da83c7dadd', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Um trigger associa uma ação a:', '["Uma função de rede obrigatória.","Um nome de usuário sem evento.","Um evento especificado no banco.","Toda impressão de tela.","Uma única posição fixa de disco."]'::jsonb, 2, 'Gatilhos executam ações em resposta aos eventos para os quais foram definidos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.11, páginas 470–473 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7e2fcbb6-5bd0-56ff-aa5d-8cfa40eaaa6b', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Por que um trigger não deve ser confundido com uma restrição declarativa?', '["Ele especifica uma ação disparada por evento, não apenas uma condição de validade.","Porque não depende de eventos.","Porque não possui condições de execução.","Porque nunca pode alterar dados.","Porque substitui todas as chaves."]'::jsonb, 0, 'Ações procedimentais e declarações de estados admissíveis têm contratos diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.11, páginas 470–473 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b32e66c0-ce4e-5697-85ad-4289f3273c20', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Na abordagem defendida por Date, cabe ao usuário programar a ordem de todas as verificações de restrições?', '["Sim, usando sempre cursores.","Não; o SGBD deve determinar as verificações necessárias.","Sim, para cada consulta de leitura.","Não, porque nenhuma verificação é necessária.","Sim, por meio da ordem física das linhas."]'::jsonb, 1, 'O autor defende tratamento declarativo e verificação pelo sistema.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.5, páginas 445–446 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8ee7f61c-6901-5435-9c41-00f278422283', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Uma atualização feita por uma visão pode ignorar as restrições das relvars envolvidas?', '["Sim, se o usuário não conhecer as tabelas.","Sim, porque visões não possuem ligação com dados básicos.","Não, porque visões nunca podem ser consultadas.","Não; os efeitos precisam preservar a integridade do banco.","Sim, pois fechamento dispensa restrições."]'::jsonb, 3, 'A interface usada para atualizar não elimina os requisitos de integridade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.8, páginas 452–453 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4fcb00a4-7d65-5dc5-9c82-4a46bd4f644b', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Fácil', 'Qual construção SQL representa diretamente uma condição de validade dos dados?', '["COMMIT.","ORDER BY.","GRANT.","EXPLAIN.","CHECK."]'::jsonb, 4, 'CHECK declara um predicado que os dados devem satisfazer segundo as regras SQL.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.12, páginas 474–480 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('04359e3d-5f07-522c-9254-18719b7b053d', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Adicionar uma restrição UNIQUE em outra combinação de colunas serve principalmente para:', '["Autorizar qualquer usuário a alterar linhas.","Transformar a tabela em visão.","Tornar a tabela obrigatoriamente ordenada.","Impedir repetição dessa combinação segundo a semântica SQL.","Criar uma referência externa obrigatória."]'::jsonb, 3, 'Unicidade é uma condição de integridade, não uma garantia de apresentação ou acesso.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 9, seção 9.10, páginas 458–469 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9c097f64-d5fc-576e-aaf3-349c536203ac', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Fácil', 'Uma visão relacional é essencialmente:', '["Um arquivo de log.","Um índice exclusivo.","Uma transação suspensa.","Uma cópia física obrigatória.","Uma expressão relacional nomeada."]'::jsonb, 4, 'A visão constitui uma relvar derivada virtual definida por uma expressão.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.1, páginas 501–505 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4470a360-7ff6-56b3-b6be-cc1a4c492ca2', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Consultar uma visão exige necessariamente armazenar previamente todas as suas linhas?', '["Não, porque visões não possuem resultado.","Sim, uma vez por usuário.","Não; sua definição pode ser expandida durante o processamento.","Sim, como requisito do modelo.","Sim, antes de qualquer inserção no banco."]'::jsonb, 2, 'Visões virtuais podem ser avaliadas a partir das relvars de origem.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.1, páginas 501–505 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6bde35af-ca51-5ef2-87bb-8781b33fba07', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Na implementação conceitual por substituição, consultar uma visão consiste em:', '["Desativar todos os predicados.","Substituir seu nome pela expressão que a define.","Renomear fisicamente todos os arquivos.","Usar apenas o último backup.","Excluir sua definição após cada leitura."]'::jsonb, 1, 'O fechamento permite integrar a expressão definidora à consulta externa.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.3, páginas 511–512 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6a728bce-6a8d-57a1-9fb7-dff7c4ecbbd7', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Ocultar o atributo salário em uma visão contribui principalmente para:', '["Normalizar automaticamente a tabela.","Criptografar os valores armazenados.","Garantir que salários estejam corretos.","Restringir a informação apresentada aos usuários daquela interface.","Eliminar qualquer possibilidade de acesso por outros canais."]'::jsonb, 3, 'A visão pode limitar exposição, mas segurança completa depende também dos demais privilégios.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.2, páginas 506–510 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d99f06a4-197d-5fa2-b34c-7dc4ed7a968c', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Manter uma interface de visão estável após reestruturar tabelas básicas favorece:', '["Obrigatoriedade de navegação física.","Duplicação não controlada.","Mudança automática de todas as aplicações.","Eliminação de tipos.","Independência de dados lógica."]'::jsonb, 4, 'A visão pode preservar a forma de acesso esperada pelas aplicações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.2, páginas 506–510 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('36c589f8-5114-5ed1-858e-3599b6aca301', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Fácil', 'Dar um nome a uma consulta complexa usada em vários relatórios serve como:', '["Abreviação reutilizável e simplificação da interface.","Obrigação de copiar o resultado.","Substituição das restrições de origem.","Conversão do banco em arquivo sequencial.","Confirmação automática de transações."]'::jsonb, 0, 'A visão evita repetir a mesma expressão em vários pontos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.2, páginas 506–510 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9d89e962-a2b4-58e0-bf7e-c2df455ac664', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'O princípio de permutabilidade discutido por Date defende que aplicações não dependam indevidamente de:', '["Predicados do resultado.","Significado dos dados.","Seus requisitos de integridade.","Tipos declarados de atributos.","Uma relvar ser básica ou derivada."]'::jsonb, 4, 'O tratamento uniforme busca reduzir diferenças artificiais entre interfaces básicas e virtuais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.2, páginas 506–510 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6a9c6896-74e4-5423-8390-026cafb86080', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Atualizar uma visão envolve necessariamente avaliar:', '["Somente a quantidade de índices.","Quais alterações nas relvars de origem correspondem à operação e preservam restrições.","Apenas o nome do usuário.","A velocidade da conexão, sem considerar os dados.","Somente a ordem das colunas na tela."]'::jsonb, 1, 'Atualização por visão precisa de semântica definida e efeitos válidos nas fontes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.4, páginas 513–534 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a81b0fb4-db04-5588-a885-6236f2993f69', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Uma visão filtra produtos com preço acima de 100. Com CHECK OPTION, inserir preço 80 pela visão deve:', '["Excluir todos os produtos baratos.","Ser aceito e automaticamente convertido para 101.","Alterar a definição da visão.","Ser rejeitado por não satisfazer a condição da visão.","Confirmar sem verificar o predicado."]'::jsonb, 3, 'CHECK OPTION impede que alterações pela visão produzam linhas fora de sua condição.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.4, páginas 513–534 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9b80e03f-9571-5924-921f-10e6e0349ea3', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Sem CHECK OPTION, uma atualização por visão pode fazer uma linha deixar de aparecer nela?', '["Sim, mas a tabela básica será sempre eliminada.","Não, porque visões não usam filtros.","Sim, somente se o banco estiver offline.","Não, toda visão possui esse controle implicitamente.","Sim, quando a alteração deixa de satisfazer seu filtro e a operação é admitida."]'::jsonb, 4, 'O desaparecimento da visão não significa necessariamente exclusão da linha básica.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.6, páginas 538–542 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('06052e57-b5f0-5ed8-bed0-710721059343', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Por que uma visão de totais por setor exige cuidado ao receber atualizações?', '["Um novo total não determina por si só como distribuir alterações entre as linhas básicas.","Porque totais não podem ser consultados.","Porque agregação elimina o esquema do banco.","Porque todos os resultados agregados são índices.","Porque toda visão agregada é uma cópia física."]'::jsonb, 0, 'Atualizações precisam de correspondência definida, não de uma distribuição arbitrária dos valores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.4, páginas 513–534 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c0df41c7-b0a0-5e9a-ac4b-efad9f7ed153', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Uma visão de projeção omite um atributo obrigatório sem valor padrão. Qual dificuldade pode surgir ao inserir por ela?', '["O tipo dos atributos visíveis desaparece.","A projeção passa a ordenar fisicamente a tabela.","A inserção vira automaticamente uma exclusão.","Faltar informação necessária para construir uma tupla básica válida.","A unicidade deixa de poder ser declarada."]'::jsonb, 3, 'As restrições das fontes continuam aplicáveis às operações realizadas pela visão.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.4, páginas 513–534 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7f8bb274-37cc-58f9-91dd-60f1f3362d23', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Uma visão junta pedidos e clientes. Alterar um atributo de cliente pode afetar a apresentação de vários pedidos porque:', '["Cada linha da visão é uma cópia independente obrigatória.","Pedidos e clientes devem ter chaves idênticas.","Várias tuplas da junção podem referir-se ao mesmo cliente.","Junções sempre duplicam registros básicos.","Visões não preservam correspondências."]'::jsonb, 2, 'A multiplicidade de correspondências precisa ser considerada na semântica de atualização.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.4, páginas 513–534 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('79ef33a0-b787-574a-8423-4a4a21d0d316', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Excluir uma linha de uma visão de junção deve significar apagar todas as entidades envolvidas?', '["Sim, sempre em todas as tabelas.","Sim, pois junção é produto físico.","Não; os efeitos dependem de regras de atualização e restrições bem definidas.","Não, porque uma visão de junção não pode ser lida.","Sim, inclusive entidades não relacionadas."]'::jsonb, 2, 'Não se deve deduzir uma política de exclusão apenas da aparência do resultado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.4, páginas 513–534 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dcbe675f-2ab2-5406-bcea-75e7d34e8183', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Fácil', 'Qual diferença caracteriza um snapshot em relação a uma visão virtual comum?', '["Ele substitui a chave primária.","Ele mantém uma cópia materializada de dados de um instante ou atualização.","Ele é necessariamente atualizado a cada leitura.","Ele representa apenas permissões.","Ele não possui resultado consultável."]'::jsonb, 1, 'Snapshots introduzem armazenamento de resultados e uma política de renovação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.5, páginas 535–537 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5c7bf455-61d6-595d-aed0-73cce33bcb49', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Uma cópia materializada é renovada apenas à noite. Durante o dia ela pode:', '["Eliminar todas as transações.","Refletir um estado anterior ao das fontes.","Impedir alterações nas tabelas básicas.","Garantir dados mais recentes que as fontes.","Tornar irrelevante seu horário de renovação."]'::jsonb, 1, 'A atualidade depende do mecanismo e da periodicidade de manutenção.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.5, páginas 535–537 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('31946474-3ae6-5990-af96-c05d7b25b4a3', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Qual compromisso surge ao materializar um resultado de consulta?', '["Eliminar todos os custos de atualização.","Garantir ausência de redundância.","Ganhar desempenho de leitura ao custo de armazenamento e manutenção.","Tornar inúteis as consultas às fontes.","Dispensar qualquer estratégia de renovação."]'::jsonb, 2, 'Materialização mantém informação derivada que precisa ser administrada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.5, páginas 535–537 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0d9fc9b1-63ca-5ebc-a89d-c8ff8808f670', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Descartar uma visão virtual implica necessariamente excluir os dados das tabelas que ela consulta?', '["Não; remove-se a definição da visão, respeitadas as dependências aplicáveis.","Sim, mas apenas dados com valores numéricos.","Não, pois visões não possuem definições.","Sim, sempre todas as linhas.","Sim, porque a visão possui exclusivamente os dados."]'::jsonb, 0, 'Definição derivada e conteúdo das fontes são objetos distintos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.6, páginas 538–542 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a67916fa-b28a-57ac-b355-8b78215b8b51', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Uma visão V2 consulta V1, que consulta uma relvar básica. Conceitualmente, a busca pode:', '["Exigir que V1 seja uma cópia física.","Consultar apenas o nome de V2 sem expressão.","Transformar V2 em chave estrangeira.","Expandir sucessivamente as definições até as fontes.","Ignorar o filtro de V1."]'::jsonb, 3, 'Composição e substituição permitem construir interfaces derivadas em camadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.3, páginas 511–512 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8a30bd17-a0ae-5b5d-ba6d-95d14f443eae', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Uma aplicação consulta somente uma visão com nomes estáveis. Renomear colunas básicas pode ser transparente se:', '["A definição da visão for ajustada preservando seu contrato externo.","O usuário adivinhar os novos nomes.","A visão também mudar todos os nomes expostos.","Todas as linhas forem duplicadas.","Os tipos forem removidos."]'::jsonb, 0, 'Preservar o contrato da visão pode isolar a aplicação da reestruturação subjacente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 10, seção 10.2, páginas 506–510 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e61bbb5a-c810-55a0-98f7-87a36590b7d2', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'A dependência funcional A → B estabelece que:', '["Tuplas iguais em A devem ser iguais em B.","B deve ser chave primária.","A precisa ser numérico.","Tuplas iguais em B devem ser iguais em A.","A e B devem ter o mesmo tipo."]'::jsonb, 0, 'A determina B, mas a dependência inversa não é implicada automaticamente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.2, páginas 560–563 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('01d18e48-3108-52ac-bd50-5bfd50f755c4', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Qual par de tuplas viola A → B?', '["(A=4,B=7) e (A=5,B=7).","(A=5,B=9) e (A=6,B=9).","(A=4,B=7) e (A=5,B=9).","(A=4,B=7) e (A=6,B=7).","(A=4,B=7) e (A=4,B=9)."]'::jsonb, 4, 'O mesmo determinante A aparece associado a valores distintos de B.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.2, páginas 560–563 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ac656162-e5bc-534d-bbfd-3c243b82a0a0', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Fácil', 'Qual dependência é trivial?', '["C → B, com B e C distintos.","A → B, com A e B distintos.","{A,B} → A.","A → C, com A e C distintos.","B → A, com A e B distintos."]'::jsonb, 2, 'Uma DF é trivial quando o dependente é subconjunto do determinante.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.3, páginas 564 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('492ac750-7ead-54ca-b640-8c4d41bb1f4a', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'A DF {A,B} → {A,B} é válida em qualquer relvar com esses atributos por:', '["Uma ordenação física.","Reflexividade.","Uma política de acesso.","Transitividade entre três atributos distintos.","Uma chave estrangeira obrigatória."]'::jsonb, 1, 'Todo conjunto de atributos determina seus próprios subconjuntos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.3, páginas 564 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('48d8da50-e56d-55e6-b733-b74a48e74472', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'De A → B e B → C, qual DF pode ser inferida?', '["B → A.","A → C.","C → B.","C → A.","C → {A,B}."]'::jsonb, 1, 'A transitividade permite encadear as duas determinações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.4, páginas 565–567 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('16691aeb-deae-5a0c-83a0-9ff16ac0dc7a', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'De A → B, a regra de aumento permite inferir:', '["B → C.","C → A.","{A,C} → {B,C}.","C → B.","B → A."]'::jsonb, 2, 'Acrescentar os mesmos atributos aos dois lados preserva a dependência.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.4, páginas 565–567 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4f2bdc47-0528-566c-885c-579b950c4321', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'De A → B e A → C, pode-se inferir:', '["C → A.","B → C.","C → B.","A → {B,C}.","B → A."]'::jsonb, 3, 'A regra de união reúne dependentes do mesmo determinante.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.4, páginas 565–567 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6a76b786-a84b-5c2d-bfc2-2ecc10146bfb', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'De A → {B,C}, pode-se inferir:', '["B → C e C → B.","B → A e C → A.","B → A apenas.","A → B e A → C.","C → A apenas."]'::jsonb, 3, 'A decomposição separa os atributos do lado direito.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.4, páginas 565–567 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a2b59d76-49d5-5cad-927e-f8545f911cbf', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'O fecho F+ de um conjunto F de DFs contém:', '["Todas as DFs logicamente implicadas por F.","Apenas as chaves estrangeiras.","Somente as DFs textualmente listadas em F.","As tuplas atualmente armazenadas.","Somente DFs não triviais."]'::jsonb, 0, 'O fecho inclui também consequências e dependências triviais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.4, páginas 565–567 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('948994a0-5098-5e51-9360-09a7b2f33ca7', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Em R(A,B,C), com A → B e B → C, o fecho de A é:', '["{B,C}.","{A}.","{A,B}.","{A,B,C}.","Vazio."]'::jsonb, 3, 'Começa-se por A e aplicam-se as DFs até não acrescentar novos atributos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.5, páginas 568–570 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0cbc97c5-0bc2-5d6a-8ad2-c1d0a01eba83', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Difícil', 'Em R(A,B,C), somente com A → B, qual é C+?', '["Vazio.","{B,C}.","{A,B,C}.","{A,C}.","{C}."]'::jsonb, 4, 'Nenhuma DF disponível permite obter A ou B a partir de C.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.5, páginas 568–570 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('23dc5f1f-a5a6-5f46-9f34-6f24af63589c', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Difícil', 'Em R(A,B,C), com A → B, qual conjunto é chave candidata?', '["{C}.","{A}.","{A,C}.","{B,C}.","{B}."]'::jsonb, 2, 'A e C juntos determinam tudo; nenhum deles isoladamente determina todos os atributos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.5, páginas 568–570 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4b6b60f8-0e13-5c55-bdc9-3d7f63942866', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Em R(A,B,C), com A → B e B → C, A é:', '["Chave candidata.","Uma superchave não mínima.","Um dependente que não determina nada.","Apenas chave estrangeira.","Um atributo necessariamente redundante."]'::jsonb, 0, 'A+ contém todos os atributos, e seu único subconjunto próprio é vazio, que não os determina neste caso.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.5, páginas 568–570 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9e43892e-4e5f-5cfb-b4e4-d05918c50ab7', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Um conjunto X cujo fecho contém todos os atributos de R é:', '["Sempre uma chave candidata mínima.","Uma tupla da relação.","Sempre uma DF trivial.","Necessariamente uma chave estrangeira.","Uma superchave de R."]'::jsonb, 4, 'Para ser chave candidata, X ainda precisa ser irredutível.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.5, páginas 568–570 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a5b32566-c0bb-5c71-afea-4cee7b94f5be', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Dois conjuntos de DFs são equivalentes quando:', '["Usam a mesma ordem textual.","Possuem apenas atributos numéricos.","Possuem o mesmo fecho.","Têm o mesmo número de dependências.","Foram definidos pelo mesmo usuário."]'::jsonb, 2, 'Equivalência depende das consequências lógicas, não da forma de apresentação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.6, páginas 571–574 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('509f9f63-4626-5ccd-b18c-3ff7722947c0', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Uma DF redundante em F pode ser removida quando:', '["Não aparece em um índice.","Possui dois atributos no determinante.","Usa uma letra repetida em outra DF.","É a primeira da lista.","Ela já é implicada pelas outras DFs de F."]'::jsonb, 4, 'A remoção deve preservar o conjunto de dependências implicadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.6, páginas 571–574 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0fac0546-d506-526a-9573-cb5b207fefa8', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Em F={A → B, B → C, A → C}, qual DF é redundante?', '["Todas, independentemente umas das outras.","A → C.","A → B.","Nenhuma.","B → C."]'::jsonb, 1, 'A → C já decorre da transitividade das outras duas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.6, páginas 571–574 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f267b81f-e7b9-5043-a8c9-497a84d12701', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Difícil', 'Um conjunto irredutível de DFs deve evitar:', '["A existência de chaves candidatas.","Dependências e atributos supérfluos.","Toda aplicação de transitividade.","Toda dependência não trivial.","Qualquer atributo determinante."]'::jsonb, 1, 'Irredutibilidade busca uma cobertura equivalente sem componentes desnecessários.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.6, páginas 571–574 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3b768f32-bc54-5f1e-81e7-71b8d977a107', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Observar poucas linhas sem violação comprova que A → B é uma regra do domínio?', '["Não; a regra deve valer para todos os estados admissíveis.","Sim, se B for texto.","Sim, se houver índice em A.","Sim, duas linhas sempre bastam.","Não, porque DFs só se aplicam a uma linha."]'::jsonb, 0, 'Um estado pode satisfazer acidentalmente uma DF que não é uma restrição do domínio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.2, páginas 560–563 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d157c5e5-a7c5-5dff-ad9e-95980ebc5cdf', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Difícil', 'Para testar se X → Y é implicada por F, pode-se verificar se:', '["X está ordenado fisicamente.","X e Y têm a mesma quantidade de atributos.","Y é numérico.","Y está contido em X+ calculado sob F.","F possui mais de três DFs."]'::jsonb, 3, 'O cálculo de fecho de atributos permite testar implicação sem enumerar todo F+.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 11, seção 11.5, páginas 568–570 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('73860ec7-a7be-5bfd-9d5b-523d6283fccd', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Qual objetivo motiva a normalização discutida por Date?', '["Reduzir redundância e anomalias de atualização.","Criar o maior número possível de tabelas.","Eliminar a necessidade de transações.","Garantir o plano físico mais rápido em qualquer consulta.","Substituir regras de negócio por índices."]'::jsonb, 0, 'Normalização é uma disciplina de projeto lógico, não uma promessa universal de desempenho.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.1, páginas 584–589 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('44e8f007-87d2-5dc6-8d71-8e6278a719ce', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Uma decomposição sem perdas deve permitir:', '["Ordenar os dados sem índices.","Aceitar tuplas espúrias como requisito.","Reconstruir apenas parte das tuplas.","Reconstruir a relação original pela junção das projeções.","Remover as chaves de todas as projeções."]'::jsonb, 3, 'O critério é preservar a informação na decomposição e recomposição.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.2, páginas 590–594 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9b781b5c-3832-500f-bc2d-441e1fc7935f', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Difícil', 'Em R(A,B,C), com A → B, qual decomposição é garantida sem perdas pelo caso de Heath?', '["B e C apenas.","A e BC, sem outras hipóteses.","AB e AC.","A e B apenas.","AB e BC, sem outras hipóteses."]'::jsonb, 2, 'A interseção A determina AB; a junção de AB e AC recompõe R.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.2, páginas 590–594 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9676d174-c067-55d7-b7f8-c8372f003726', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Uma junção de projeções gera combinações que não existiam na relação original. Isso indica:', '["Normalização sem perdas garantida.","Uma simples alteração de apresentação.","Decomposição com perda de informação.","Ausência de qualquer dependência.","Um backup completo."]'::jsonb, 2, 'A perda é de informação sobre associações, podendo aparecer como tuplas espúrias.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.2, páginas 590–594 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4cbd6255-2dd0-5672-b9e5-8ed3010af536', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Na 2FN, atributos não primos não podem depender de:', '["Um tipo declarado.","Seu próprio valor.","Qualquer atributo em qualquer circunstância.","Parte própria de uma chave candidata composta.","Uma chave candidata completa."]'::jsonb, 3, 'A 2FN elimina dependências parciais de atributos não primos em chaves candidatas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.3, páginas 595–604 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('19baaaa0-12df-5fdc-a55b-22cf9636cdf9', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'R(A,B,C), chave AB e DF A → C, com C não primo, viola diretamente:', '["A existência de DFs triviais.","A possibilidade de ter atributos.","A 2FN.","Toda unicidade de AB.","A definição de tupla."]'::jsonb, 2, 'C depende de parte própria da chave composta AB.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.3, páginas 595–604 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('47369adb-8ed4-5fff-860d-b63f1629b732', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Um atributo primo é aquele que:', '["É sempre um número primo.","Participa de pelo menos uma chave candidata.","Não pode participar de dependências.","É necessariamente a chave primária inteira.","Está na primeira coluna física."]'::jsonb, 1, 'A classificação considera todas as chaves candidatas, não apenas a escolhida como primária.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.3, páginas 595–604 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f5c8782e-bf88-5f55-9b66-bce9ac2827e3', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Na definição geral de 3FN, para cada DF não trivial X → A deve valer:', '["X é superchave ou A é atributo primo.","A é obrigatoriamente não primo.","A é sempre chave estrangeira.","X tem exatamente um atributo.","X e A possuem o mesmo tipo."]'::jsonb, 0, 'A condição por atributo primo diferencia a 3FN da FNBC.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.3, páginas 595–604 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('08e6b7db-0582-56e5-a582-4ea8c7309bc7', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Em R(A,B,C), com chave A, A → B e B → C, sem outras DFs, qual problema existe?', '["Ausência de qualquer chave candidata.","Obrigação de uma chave composta.","Dependência transitiva de C em relação à chave, violando a 3FN.","DF B → C trivial.","Violação da unicidade de A por definição."]'::jsonb, 2, 'B não é superchave e C não é primo; separar BC elimina esse padrão de redundância.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.3, páginas 595–604 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c7af64da-19cf-5ef7-b8a5-6807ba73e579', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Se todas as chaves candidatas têm um único atributo, dependências parciais em partes próprias não vazias dessas chaves:', '["Impedem a 1FN.","Não ocorrem.","Exigem desnormalização.","São obrigatórias.","Criam automaticamente uma DMV."]'::jsonb, 1, 'Uma chave simples não possui subconjunto próprio não vazio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.3, páginas 595–604 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d22e77ef-1aaa-5cea-8d4a-287d6a5f0946', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Preservar dependências em uma decomposição significa principalmente:', '["Duplicar todas as DFs em todas as tabelas.","Garantir custo zero de validação.","Eliminar o significado das chaves.","Preservar a ordem física de cada registro.","Poder impor as DFs originais a partir das restrições das projeções."]'::jsonb, 4, 'Busca-se verificar dependências sem precisar recompor o conjunto original por junções.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.4, páginas 605–608 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('08c83c06-e183-5cd6-b0ed-484aa95da461', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Decomposição sem perdas e preservação de dependências são:', '["Propriedades impossíveis de testar.","Exclusivamente decisões de hardware.","Dois nomes para a mesma condição.","Garantias de ordenação.","Propriedades distintas."]'::jsonb, 4, 'Uma decomposição pode ser sem perdas e ainda não preservar todas as dependências localmente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.4, páginas 605–608 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c9455692-c597-5fdb-8166-63d6623590a6', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Uma relvar está em FNBC quando, em toda DF não trivial válida:', '["Existem exatamente duas chaves.","Todos os atributos são primos.","A chave primária é numérica.","O dependente tem um único caractere.","O determinante é superchave."]'::jsonb, 4, 'FNBC restringe todos os determinantes não triviais a superchaves.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.5, páginas 609–616 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5457479d-88d0-5d14-bfad-a4cc7938afac', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Toda relvar em FNBC está também em 3FN?', '["Não, as formas são incompatíveis.","Sim.","Somente se não possuir tuplas.","Somente se tiver uma chave simples.","Somente se usar SQL."]'::jsonb, 1, 'A condição da FNBC implica a condição da 3FN.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.5, páginas 609–616 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b8c6e821-7520-5bf6-bb5d-419a900089fe', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Toda relvar em 3FN está necessariamente em FNBC?', '["Não; a 3FN admite certos casos com dependente primo e determinante não superchave.","Sim, se houver índice.","Não, porque a FNBC é inferior à 1FN.","Sim, quando existem DFs.","Sim, são sinônimos."]'::jsonb, 0, 'A exceção permitida pela 3FN impede a equivalência entre as duas formas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.5, páginas 609–616 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d43320fc-8034-5577-abbb-68a300810863', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Difícil', 'Em R(A,B,C), com AB → C e C → B, quais são as chaves candidatas?', '["Somente BC.","AB e AC.","A e B.","B e C.","A e C."]'::jsonb, 1, 'AB determina tudo; AC obtém B por C → B. Nenhum subconjunto desses conjuntos basta.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.5, páginas 609–616 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f4f901e6-8703-5dd0-9dd8-99a1ef84c899', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Difícil', 'Em R(A,B,C), com AB → C e C → B, a DF C → B:', '["Prova que C é chave candidata.","É trivial.","Impede a existência de qualquer chave.","Garante a 5FN.","Viola a FNBC, pois C não determina A."]'::jsonb, 4, 'C não é superchave; B é primo, o que explica a possibilidade de 3FN sem FNBC.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.5, páginas 609–616 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('142b2692-5578-56d5-80cb-7357c4acd110', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Difícil', 'Uma decomposição em FNBC pode exigir qual compromisso?', '["Substituir domínios por endereços.","Aceitar obrigatoriamente tuplas duplicadas.","Eliminar todas as chaves.","Deixar de preservar localmente algumas DFs, embora seja sem perdas.","Descartar a reconstrução por junção."]'::jsonb, 3, 'Sem perdas e preservação de dependências podem entrar em conflito na redução à FNBC.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.5, páginas 609–616 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('808e5920-7cff-5315-a93a-d843f0c5ce86', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Na discussão de Date, possuir um atributo com valor relacional significa automaticamente violar a 1FN?', '["Não; é preciso respeitar o conceito de um valor do tipo correspondente.","Sim, toda relação aninhada é um ponteiro físico.","Sim, relações só admitem caracteres individuais.","Sim, atributos não podem ter tipos definidos.","Não, porque a 1FN dispensa tipos."]'::jsonb, 0, 'O autor distingue complexidade do tipo e ausência de um valor tipado por atributo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.6, páginas 617–619 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3778e22c-dfe5-5c39-b7be-9d3cb4b100eb', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Separar nome de departamento de cada matrícula, mantendo-o no cadastro de departamentos, evita principalmente:', '["Todas as consultas com junções.","Toda ocorrência de bloqueio.","Qualquer necessidade de autorização.","Atualizar várias cópias do mesmo fato departamental.","Toda chave estrangeira."]'::jsonb, 3, 'Reduzir repetição de fatos ajuda a evitar anomalias de modificação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 12, seção 12.1, páginas 584–589 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('abd2dd33-f1a6-525a-8476-60727a659562', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Uma dependência multivalorada trata principalmente de:', '["Permissões de usuário.","Ordenação física das linhas.","Criptografia de colunas.","Quantidade de índices.","Independência entre conjuntos de valores associados a um determinante."]'::jsonb, 4, 'DMVs capturam combinações independentes que DFs não descrevem completamente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('397dfb61-3e56-5300-b2a5-a933ffb4fca8', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Um aluno possui idiomas e esportes independentes entre si. Em R(Aluno,Idioma,Esporte), essa independência sugere:', '["Aluno →→ Idioma e Aluno →→ Esporte.","Esporte → Aluno obrigatoriamente.","Ausência de qualquer dependência.","Idioma → Aluno obrigatoriamente.","Aluno → Idioma e Aluno → Esporte obrigatoriamente."]'::jsonb, 0, 'Vários valores independentes por aluno indicam DMVs, não necessariamente DFs.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('25e53f9d-e8ac-5515-8371-f870a8332550', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Para um aluno com dois idiomas e três esportes independentes, quantas combinações completas aparecem em R?', '["5.","3.","2.","6.","1."]'::jsonb, 3, 'A independência requer o produto das duas coleções para aquele determinante.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f65ade8d-cf19-5680-84a7-c17c27616bb7', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Qual decomposição remove a repetição causada por idiomas e esportes independentes?', '["Uma relação por combinação completa.","AlunoIdioma e AlunoEsporte.","Aluno apenas.","Três relações sem o identificador do aluno.","IdiomaEsporte apenas."]'::jsonb, 1, 'As projeções preservam separadamente cada conjunto de fatos independentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('14a4a761-0191-5b77-aca7-83434f341abf', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'A 4FN exige que toda DMV não trivial tenha como determinante:', '["Uma coluna fisicamente ordenada.","Uma superchave.","Um atributo não primo.","Uma chave estrangeira necessariamente.","Um atributo textual."]'::jsonb, 1, 'Essa condição evita redundância multivalorada não justificada por chaves.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('033a6194-a0e5-51a3-8df9-d74e196a75ab', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'Toda dependência funcional X → Y implica uma DMV X →→ Y?', '["Somente se X for vazio.","Não, DFs e DMVs são incompatíveis.","Somente se Y for numérico.","Sim.","Somente em bancos distribuídos."]'::jsonb, 3, 'DMVs generalizam DFs; o sentido inverso não vale em geral.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f54431c0-e88f-59c8-839f-a7295f285e13', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Uma DMV X →→ Y implica necessariamente X → Y?', '["Não; pode haver vários valores de Y para o mesmo X.","Sim, se o banco for relacional.","Sim, se houver mais de uma linha.","Não, porque DMVs não admitem determinantes.","Sim, por definição."]'::jsonb, 0, 'A DF exige um único valor dependente por determinante; a DMV não.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('82837954-24c3-55dd-8f23-b9d1d2e7e70d', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Uma relvar em FNBC pode ainda conter redundância por quê?', '["FNBC ignora todas as DFs.","A FNBC elimina os tipos.","FNBC exige duplicação de todas as tuplas.","Toda chave candidata viola uma DMV.","Podem existir DMVs não triviais com determinante que não seja superchave."]'::jsonb, 4, 'FNBC resolve condições sobre DFs, mas não todas as dependências multivaloradas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f9cc4c72-8653-50e3-92ed-cd14f3c88aae', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Uma dependência de junção declara que uma relação é igual:', '["À primeira linha de cada projeção.","À união arbitrária de quaisquer tabelas.","À junção de determinadas projeções suas.","A uma lista ordenada de atributos.","A um produto físico de arquivos."]'::jsonb, 2, 'A DJ expressa a reconstrução sem perdas por um conjunto de projeções.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.3, páginas 637–643 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4a9c4c25-2860-5ee9-864a-e21bc0b143c6', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Uma DJ pode envolver mais de duas projeções?', '["Somente em arquivos não relacionais.","Não, pois junções são sempre unárias.","Sim.","Não, toda DJ é binária.","Somente se não houver chaves."]'::jsonb, 2, 'Certas redundâncias só são reveladas por decomposições em três ou mais projeções.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.3, páginas 637–643 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f0827a09-f3ee-5f1f-acb7-12ac3c793c95', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Qual forma normal é também chamada forma normal de projeção-junção?', '["FNBC.","1FN.","5FN.","3FN.","2FN."]'::jsonb, 2, 'A 5FN trata das dependências de junção não triviais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.3, páginas 637–643 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8382f474-262d-50c6-8bda-a771bd691fe2', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Difícil', 'Na 5FN, as dependências de junção não triviais devem ser justificadas por:', '["Número de discos.","Ordem dos atributos.","Endereços físicos.","Senhas dos usuários.","Chaves candidatas."]'::jsonb, 4, 'O critério exclui redundância de junção que não decorra das chaves.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.3, páginas 637–643 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('832b64aa-5ec9-5748-a730-a8d614707634', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Toda relvar em 5FN está em 4FN?', '["Sim.","Não, porque a 5FN dispensa DMVs.","Somente se estiver vazia.","Não, são formas independentes.","Somente se tiver uma chave simples."]'::jsonb, 0, 'A hierarquia de formas normais exige também as condições anteriores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.3, páginas 637–643 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('36d3d42e-b1a5-5608-bf7f-70f1c6ff4929', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'A 4FN garante, por si só, a ausência de toda redundância baseada em DJs de maior ordem?', '["Não, porque 4FN exige duplicatas.","Sim, se houver índices.","Sim, desde que haja três atributos.","Não; essa motivação leva à 5FN.","Sim, toda DJ é uma DF."]'::jsonb, 3, 'DMVs não esgotam as dependências de junção possíveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.3, páginas 637–643 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('38d48861-557f-5471-bb63-8cdbfc1dbfbc', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Ao decompor uma relação durante a normalização, qual propriedade deve ser preservada?', '["Número original de colunas em cada projeção.","Reconstrução sem perdas.","Ordem de inserção.","Quantidade de páginas do índice.","Nome físico do arquivo."]'::jsonb, 1, 'Dividir tabelas sem preservar informação não constitui uma decomposição adequada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.4, páginas 644–647 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1eacfa51-7e02-553c-be8b-8c85071b18d5', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Date recomenda assumir que desnormalizar é sempre necessário para desempenho?', '["Sim, toda junção torna o banco inviável.","Sim, a 5FN impede índices.","Não; desempenho e projeto lógico devem ser analisados separadamente.","Sim, qualquer duplicação é benéfica.","Não, porque desempenho não importa."]'::jsonb, 2, 'Não se deve abandonar um bom projeto lógico por uma regra geral de desempenho sem análise.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.5, páginas 648–651 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8a86e63a-3db1-55cf-80ab-337d611c7d26', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Materializar um resultado para acelerar consultas deve exigir atenção a:', '["Proibição de qualquer redundância controlada.","Apenas escolha da cor da interface.","Remoção de todas as chaves.","Atualização e consistência da informação derivada.","Dispensa de renovação."]'::jsonb, 3, 'Uma representação redundante mantida por razões físicas precisa de controle.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.5, páginas 648–651 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0d8ec0fb-3758-548f-8cad-7dca1a75ec4a', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'O princípio de projeto ortogonal busca evitar principalmente:', '["Toda junção em consultas.","Qualquer relacionamento entre entidades.","Toda referência entre tabelas.","Todos os tipos definidos pelo usuário.","Representações redundantes e sobrepostas do mesmo fato em relvars diferentes."]'::jsonb, 4, 'O princípio complementa a preocupação com redundância entre relvars distintas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.6, páginas 652–656 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dc5c455b-5e69-599b-9839-b3d75864dfb6', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Difícil', 'Se idiomas e esportes não forem independentes, decompor somente em AlunoIdioma e AlunoEsporte pode:', '["Criar combinações não autorizadas ao recompor por junção.","Produzir uma única tupla por aluno.","Preservar obrigatoriamente a associação original.","Garantir sempre a mesma relação.","Eliminar automaticamente todas as restrições."]'::jsonb, 0, 'A decomposição depende da validade da DMV, não apenas dos nomes dos atributos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c3f24048-848e-5fd6-b93a-2ccd1432dcdf', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Por que inferir dependências somente a partir da amostra atual é arriscado?', '["Porque amostras nunca contêm dados.","Ela pode omitir combinações válidas ou violações possíveis em outros estados.","Porque toda amostra determina a 5FN.","Porque a normalização independe da semântica.","Porque dependências são físicas."]'::jsonb, 1, 'Dependências são regras dos estados admissíveis, não coincidências de uma fotografia dos dados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.4, páginas 644–647 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7addf850-bdda-56ae-b825-81089b3f090d', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Qual é uma finalidade da modelagem semântica?', '["Substituir toda análise de requisitos.","Eliminar o significado dos dados.","Representar conceitos do domínio e suas regras de forma estruturada.","Escolher exclusivamente o tamanho de páginas.","Determinar senhas de rede."]'::jsonb, 2, 'Entidades, propriedades e relacionamentos ajudam a explicitar a semântica do domínio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.2, páginas 676–679 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1fdf2f76-9b4f-592b-9840-602b40ce3c26', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Fácil', 'Um equipamento individual distinguível no domínio é exemplo de:', '["Operador de agregação.","Entidade.","Arquivo de log.","Regra de bloqueio.","Índice obrigatório."]'::jsonb, 1, 'Uma entidade corresponde a um objeto distinguível de interesse para a organização.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('90463aa6-1766-527d-b1c1-4b694eb50862', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Fácil', 'A data de aquisição de um equipamento é, no modelo E/R, uma:', '["Superclasse necessariamente.","Junção física.","Propriedade da entidade.","Entidade fraca obrigatória.","Transação distribuída."]'::jsonb, 2, 'Propriedades descrevem aspectos das entidades ou dos relacionamentos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7046663c-3050-5517-b755-949f3c0138fd', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'A associação entre técnicos e equipamentos que inspecionam é um:', '["Checkpoint.","Operador de criptografia.","Relacionamento.","Tipo físico de disco.","Catálogo de usuários."]'::jsonb, 2, 'Relacionamentos representam associações entre entidades do domínio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6559630e-c4a7-5298-8f0f-2c93582bcb13', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Uma entidade cuja existência depende de outra é denominada, na terminologia discutida:', '["Fraca.","Independente obrigatoriamente.","Materializada.","Primária por definição.","Irredutível."]'::jsonb, 0, 'O capítulo associa entidades fracas à dependência de existência em relação a outra entidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0139f77b-e899-5bae-a5eb-973990409581', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Fácil', 'Um técnico inspeciona vários equipamentos e um equipamento recebe vários técnicos. A cardinalidade é:', '["Muitos para um apenas do técnico para o equipamento.","Um para um.","Muitos para muitos.","Zero para um obrigatoriamente.","Um para muitos apenas do técnico para o equipamento."]'::jsonb, 2, 'Ambos os lados podem participar em várias ocorrências da associação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c62de188-d2b2-558d-b12a-4f052535997c', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Fácil', 'Cada empregado pertence a um departamento, e cada departamento possui vários empregados. Do departamento para empregados, há:', '["Nenhum relacionamento.","Muitos para muitos obrigatoriamente.","Muitos para um.","Um para um.","Um para muitos."]'::jsonb, 4, 'A cardinalidade precisa ser lida no sentido indicado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5f64e312-4616-59e1-823d-cb2c3de5ba6a', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Fácil', 'Uma propriedade calculada a partir de outras, como total de itens, é:', '["Uma entidade regular.","Derivada.","Sempre multivalorada.","Obrigatoriamente identificadora.","Um índice interno."]'::jsonb, 1, 'A propriedade derivada possui regra de cálculo a partir de informações disponíveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4e9c78a9-4312-5220-989b-e4cf189099cc', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Fácil', 'Vários telefones para a mesma pessoa exemplificam uma propriedade:', '["Sem relação com a entidade.","Obrigatoriamente sem domínio.","Sempre identificadora.","Multivalorada no modelo conceitual.","Sempre derivada."]'::jsonb, 3, 'A representação lógica posterior precisa expressar adequadamente essa multiplicidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cd438dfc-edac-5876-89b4-375612b41dd0', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Rua, número e cidade agrupados em endereço ilustram uma propriedade:', '["Obrigatoriamente fraca.","Um relacionamento ternário necessariamente.","Uma chave estrangeira por definição.","Composta.","Sem componentes."]'::jsonb, 3, 'Uma propriedade composta pode ser descrita em termos de componentes menores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7e30c18a-244f-5d5e-9b1b-a9bb12d68fc7', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Um diagrama E/R dispensa a especificação complementar de todas as regras de integridade?', '["Não, porque diagramas não representam entidades.","Sim, desde que não existam atributos.","Sim, se houver retângulos.","Sim, todo desenho formaliza qualquer regra.","Não; regras podem não estar expressas pela notação gráfica utilizada."]'::jsonb, 4, 'O capítulo alerta para a imprecisão e as lacunas de diagramas na descrição de restrições.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.4, páginas 686–688 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ee26e012-b069-5907-b476-1090adc97aa5', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Ao mapear um relacionamento muitos para muitos para o modelo relacional, é comum criar:', '["Uma relvar de associação com referências aos participantes.","Um índice sem dados.","Uma cópia de segurança por entidade.","Um usuário por ocorrência.","Uma coluna que concatena todos os identificadores."]'::jsonb, 0, 'A associação é representada por fatos próprios ligados às entidades participantes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.5, páginas 689–695 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ada556ff-2ed6-5193-85f2-2b35d42789b5', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Qual estrutura representa adequadamente notas de alunos em disciplinas?', '["Apenas uma nota única no cadastro geral da disciplina.","Um nome de aluno dentro da senha do professor.","Uma nota única global para todos os alunos.","Somente um índice na tabela de alunos.","Uma associação AlunoDisciplina com as referências e a nota."]'::jsonb, 4, 'A nota depende da ocorrência da associação, não apenas de um dos participantes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.5, páginas 689–695 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ae2d9081-3d41-5d71-94b7-d7cb3a0eac9e', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Para representar cada empregado ligado a um departamento, uma opção usual é:', '["Uma tabela sem identificadores.","Uma chave estrangeira de departamento em empregado.","Uma chave primária igual para todos os empregados.","O endereço físico do departamento na aplicação.","Uma lista de nomes concatenados no departamento."]'::jsonb, 1, 'A chave estrangeira representa a associação muitos para um, respeitadas as demais restrições.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.5, páginas 689–695 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('87b6ad8d-a475-5c51-be7d-6814084aed41', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Uma chave estrangeira, sozinha, garante um relacionamento um para um?', '["Não; a exclusividade do lado referenciador exige restrição adicional apropriada.","Sim, se a coluna for texto.","Sim, toda referência é um para um.","Sim, se o banco tiver índices.","Não, porque chaves estrangeiras não ligam entidades."]'::jsonb, 0, 'Unicidade e obrigatoriedade precisam ser modeladas além da mera referência.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.5, páginas 689–695 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5b2c2ef7-c1ab-5ae5-8bb6-26b53c4b439b', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Um relacionamento que liga empregado a seu supervisor, ambos do tipo empregado, é:', '["Necessariamente muitos para muitos.","Uma propriedade sem entidades.","Impossível no modelo E/R.","Uma herança de tipos obrigatória.","Recursivo, com papéis distintos."]'::jsonb, 4, 'A mesma classe de entidades pode participar com papéis diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7e41272b-cbc8-50c0-b685-33acfc374a10', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Substituir um relacionamento ternário por três relacionamentos binários é sempre seguro?', '["Não; pode perder restrições sobre a combinação dos três participantes.","Sim, por identidade matemática universal.","Sim, porque entidades só se ligam aos pares.","Sim, se houver três índices.","Não, porque relacionamentos binários são proibidos."]'::jsonb, 0, 'A associação entre triplas pode conter informação não preservada por pares independentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.5, páginas 689–695 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ec149ec2-afb5-59c6-82ab-1ee6c2e0f8e8', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Uma entidade pode participar de zero ocorrências de um relacionamento quando a participação é:', '["Sempre total.","Identificadora por definição.","Obrigatória.","Opcional.","Fisicamente ordenada."]'::jsonb, 3, 'Participação opcional admite ausência de associação; cardinalidade máxima é outra informação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.3, páginas 680–685 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0cac28be-db7e-5f1b-86fb-d9f8a59ab91c', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Ao transformar conceitos do domínio em objetos formais, é necessário também definir:', '["Um índice por palavra do enunciado.","Somente cores dos diagramas.","A ordem física de todas as tuplas.","Regras de integridade e operações correspondentes.","A senha de cada usuário final."]'::jsonb, 3, 'Símbolos sem regras e operações não fornecem uma descrição formal suficiente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.2, páginas 676–679 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6f7b73a8-0d23-55b7-ac8a-87640e508ae7', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Na análise de Date, usar diagramas E/R obriga a adotar integralmente todas as ideias de um único modelo semântico?', '["Sim, porque qualquer diagrama é um esquema interno.","Não; a técnica de diagramação e o modelo são propostas distinguíveis.","Sim, por definição de diagrama.","Não, porque diagramas nunca têm semântica.","Sim, desde que haja entidades fracas."]'::jsonb, 1, 'O autor distingue a notação gráfica dos compromissos teóricos de um modelo específico.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 14, seção 14.6, páginas 696–699 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('46fddde3-ec97-5d45-975d-a43868d4bd3f', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Fácil', 'Uma transação é, principalmente, uma unidade lógica de:', '["Ordenação de colunas.","Armazenamento de senhas.","Trabalho e recuperação.","Definição de hardware.","Diagramação de entidades."]'::jsonb, 2, 'Agrupar operações permite tratar seus efeitos como uma unidade recuperável.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.2, páginas 727–732 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9ba4fb0b-2c81-56ac-972c-838f8536bdca', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Fácil', 'Qual propriedade exige que os efeitos de uma transação sejam confirmados em conjunto?', '["Confidencialidade.","Fragmentação.","Atomicidade.","Durabilidade.","Normalização."]'::jsonb, 2, 'Atomicidade evita a confirmação de apenas uma parte da unidade lógica.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.2, páginas 727–732 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1694baca-d3d4-5731-a696-f694b9402b44', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Fácil', 'Qual propriedade exige a permanência dos efeitos de uma transação confirmada após falhas recuperáveis?', '["Projeção.","Minimalidade.","Autorização.","Redundância.","Durabilidade."]'::jsonb, 4, 'Após o commit, os mecanismos de recuperação devem preservar os efeitos confirmados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.2, páginas 727–732 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8e5ac466-ff8e-5541-9e18-1b09e4407213', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'Em ACID, isolamento trata principalmente de:', '["Interferência entre transações concorrentes.","Tipos dos dispositivos.","Ausência de índices.","Distribuição de documentos.","Validação de senhas."]'::jsonb, 0, 'O objetivo é controlar a visibilidade e o efeito da execução concorrente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.2, páginas 727–732 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('58059891-a1df-5550-b7bf-a416cb02cb37', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'O SGBD pode garantir que qualquer programa autorizado implementa corretamente a intenção do negócio?', '["Sim, pela existência do log.","Não, porque transações não possuem regras.","Sim, se houver uma chave primária.","Não; a correção da lógica da aplicação também precisa ser assegurada.","Sim, somente por usar COMMIT."]'::jsonb, 3, 'Mecanismos transacionais não corrigem automaticamente algoritmos de negócio incorretos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.2, páginas 727–732 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('709a697f-b58a-547a-ae3c-51e9a9dcc49f', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'Uma transação termina sem alcançar COMMIT e precisa ser abandonada. Qual tratamento corresponde à recuperação local?', '["Eliminar todas as transações já confirmadas.","Desfazer seus efeitos não confirmados.","Confirmar somente seu primeiro comando.","Renomear as relvars alteradas.","Descartar as restrições do banco."]'::jsonb, 1, 'Recuperação de transação reverte a unidade malsucedida.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.3, páginas 733–736 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('11380c06-a0fc-5c6e-b092-d15908deb08f', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Para permitir operações de desfazer e refazer, o sistema mantém:', '["Log de recuperação.","Somente a interface gráfica.","A ordem de apresentação de relatórios.","Apenas nomes de usuários.","Um diagrama E/R sem dados."]'::jsonb, 0, 'O log registra informações necessárias à recuperação das alterações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.3, páginas 733–736 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('422df7d9-407e-568c-8c91-40aa1e8aebd5', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'A regra de gravação antecipada no log exige, no tratamento descrito, que o COMMIT só seja concluído após:', '["Atualizar todas as telas.","Eliminar os registros de recuperação.","Persistir no log as informações necessárias da transação.","Imprimir todas as alterações.","Copiar o banco para cada cliente."]'::jsonb, 2, 'O registro durável permite recuperar os efeitos mesmo que páginas de dados ainda dependam de gravação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.3, páginas 733–736 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('aecc4d14-af1e-5227-89a3-34f37424a0ed', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Uma queda de energia sem dano físico ao armazenamento é classificada no capítulo como:', '["Falha do sistema.","Ataque por inferência.","Erro de tipo.","Violação de chave candidata.","Falha da mídia obrigatoriamente."]'::jsonb, 0, 'O capítulo distingue interrupções globais sem dano físico de falhas destrutivas de mídia.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.4, páginas 737–740 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('940df84e-1f84-58a2-841e-ade7df4b5ca6', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Perder fisicamente o disco de dados exige uma estratégia baseada em:', '["Somente reiniciar a interface.","Apenas renomear os arquivos ausentes.","Uma projeção sem fontes.","Cópia de segurança e informações de recuperação disponíveis.","Somente liberar bloqueios."]'::jsonb, 3, 'A recuperação da mídia depende de reconstruir dados perdidos a partir de cópias e registros preservados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.5, páginas 741 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a8d47f5d-b84f-5335-b598-c320b3672e4d', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Em uma estratégia de recuperação com undo/redo, uma transação não confirmada na falha pode exigir:', '["Exclusão das transações anteriores.","Remoção do catálogo.","Confirmação automática obrigatória.","Renovação de todas as senhas.","Undo de seus efeitos."]'::jsonb, 4, 'O trabalho não confirmado não deve permanecer parcialmente efetivado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.4, páginas 737–740 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bf814de4-de58-57ef-863e-e6193f9bb558', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Em uma estratégia com undo/redo, uma transação confirmada cujas páginas ainda não foram persistidas pode exigir:', '["Desativação da durabilidade.","Exclusão de sua entrada no log.","Redo a partir do log.","Uma nova autorização do usuário.","Cancelamento definitivo do commit."]'::jsonb, 2, 'Refazer alterações permite recuperar efeitos confirmados ainda ausentes dos arquivos de dados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.4, páginas 737–740 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1f2d781e-9049-51d2-b021-a2b7efff0fcc', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Qual é uma finalidade dos checkpoints?', '["Substituir todos os backups de mídia.","Apagar imediatamente todo o log.","Garantir a correção do algoritmo de negócio.","Impedir qualquer nova transação.","Reduzir e organizar o trabalho necessário na recuperação."]'::jsonb, 4, 'Checkpoints delimitam informações úteis ao reinício e à análise das transações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.4, páginas 737–740 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6fd626f0-a04c-5242-9bd8-9a1ec43e4d35', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'O commit de duas fases coordena principalmente:', '["Duas fases de criação de índice.","Uma decisão comum entre gerenciadores de recursos participantes.","Duas formas normais.","A troca de senhas entre dois usuários.","Apenas dois comandos SELECT."]'::jsonb, 1, 'A coordenação busca evitar confirmações parciais de uma transação envolvendo vários recursos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.6, páginas 742–744 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('12af115c-b165-5122-91fd-16cee2651842', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Na primeira fase do 2PC, os participantes são consultados sobre:', '["A ordem gráfica das tabelas.","Sua capacidade de preparar e concluir a transação conforme a decisão global.","A conversão do banco em monousuário.","A remoção de todos os logs.","A existência de uma impressora."]'::jsonb, 1, 'A fase de preparação antecede a decisão global de confirmar ou abortar.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.6, páginas 742–744 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cfe54477-f0c3-5971-af7e-37e7412437d1', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Se um participante não consegue preparar sua parte, a decisão global de sucesso deve ser:', '["Substituída por exclusão de seu log.","Definida apenas pela maioria dos usuários finais.","Aplicada somente à primeira tabela.","Impedida, levando ao abortamento no protocolo normal.","Confirmada nos demais e ignorada nele."]'::jsonb, 3, 'A atomicidade global exige que todos os participantes possam cumprir a confirmação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.6, páginas 742–744 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bf49f7c9-0eb7-5fb1-9752-4fc8cb8cbd37', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Criar um savepoint equivale a confirmar definitivamente as alterações anteriores?', '["Sim, é sinônimo de COMMIT.","Não; ele marca um ponto de retorno dentro da transação.","Não, porque savepoints não possuem nome.","Sim, mas apenas em tabelas vazias.","Sim, e encerra a transação."]'::jsonb, 1, 'Um savepoint não é uma confirmação independente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.7, páginas 745 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c0543d84-fc3e-5e6c-a099-c4475a681753', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'ROLLBACK até um savepoint permite:', '["Eliminar a necessidade de commit final.","Confirmar todas as alterações posteriores.","Desfazer commits de outras sessões.","Apagar a definição das tabelas.","Desfazer alterações posteriores ao ponto, preservando o contexto anterior da transação."]'::jsonb, 4, 'O mecanismo fornece recuperação parcial sem confirmar uma subtransação independente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.7, páginas 745 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('84345e8c-2feb-5a46-ace8-dceed8a7a444', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Fácil', 'Qual par SQL corresponde à conclusão bem-sucedida e ao abandono de uma transação?', '["CREATE e ALTER.","JOIN e UNION.","SELECT e INSERT.","COMMIT e ROLLBACK.","GRANT e REVOKE."]'::jsonb, 3, 'A conclusão transacional é diferente da manipulação de linhas ou de privilégios.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.8, páginas 746–747 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5c7178ae-86c5-5298-ac25-26499b1dd621', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Manter uma cópia de backup no mesmo dispositivo físico que pode falhar oferece qual limitação?', '["A mesma falha pode destruir dados e cópia.","Impede qualquer falha do sistema.","Torna o backup mais recente que os dados.","Garante recuperação integral por definição.","Dispensa o log."]'::jsonb, 0, 'A recuperabilidade depende de preservar fontes de restauração além do componente perdido.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 15, seção 15.5, páginas 741 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bcf0688d-423c-5259-a3c1-70cdc6856dea', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'T1 e T2 leem saldo 100. T1 grava 110 e T2 grava 120 calculado do saldo antigo. Qual anomalia ocorre?', '["Atualização perdida.","Herança múltipla.","Leitura fantasma necessariamente.","Violação obrigatória de chave.","Decomposição sem perdas."]'::jsonb, 0, 'A segunda gravação sobrescreve o efeito da primeira sem incorporá-lo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.2, páginas 761–765 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ef6bc2ae-ea03-50fa-9e93-fd16d26e15a8', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'T2 lê um valor escrito por T1 antes do commit; T1 depois aborta. Isso é:', '["Atualização de catálogo obrigatória.","Normalização.","Fragmentação vertical.","Dependência sem commit ou leitura suja.","Durabilidade."]'::jsonb, 3, 'T2 utilizou uma alteração que não chegou a ser confirmada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.2, páginas 761–765 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ac102456-46dc-5951-9ebc-b801fd29cbab', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Um relatório soma valores enquanto outra transação redistribui quantias entre os registros lidos. Sem isolamento, pode ocorrer:', '["Análise inconsistente.","Desnormalização obrigatória.","Garantia de leitura serial.","Junção sem perdas.","Mudança de tipo."]'::jsonb, 0, 'O relatório pode combinar estados anteriores e posteriores da operação concorrente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.2, páginas 761–765 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3b0344f6-21da-5bf1-9e81-050a909a92a1', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Dois bloqueios compartilhados sobre o mesmo objeto são, no esquema básico:', '["Permitidos somente para a mesma transação.","Equivalentes a um exclusivo.","Sempre conflitantes.","Compatíveis.","Proibidos após qualquer leitura."]'::jsonb, 3, 'Vários leitores podem coexistir quando nenhum deles exige exclusividade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.3, páginas 766–768 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('74f61b3a-eb9e-5595-b4ea-5e2fb170dd53', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Um bloqueio exclusivo existente é compatível com um novo bloqueio compartilhado de outra transação sobre o mesmo objeto?', '["Somente se o leitor não usar SQL.","Sim, porque leitura nunca interfere.","Sim, quando o objeto tem nome curto.","Não, no esquema básico de bloqueios.","Sim, sempre."]'::jsonb, 3, 'O exclusivo impede acessos concorrentes incompatíveis ao objeto bloqueado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.3, páginas 766–768 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('53524498-9a75-575d-84c5-139f26c7d51b', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'Antes de atualizar um objeto, o protocolo básico exige bloqueio:', '["De impressão.","Exclusivo.","Apenas sobre o terminal.","Somente compartilhado.","De autenticação."]'::jsonb, 1, 'A escrita exige exclusão de acessos incompatíveis no modelo discutido.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.3, páginas 766–768 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('72090c60-feb3-5c89-9e5e-5d14fc19c2f5', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Fácil', 'T1 espera um recurso de T2, enquanto T2 espera um recurso de T1. Isso caracteriza:', '["Renomeação.","Commit distribuído concluído.","Leitura repetível garantida.","Fragmentação.","Deadlock."]'::jsonb, 4, 'A espera circular impede o avanço sem intervenção.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.5, páginas 772–774 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0ed2914b-e9b1-5b13-8c61-c78af88256e8', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Uma forma de resolver um deadlock detectado é:', '["Escolher uma transação vítima e desfazê-la para liberar recursos.","Confirmar à força todas as transações.","Apagar todas as tabelas envolvidas.","Proibir permanentemente qualquer leitura.","Eliminar as restrições de tipo."]'::jsonb, 0, 'O rollback de uma vítima rompe o ciclo de espera.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.5, páginas 772–774 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('99c829a9-6a61-5826-8af5-a45a53517dc5', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Fácil', 'Um escalonamento serial executa transações:', '["Somente em modo de leitura.","Uma após a outra, sem intercalar suas operações.","Na ordem alfabética dos usuários.","Sempre simultaneamente em vários processadores.","Com todos os commits omitidos."]'::jsonb, 1, 'Serial descreve a organização da execução, não um algoritmo de ordenação de usuários.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.6, páginas 775–778 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5074adb9-3908-59f0-be6b-c981ea7df597', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Um escalonamento seriável é aquele equivalente, no sentido relevante, a:', '["Qualquer execução com o mesmo tempo total.","Um backup em ordem crescente.","Uma consulta sem junção.","Uma execução sem log.","Algum escalonamento serial das mesmas transações."]'::jsonb, 4, 'A execução pode ser intercalada e ainda preservar um resultado compatível com ordem serial.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.6, páginas 775–778 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('277bbdd6-e572-546c-b538-3d460100904e', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Difícil', 'No bloqueio de duas fases, depois de começar a liberar bloqueios uma transação:', '["Deve obrigatoriamente abortar.","Pode ignorar conflitos.","Deve adquirir um exclusivo sobre todo o banco.","Precisa executar outro BEGIN.","Não deve adquirir novos bloqueios."]'::jsonb, 4, 'As fases são crescimento e encolhimento do conjunto de bloqueios.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.6, páginas 775–778 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8ffc4c60-2745-52c5-8ddc-6a846d1bd6a7', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Difícil', 'O protocolo de duas fases garante ausência de deadlock?', '["Sim, desde que existam índices.","Não, porque ele proíbe transações.","Sim, se todos os bloqueios forem exclusivos.","Não; seriabilidade não elimina a possibilidade de espera circular.","Sim, porque são apenas duas fases."]'::jsonb, 3, 'A garantia de seriabilidade e a prevenção de deadlocks são problemas distintos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.6, páginas 775–778 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7db244dd-439b-5dc4-8a15-4385e3aa50d6', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Reter bloqueios de escrita até o fim da transação ajuda a evitar:', '["A necessidade de log.","Todos os deadlocks.","Leituras de alterações não confirmadas e abortamentos em cascata.","Todas as consultas complexas.","Qualquer falha física de disco."]'::jsonb, 2, 'Outras transações não devem depender de efeitos que ainda podem ser desfeitos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.7, páginas 779–781 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('460e9b0b-c3e0-52ab-94d5-c4a2c75a5c59', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'No padrão SQL, READ COMMITTED evita diretamente:', '["Todos os fantasmas.","Todas as leituras não repetíveis.","Leituras sujas.","Toda atualização perdida em qualquer padrão de uso.","Toda espera por bloqueio."]'::jsonb, 2, 'O nível não oferece, por si só, todas as garantias de SERIALIZABLE.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.11, páginas 797–798 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('512b5b9a-1b4d-5ff2-879f-5e5ccf36017a', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Uma linha é lida duas vezes e aparece alterada por um commit concorrente. Essa anomalia é:', '["Deadlock necessariamente.","Leitura não repetível.","Leitura suja necessariamente.","Dependência funcional trivial.","Falha de mídia."]'::jsonb, 1, 'A segunda leitura vê outro valor confirmado para a mesma linha.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.8, páginas 782–785 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e25e5735-0df1-547c-9d0a-f0710fb04dbc', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Uma consulta repetida encontra novas linhas que satisfazem seu filtro após uma inserção concorrente. Isso ilustra:', '["Fantasma.","Ausência de concorrência.","Commit de duas fases.","Uma DF trivial.","Atomicidade."]'::jsonb, 0, 'A mudança afeta o conjunto de linhas que satisfaz o predicado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.8, páginas 782–785 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c041dc5a-94bf-5e30-bdc6-4bf7ba7a6b5c', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Difícil', 'Bloquear apenas as linhas já encontradas impede necessariamente inserções que gerem fantasmas?', '["Não, porque linhas não podem ser bloqueadas.","Não; o conjunto definido pelo predicado também precisa de proteção apropriada.","Sim, qualquer bloqueio de linha protege todo o predicado.","Sim, ao usar uma coluna numérica.","Sim, desde que a tabela possua nome."]'::jsonb, 1, 'Linhas ainda inexistentes não são cobertas simplesmente por bloqueios nas linhas lidas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.8, páginas 782–785 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0eeee178-45a3-506b-a11a-43c82df76062', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Granularidade mais fina de bloqueio tende a oferecer:', '["Dispensa de detectar conflitos.","Menos concorrência e nenhum custo de gestão.","Mais concorrência, com maior quantidade potencial de bloqueios.","Uma única trava para todo o banco.","Eliminação garantida de deadlocks."]'::jsonb, 2, 'A escolha envolve compromisso entre concorrência e sobrecarga de gerenciamento.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.9, páginas 786–789 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('40750b21-75e7-533d-9382-9da123c3c1b0', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Bloqueios de intenção em uma hierarquia indicam:', '["Que os dados são públicos.","Que não há qualquer bloqueio em descendentes.","Que os índices foram removidos.","Que a transação já confirmou.","Que podem existir ou ser adquiridos bloqueios em níveis inferiores."]'::jsonb, 4, 'A intenção permite coordenar bloqueios de granularidades diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.9, páginas 786–789 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1091dd2d-22b4-5964-8a8c-eab124fe6b8a', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Difícil', 'O nome REPEATABLE READ deve ser interpretado sem considerar o padrão e o produto discutidos?', '["Não, porque isolamento não possui níveis.","Sim, ele sempre significa exatamente SERIALIZABLE.","Não; o capítulo alerta para diferenças entre a terminologia do DB2 e a do padrão SQL.","Sim, todos os produtos usam a mesma implementação.","Sim, ele sempre permite leitura suja."]'::jsonb, 2, 'A nomenclatura histórica não deve ser generalizada sem conferir a definição aplicável.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 16, seção 16.11, páginas 797–798 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f112f594-045a-590a-86b4-e93519b9d172', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Fácil', 'No contraste entre segurança e integridade, segurança trata principalmente de:', '["Garantir a validade semântica de todo dado.","Decompor relações sem perdas.","Impedir acesso não autorizado.","Escolher o algoritmo de junção.","Reduzir o número de atributos."]'::jsonb, 2, 'Segurança verifica permissões; integridade verifica condições de validade dos dados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.1, páginas 818–821 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('77bbed08-d976-5ce2-b3fa-50166e2c3360', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'O controle de acesso discricionário se caracteriza por permissões concedidas segundo:', '["O algoritmo de ordenação física.","Somente o valor da chave primária.","Apenas a ordem das tuplas.","O instante de criação de um índice.","Decisões de proprietários ou autoridades habilitadas sobre os objetos."]'::jsonb, 4, 'O capítulo usa também a expressão controle discriminatório para essa categoria.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.2, páginas 822–829 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b8f33a1a-e7c9-5f53-9699-aaa459e05a61', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Uma autorização precisa relacionar, entre outros elementos:', '["Apenas o número de conexões.","Usuários, objetos e privilégios permitidos.","Somente processadores e discos.","Somente chaves e índices.","Tabelas e cores de interface."]'::jsonb, 1, 'A permissão deve definir quem pode fazer o quê sobre quais dados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.2, páginas 822–829 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4c86bead-9614-5d0d-952e-b7f27ca7c3a5', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Permitir leitura, mas impedir atualização, exemplifica:', '["Privilégios distintos para tipos de operação.","Uma dependência multivalorada.","Ausência de qualquer segurança.","Uma DF entre usuários.","Uma cópia de segurança."]'::jsonb, 0, 'A autorização pode ser específica para consulta, inserção, alteração ou exclusão.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.2, páginas 822–829 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d2954897-a812-56df-8214-263dbf0b49f3', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Restringir um empregado à consulta de sua própria linha é um controle:', '["Sem relação com autorização.","De normalização obrigatória.","Exclusivamente sobre criação de índices.","Baseado somente em tamanho físico.","Dependente dos valores envolvidos no acesso."]'::jsonb, 4, 'O critério depende da associação entre o usuário e os valores consultados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.2, páginas 822–829 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('deb0a7da-1a17-5896-8ea8-518e487a17bd', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Fácil', 'Qual finalidade tem uma trilha de auditoria?', '["Normalizar o banco.","Eliminar a necessidade de autenticação.","Substituir toda autorização.","Impedir matematicamente qualquer invasão.","Registrar eventos de acesso relevantes para investigação."]'::jsonb, 4, 'Auditoria fornece evidências; não equivale, sozinha, a bloquear operações indevidas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.2, páginas 822–829 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8985f476-c323-5e7d-8a17-c788ea8aa2dc', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'No controle mandatário, decisões de acesso utilizam principalmente:', '["Preferências de cores do usuário.","Quantidade de linhas da tabela.","Classificação dos objetos e nível de liberação dos usuários.","Ordem de inserção.","Tamanho do nome do atributo."]'::jsonb, 2, 'Rótulos e regras obrigatórias restringem o fluxo de informação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.3, páginas 830–834 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('603263e5-c559-5216-b8bc-0fb694f1cb55', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'No modelo de confidencialidade apresentado, a regra de leitura impede:', '["Toda leitura no próprio nível.","Somente leitura de índices.","Uso de tabelas com uma coluna.","Ler informação acima do nível de liberação permitido.","Acesso a qualquer dado público."]'::jsonb, 3, 'A regra impede leitura para cima na hierarquia de classificação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.3, páginas 830–834 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e4d825c5-ed4b-5866-a6c2-152d81413209', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'A regra de escrita voltada a impedir vazamento entre níveis restringe:', '["Qualquer escrita no mesmo nível.","Somente atualizações de números.","Toda leitura de catálogos.","Escrever informação em nível inferior ao permitido pelo modelo.","Somente inserções em tabelas vazias."]'::jsonb, 3, 'Evitar escrita para baixo ajuda a impedir transferência indevida para níveis menos sigilosos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.3, páginas 830–834 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6bcb536d-1831-5029-95f9-97d30582553c', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Um banco estatístico deve fornecer agregados preservando:', '["Apenas a primeira linha de cada grupo.","A confidencialidade das informações individuais.","A ordem de todos os nomes.","A ausência de qualquer soma.","O acesso irrestrito às linhas."]'::jsonb, 1, 'O objetivo combina utilidade estatística e proteção de dados individuais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.4, páginas 835–842 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2bb0e391-2586-5530-ae57-0b2c3050a8d5', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Duas somas sobre grupos quase iguais permitem deduzir o salário de uma pessoa pela diferença. Isso é um risco de:', '["Fragmentação vertical.","Deadlock.","Inferência estatística.","Perda de fechamento.","Dependência parcial."]'::jsonb, 2, 'Resultados agregados combinados podem revelar informação que não foi consultada diretamente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.4, páginas 835–842 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f525ba75-95ce-56f7-8e57-8013f7ab3623', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Proibir consultas que retornem uma única pessoa elimina todo risco de inferência?', '["Não; combinações de consultas podem isolar informações individuais.","Não, porque agregação não é permitida.","Sim, desde que os nomes não sejam exibidos.","Sim, se os totais forem exatos.","Sim, qualquer grupo maior que um é seguro."]'::jsonb, 0, 'O capítulo destaca ataques que combinam resumos aparentemente permitidos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.4, páginas 835–842 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('47804b46-21bf-5f7a-8167-62062b2be46a', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Na criptografia simétrica, emissor e receptor utilizam essencialmente:', '["Uma chave primária de tabela.","A senha do DBA em cada linha.","Somente uma chave pública universal.","Uma chave secreta compartilhada para as operações correspondentes.","Um índice agrupado."]'::jsonb, 3, 'A gestão do segredo compartilhado é parte central desse esquema.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.5, páginas 843–848 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a4ac9ae4-3da6-59c1-8ddc-39fd20a86e4b', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Na criptografia de chave pública, qual distinção é fundamental?', '["Uma chave SQL e um índice físico.","Duas chaves que devem ser divulgadas juntas.","Duas cópias públicas da mesma senha.","Uma chave pública e uma chave privada relacionadas, com papéis diferentes.","Uma chave por coluna sem relação matemática."]'::jsonb, 3, 'A chave privada deve permanecer secreta; a pública pode ser divulgada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.5, páginas 843–848 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a1414805-5357-5b33-a711-33d330e57888', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Uma assinatura digital procura fornecer principalmente evidência de:', '["Confidencialidade obrigatória de todo conteúdo.","Origem e integridade da mensagem assinada.","Compressão sem perdas.","Normalização da mensagem.","Ausência de qualquer chave."]'::jsonb, 1, 'Assinar não significa necessariamente cifrar o conteúdo para ocultá-lo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.5, páginas 843–848 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('396e37ad-2600-5929-9ffc-7af4bc5b72c8', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Cifrar dados resolve automaticamente permissões indevidas concedidas pela aplicação?', '["Sim, ao usar nomes de colunas curtos.","Não; criptografia e controle de acesso são mecanismos complementares.","Sim, toda permissão fica irrelevante.","Sim, se houver uma chave pública.","Não, porque dados cifrados nunca podem ser lidos."]'::jsonb, 1, 'Uma aplicação autorizada a decifrar ainda precisa aplicar as regras de acesso.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.5, páginas 843–848 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7bfc0c7b-82fd-561d-940f-7b75bbb81484', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Fácil', 'Qual comando SQL concede privilégios?', '["GROUP BY.","REVOKE.","CHECK.","ROLLBACK.","GRANT."]'::jsonb, 4, 'GRANT estabelece autorizações sobre objetos conforme o modelo SQL.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.6, páginas 849–854 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('524275fb-a69c-5225-a75e-52f35f2dcbd5', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Fácil', 'Qual comando SQL revoga privilégios?', '["REVOKE.","INSERT.","COMMIT.","SELECT.","CREATE TYPE."]'::jsonb, 0, 'A revogação precisa considerar as regras de dependência e propagação aplicáveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.6, páginas 849–854 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('43cc2e81-eb8c-594b-ad4a-0aad74efe3d9', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'WITH GRANT OPTION permite ao beneficiário, nas condições previstas:', '["Repassar o privilégio recebido.","Confirmar transações de outros usuários.","Ler qualquer tabela sem autorização.","Ignorar todas as restrições de integridade.","Apagar logs de auditoria automaticamente."]'::jsonb, 0, 'A opção trata da delegação do privilégio concedido.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.6, páginas 849–854 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7fc6ab79-8dd8-55bb-9ad5-fef6d4ba270d', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Se arquivos físicos puderem ser lidos contornando o SGBD, seus controles internos são suficientes?', '["Não, porque bancos não usam arquivos.","Sim, se o catálogo estiver normalizado.","Não; o sistema operacional e os demais canais também precisam de proteção.","Sim, desde que exista uma visão.","Sim, a autorização SQL cobre qualquer acesso externo."]'::jsonb, 2, 'A segurança precisa considerar o sistema completo, não apenas um ponto de acesso.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 17, seção 17.1, páginas 818–821 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e763087f-70f5-59a0-a8ab-4a4c7633f682', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Qual objetivo orienta a otimização de uma consulta?', '["Transformar toda consulta em índice.","Eliminar restrições de integridade.","Confirmar automaticamente transações.","Escolher uma implementação eficiente que preserve o significado da consulta.","Modificar o resultado para reduzir seu tamanho."]'::jsonb, 3, 'Otimização altera o plano de execução, não a resposta lógica esperada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.3, páginas 870–875 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8c74c858-06e5-5174-993e-a24d3c9de4fe', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Uma representação interna canônica da consulta serve principalmente para:', '["Substituir o catálogo.","Descartar os tipos dos atributos.","Persistir uma cópia por usuário.","Facilitar análise e transformações pelo otimizador.","Expor endereços físicos ao usuário."]'::jsonb, 3, 'Uma forma interna estruturada permite trabalhar sobre a consulta independentemente de seu texto original.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.3, páginas 870–875 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6c8aa078-b1ae-5f4e-ab38-e10fcea49d41', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Um plano lógico e um plano físico diferem porque o físico especifica:', '["A cor dos resultados.","Técnicas de implementação e caminhos de acesso.","Somente o significado de cada entidade.","A senha de conexão.","A validade das regras do domínio."]'::jsonb, 1, 'O plano físico escolhe como executar operações que já possuem significado lógico.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.3, páginas 870–875 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2badce2b-707a-5984-85c8-f16f0d632f2a', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Empurrar uma seleção para antes de uma junção pode ser vantajoso porque:', '["Dispensa compatibilidade de atributos.","Garante custo zero.","Muda a condição de resposta para aceitar mais linhas.","Sempre elimina todas as junções.","Pode reduzir os dados intermediários processados."]'::jsonb, 4, 'A transformação é útil quando é válida e reduz o volume de trabalho.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.4, páginas 876–883 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4df9e9cf-042d-504a-89e9-7c7b98c9fd59', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Uma seleção sobre atributo exclusivo de R pode, em condições relacionais usuais, ser aplicada antes de R JOIN S porque:', '["A condição pode ser avaliada apenas em R, preservando o resultado da expressão.","Toda seleção é equivalente a qualquer junção.","A junção ignora todos os atributos de R.","O resultado deixa de precisar de tipos.","A transformação permite descartar o predicado."]'::jsonb, 0, 'A validade depende das referências do predicado e da semântica dos operadores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.4, páginas 876–883 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c2f7dc43-ed29-5ecb-8a9c-e45143ee0877', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Difícil', 'Por que remover cedo uma coluna necessária à condição de junção é incorreto?', '["Porque projeção sempre aumenta a cardinalidade.","Porque o resultado precisa conter todas as colunas de origem.","A etapa seguinte deixa de possuir informação necessária à correspondência.","Porque junções não usam colunas.","Porque todo atributo é obrigatoriamente chave."]'::jsonb, 2, 'Reduzir colunas exige preservar os atributos usados por operações posteriores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.4, páginas 876–883 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('694b805b-9323-5f2e-8792-604d8ff6d4e7', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'A comutatividade de uma junção permite ao otimizador:', '["Substituir qualquer junção por diferença.","Mudar o tipo dos atributos.","Eliminar obrigatoriamente uma tabela.","Ignorar todas as condições.","Considerar ordens alternativas dos operandos com o mesmo significado."]'::jsonb, 4, 'Equivalências algébricas ampliam o espaço de planos candidatos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.4, páginas 876–883 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b0136bd0-b0af-59e8-88fb-27129a78bfd5', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'A associatividade de junções é relevante principalmente para escolher:', '["A ordem de formação de resultados intermediários.","A classificação de confidencialidade.","O formato do log de auditoria.","O nome de cada coluna.","A senha dos usuários."]'::jsonb, 0, 'Ordens equivalentes podem ter volumes intermediários e custos muito diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.4, páginas 876–883 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('142b93cd-132d-55a1-b886-51fd6f871c4c', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Difícil', 'Qual transformação usa conhecimento de restrições, além das leis algébricas gerais?', '["Criação de savepoint.","Recuperação de mídia.","Autenticação.","Otimização semântica.","Criptografia simétrica."]'::jsonb, 3, 'Restrições válidas podem permitir simplificar condições e expressões.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.4, páginas 876–883 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e1b130d9-0f05-54b7-8a08-68db6b0d7795', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Qual informação auxilia a estimar o custo de um plano?', '["Cardinalidades e distribuição de valores.","Exclusivamente o nome da chave.","Somente a cor da interface.","A senha do último usuário.","Apenas o nome da aplicação."]'::jsonb, 0, 'Estatísticas ajudam a prever quantas linhas e páginas serão processadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.5, páginas 884–885 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b7e6f268-6809-54f2-b51f-63303007ca3f', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Estatísticas desatualizadas podem causar:', '["Eliminação de todos os índices.","Confirmação automática das transações.","Estimativas ruins e escolha de plano inadequado.","Mudança necessária do resultado lógico correto.","Desaparecimento dos tipos."]'::jsonb, 2, 'O plano pode continuar semanticamente válido, mas ser ineficiente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.5, páginas 884–885 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0e21656a-a476-5773-aaf1-d483375c8a24', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Uma condição que aceita poucas linhas tende a possuir:', '["Obrigação de produzir o produto cartesiano.","Uma chave estrangeira automática.","Alta capacidade de filtragem.","Cardinalidade igual à tabela original.","Ausência de predicado."]'::jsonb, 2, 'Seletividade precisa ser interpretada conforme a convenção numérica, mas o efeito de filtragem é claro.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.5, páginas 884–885 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('903d201f-a0a8-512b-a577-5668b0306301', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Uma junção por laços aninhados combina, em sua forma básica:', '["Apenas renomeação de atributos.","Exclusão dos valores repetidos de uma coluna.","Somente leitura do catálogo.","Iteração sobre um operando e busca de correspondências no outro.","Duas confirmações de transação."]'::jsonb, 3, 'A implementação pode variar conforme o acesso escolhido para o operando interno.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.7, páginas 891–897 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('115114bd-172c-52ec-8bc1-b8e46e0c6bd8', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Um índice no operando interno pode beneficiar uma junção por laços porque:', '["Substitui a necessidade de ler resultados.","Transforma valores nulos em zero.","Permite localizar correspondências sem varrer integralmente esse operando a cada passo.","Garante que todas as consultas usem o mesmo plano.","Elimina a condição de junção."]'::jsonb, 2, 'O benefício depende da quantidade de buscas e dos custos envolvidos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.7, páginas 891–897 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('00451b87-b26d-5fe0-87c0-e1852979cb1a', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Uma junção por intercalação é favorecida quando entradas já estão:', '["Armazenadas em usuários distintos.","Cifradas com chaves diferentes.","Limitadas a uma coluna sem correspondência.","Sem qualquer cabeçalho.","Ordenadas pelos atributos de junção relevantes."]'::jsonb, 4, 'A ordenação permite percorrer valores correspondentes de maneira coordenada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.7, páginas 891–897 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('194b6dc8-b695-57da-8910-36f757c66f59', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Uma junção hash usa principalmente:', '["Uma ordenação alfabética obrigatória de todos os atributos.","Uma função de dispersão para organizar e localizar candidatos à correspondência.","Assinaturas digitais de usuários.","Um savepoint por tupla.","Uma regra de cascata."]'::jsonb, 1, 'A dispersão ajuda a localizar tuplas com chaves correspondentes, tipicamente em equijunções.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.7, páginas 891–897 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4477d526-181b-5b12-8d49-52685349abde', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Qual técnica é universalmente a mais rápida para qualquer junção?', '["Hash em todos os casos.","Nenhuma; a escolha depende dos dados, memória, índices e custos.","Laços aninhados em todos os casos.","Intercalação em todos os casos.","Produto cartesiano sem filtro em todos os casos."]'::jsonb, 1, 'Algoritmos possuem condições de aplicação e compromissos diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.7, páginas 891–897 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('86ccb3b4-d673-51f3-abe5-c2cc05eb5ada', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'A estratégia de dividir e conquistar aplicada a consultas procura:', '["Remover todas as dependências.","Decompor o problema em partes tratáveis e combinar seus resultados.","Confirmar cada linha isoladamente.","Copiar cada tabela para todos os usuários.","Eliminar a semântica da consulta."]'::jsonb, 1, 'O capítulo discute decomposição de consultas como estratégia de processamento.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.6, páginas 886–890 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0c20490a-b7fa-565f-b74d-7aa241c5e61b', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'O menor custo estimado garante necessariamente o menor tempo real observado?', '["Sim, para qualquer carga concorrente.","Sim, se o plano contiver um índice.","Não, porque o resultado lógico muda.","Sim, estimativas são medidas exatas.","Não; a escolha depende da precisão do modelo e das estimativas."]'::jsonb, 4, 'Modelos aproximam custos e podem não capturar todas as condições de execução.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.3, páginas 870–875 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('702df6cf-6ad1-5225-b15e-9b2f5a34c22c', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Difícil', 'Aplicar uma equivalência válida em conjuntos a SQL com duplicatas e nulos exige:', '["Conferir se a equivalência preserva a semântica SQL efetiva.","Eliminar todos os filtros.","Assumir que todas as regras continuam válidas sem exame.","Trocar nulos por zero automaticamente.","Ignorar a multiplicidade de linhas."]'::jsonb, 0, 'Diferenças de semântica podem invalidar transformações que parecem óbvias no modelo puro.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 18, seção 18.4, páginas 876–883 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('55bb0115-8ddd-5ddc-a906-ea3711df4bf6', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Em SQL, a comparação comum NULL = 5 produz:', '["O inteiro zero.","TRUE.","FALSE em todos os contextos.","UNKNOWN.","Uma string vazia."]'::jsonb, 3, 'Comparações comuns com marcador nulo não recebem um valor booleano clássico determinado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.2, páginas 932–938 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3a717833-5bdd-519f-8cb8-8d6ac2595419', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Na lógica trivalorada SQL, NOT UNKNOWN resulta em:', '["Uma exceção obrigatória.","TRUE.","NULL numérico igual a zero.","FALSE.","UNKNOWN."]'::jsonb, 4, 'A negação preserva o valor lógico desconhecido.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.2, páginas 932–938 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('32d022f3-adc2-5571-9bdc-72794a599c86', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Na lógica trivalorada SQL, TRUE AND UNKNOWN resulta em:', '["FALSE.","UNKNOWN.","Uma string vazia.","Zero.","TRUE."]'::jsonb, 1, 'O resultado depende da condição desconhecida, pois o outro operando é verdadeiro.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.2, páginas 932–938 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9c8ece33-f15c-5ee8-8e9f-3f277ef5240c', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Na lógica trivalorada SQL, FALSE AND UNKNOWN resulta em:', '["Um erro de chave.","UNKNOWN.","Uma relação vazia por definição.","FALSE.","TRUE."]'::jsonb, 3, 'Um operando falso torna falsa a conjunção independentemente do outro.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.2, páginas 932–938 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f541d5d6-1475-53f3-8d96-979019cb9f3a', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Na lógica trivalorada SQL, TRUE OR UNKNOWN resulta em:', '["UNKNOWN.","FALSE.","TRUE.","Uma exceção.","Um número nulo."]'::jsonb, 2, 'Um operando verdadeiro basta para tornar verdadeira a disjunção.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.2, páginas 932–938 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d1deb54e-02fc-5ed1-9b3c-e96c869a98d6', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'Na lógica trivalorada SQL, FALSE OR UNKNOWN resulta em:', '["TRUE.","Uma string vazia.","UNKNOWN.","Um erro de tipo obrigatório.","FALSE."]'::jsonb, 2, 'A verdade da disjunção ainda depende do operando desconhecido.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.2, páginas 932–938 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ae53fb90-9de4-5dde-9e2b-9e4add5e73ff', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Uma cláusula WHERE seleciona linhas cuja condição resulta em:', '["TRUE.","Somente UNKNOWN.","Qualquer valor que não seja zero.","TRUE ou UNKNOWN.","FALSE ou UNKNOWN."]'::jsonb, 0, 'Condições falsas ou desconhecidas não qualificam a linha para o resultado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1752959e-7861-5c47-b678-d8516a4638ac', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Fácil', 'Qual teste SQL verifica diretamente a presença de marcador nulo?', '["IS NULL.","= 0.","= NULL.","= UNKNOWN como substituto universal.","<> NULL."]'::jsonb, 0, 'IS NULL é um teste específico; a comparação comum com NULL não é equivalente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f4f4de9b-7148-5c39-80f5-8bb50ef36e91', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'A expressão NULL = NULL em SQL é avaliada como:', '["FALSE obrigatoriamente.","UNKNOWN.","Uma tupla vazia.","Zero.","TRUE."]'::jsonb, 1, 'A igualdade comum não identifica dois marcadores nulos como um valor conhecido igual.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('43c2e153-f683-571b-826e-b8153843c1a9', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Difícil', 'Se P é UNKNOWN, P OR NOT P produz, na lógica trivalorada discutida:', '["TRUE.","Uma confirmação.","Um inteiro.","FALSE.","UNKNOWN."]'::jsonb, 4, 'O terceiro valor impede aplicar sem exame certas equivalências da lógica bivalorada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.3, páginas 939–943 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5b1ed8a3-0bf1-5465-b4c9-9c7e26068aee', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Para valores 10, 20 e NULL, COUNT(coluna) retorna:', '["2.","1.","NULL.","3.","0."]'::jsonb, 0, 'COUNT da expressão conta apenas resultados não nulos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0457ebf8-3499-5c2a-87c0-25531a923053', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Para três linhas, uma contendo NULL na coluna consultada, COUNT(*) retorna:', '["2.","3.","NULL.","1.","0."]'::jsonb, 1, 'COUNT(*) conta linhas, independentemente de nulos em colunas particulares.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ee1d31ee-1933-5132-a7d6-edeee131ab81', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Para valores 10, 20 e NULL, AVG(coluna) resulta em:', '["30.","15.","10.","0.","NULL obrigatoriamente."]'::jsonb, 1, 'AVG ignora o marcador nulo; não o trata automaticamente como zero.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('458dd776-65e7-5fdc-8a64-0d3349fdb7d0', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Fácil', 'Uma coluna de chave primária SQL pode aceitar NULL?', '["Sim, somente na primeira linha.","Sim, se seu tipo for texto.","Sim, quando referenciada por outra tabela.","Sim, se o índice estiver ordenado.","Não."]'::jsonb, 4, 'A chave primária SQL exige identificação não nula.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.4, páginas 944–947 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f773f17d-c04b-51b5-9e22-75a39c30bfd3', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Uma chave estrangeira anulável significa necessariamente que toda linha deve possuir referência preenchida?', '["Sim, quando a tabela contém índices.","Sim, REFERENCES implica NOT NULL em qualquer declaração.","Não; nulos e regras de correspondência precisam ser considerados.","Sim, por definição de coluna.","Não, porque chaves estrangeiras nunca são verificadas."]'::jsonb, 2, 'Obrigatoriedade e integridade da referência são requisitos relacionados, mas distintos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.4, páginas 944–947 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('68fa96d9-93d2-5e86-b673-dd150e48089d', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Uma junção externa à esquerda preserva:', '["Apenas linhas com chaves nulas.","Todas as combinações do produto sem filtro.","Somente as linhas do lado direito.","Todas as linhas do lado esquerdo, usando nulos nos campos direitos sem correspondência.","Somente linhas com correspondência dos dois lados."]'::jsonb, 3, 'O preenchimento de campos ausentes distingue a junção externa da interna.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.5, páginas 948–951 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6c69f9f6-039d-59db-88c4-e1329fc5f9cb', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Difícil', 'Um filtro WHERE sobre coluna direita após LEFT JOIN pode eliminar linhas sem correspondência porque:', '["A condição pode resultar UNKNOWN nos campos preenchidos com NULL.","NULL é sempre igual a qualquer valor.","Toda coluna direita vira chave primária.","LEFT JOIN nunca conserva linhas da esquerda.","WHERE é executado como COMMIT."]'::jsonb, 0, 'É necessário considerar o efeito do filtro sobre as linhas estendidas com nulos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('488bc0b3-6053-596f-a085-7889b8ac7e29', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Usar -1 como valor especial para informação ausente exige cuidado porque:', '["Ele garante média correta sem tratamento.","Ele passa a ser automaticamente NULL.","O valor sentinela pode contaminar cálculos e precisa de semântica explícita.","Ele elimina todas as restrições.","Ele impede qualquer armazenamento."]'::jsonb, 2, 'Um valor convencional não equivale ao mecanismo de ausência nem resolve toda ambiguidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.6, páginas 952 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('97de7848-4535-583f-b60c-0749d784af43', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Qual expressão SQL escolhe o primeiro argumento não nulo entre salario e 0?', '["salario <> NULL.","NULL = 0.","salario = NULL.","COALESCE(salario, 0).","COUNT(*)."]'::jsonb, 3, 'A substituição é explícita; usar zero envolve uma decisão semântica da aplicação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.7, páginas 953–960 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6714806d-4a20-5707-8097-73274160b7cf', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Difícil', 'Uma consulta usa x NOT IN (1, NULL). Para x=2, por que a linha não é selecionada?', '["Porque NULL equivale a todos os inteiros.","Porque a tabela não pode conter 2.","Porque NOT IN é sempre falso.","Porque 2 é igual a 1.","A comparação com o nulo torna o predicado UNKNOWN."]'::jsonb, 4, 'A negação não converte desconhecido em verdadeiro, exigindo cuidado com nulos em subconsultas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 19, seção 19.3, páginas 939–943 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2e2d61c4-114f-5f3b-97d0-d794f93b248a', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Se B é subtipo de A no modelo apresentado, o conjunto de valores de B é:', '["Subconjunto do conjunto de valores de A.","Necessariamente disjunto de A.","Uma variável de relação.","Um arquivo físico separado por definição.","Superconjunto próprio de A."]'::jsonb, 0, 'Todo valor de B também é valor de A.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.2, páginas 979–984 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('97d9a352-242d-5eb9-b7c2-64407843f613', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Se C é subtipo de B e B é subtipo de A, então:', '["B deixa de existir.","C também é subtipo de A.","A é necessariamente subtipo próprio de C.","C e A são disjuntos obrigatoriamente.","C deve ser um tipo de relação."]'::jsonb, 1, 'A relação de subtipagem é transitiva.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.2, páginas 979–984 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8909900e-40fe-5632-9c9f-d8359c6f5229', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Um subtipo próprio costuma impor, em relação ao supertipo:', '["Um novo nome para exatamente o mesmo conjunto.","Ausência de operadores.","Obrigação de armazenamento separado.","Restrições adicionais sobre os valores admissíveis.","Menos condições, admitindo todos os valores adicionais."]'::jsonb, 3, 'A especialização restringe o conjunto de valores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.2, páginas 979–984 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('feb96435-1c47-5ea0-9d7c-8c1254e78b13', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'Em uma hierarquia de tipos, um tipo raiz é aquele que:', '["Não possui supertipo próprio na hierarquia considerada.","É sempre uma relvar básica.","Não possui subtipos.","Possui exatamente um atributo.","Não possui valores."]'::jsonb, 0, 'Raiz e folha descrevem posições distintas na hierarquia.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.2, páginas 979–984 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3626b0e4-4ca7-58bd-a738-0bc8603def16', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Fácil', 'Um tipo folha, na hierarquia considerada, é aquele que:', '["Não possui subtipo próprio.","Contém todos os demais tipos.","Não pode ter operadores.","Não possui supertipo.","É sempre vazio."]'::jsonb, 0, 'Ser folha não significa estar no topo da hierarquia.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.2, páginas 979–984 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('70f13728-8305-5f77-9163-4ad5da7501f6', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'O polimorfismo por inclusão permite que um operador para A receba:', '["Somente valores sem restrições.","Apenas endereços físicos.","Valores de subtipos de A, respeitado seu contrato.","Apenas relvars sem atributos.","Qualquer valor de tipo incompatível."]'::jsonb, 2, 'A inclusão do conjunto do subtipo no supertipo fundamenta essa possibilidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.3, páginas 985–989 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a5b835dc-bc76-5e5a-a41c-2b4faf0f0863', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Um operador calcula a área de uma figura do tipo ELIPSE. Um valor CÍRCULO pode ser aceito porque:', '["Círculo é um caso particular de elipse no modelo.","Todos os valores geométricos têm a mesma representação.","Operadores ignoram tipos.","A operação transforma qualquer figura em círculo.","Círculos não possuem restrições."]'::jsonb, 0, 'A substituição de valores respeita a inclusão do subtipo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.3, páginas 985–989 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3e68eb0e-a1f9-5658-9b67-df30aa2642aa', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Definir uma implementação especializada de área para retângulos pode trazer:', '["Dispensa de respeitar o tipo do resultado.","Eliminação do supertipo.","Reutilização do contrato com uma implementação mais adequada ao subtipo.","Liberdade para retornar o perímetro no lugar da área.","Mudança obrigatória do significado de área."]'::jsonb, 2, 'Especialização de implementação deve preservar a semântica do operador.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.3, páginas 985–989 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('35406eca-9005-5fd5-9fa7-e71df49d416f', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Uma variável declarada ELIPSE pode receber um valor CÍRCULO, na hierarquia apresentada?', '["Não, pois valores de subtipos nunca são atribuíveis.","Não, porque variáveis geométricas são constantes.","Sim, apenas se perder o centro.","Sim, porque o valor pertence também ao supertipo.","Sim, mas seu tipo declarado muda obrigatoriamente."]'::jsonb, 3, 'Tipo declarado da variável e tipo mais específico do valor são conceitos distintos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.4, páginas 990–995 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6a596322-5cf2-5bfc-ac78-9cc2f3f8d994', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Uma variável declarada CÍRCULO pode receber qualquer valor ELIPSE?', '["Não, porque círculos não são valores.","Não; o valor precisa satisfazer as restrições de círculo.","Sim, se estiver na mesma transação.","Sim, todo supertipo cabe no subtipo.","Sim, se tiver representação binária."]'::jsonb, 1, 'A atribuição ao subtipo exige compatibilidade com seu conjunto de valores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.4, páginas 990–995 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6147f461-a0a3-5ba8-a5f1-620f3d42cee3', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Receber um valor de subtipo altera necessariamente o tipo declarado de uma variável de supertipo?', '["Sim, se houver operador de leitura.","Sim, mas apenas uma vez.","Não, porque o valor é descartado.","Sim, em toda atribuição.","Não."]'::jsonb, 4, 'A declaração continua delimitando os valores admissíveis da variável.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.4, páginas 990–995 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ab6f4f33-8e8d-53b7-952e-7de75dddcba5', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Difícil', 'No modelo de especialização por restrição de Date, criar uma elipse com semieixos iguais produz valor cujo tipo mais específico é:', '["POLÍGONO.","CÍRCULO.","Sempre ELIPSE, nunca CÍRCULO.","Uma relvar sem tipo.","RETÂNGULO."]'::jsonb, 1, 'A classificação considera as restrições satisfeitas pelo valor, não apenas o nome do seletor.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.5, páginas 996–999 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('31b1d690-c77b-5059-8cd1-623c2223b9a7', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Se um valor satisfaz as restrições de um subtipo, sua classificação depende exclusivamente do seletor usado para construí-lo?', '["Sim, porque restrições só valem para variáveis.","Sim, independentemente das propriedades do valor.","Não, no modelo de especialização por restrição apresentado.","Sim, apenas em tipos escalares.","Não, porque nenhum tipo possui seletores."]'::jsonb, 2, 'A discussão separa propriedades do valor e histórico de construção.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.5, páginas 996–999 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('714b655c-1b9d-5644-9bab-39d8cdaec369', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Comparar valores em uma hierarquia exige considerar:', '["Apenas seus nomes impressos.","O tamanho do nome do usuário.","Compatibilidade de tipos e semântica dos operadores de comparação.","A ordem de criação dos tipos.","Somente seus endereços físicos."]'::jsonb, 2, 'Representações iguais não bastam para estabelecer toda igualdade semântica.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.6, páginas 1000–1004 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('27b2944e-3853-56ab-aca0-e55cf283f766', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'A assinatura de um operador inclui, em linhas gerais:', '["A data do último backup.","A cardinalidade de todas as tabelas.","Somente a localização do código em disco.","A senha do proprietário.","Nome e tipos dos parâmetros pertinentes."]'::jsonb, 4, 'Assinaturas permitem caracterizar e distinguir invocações e versões de operadores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.7, páginas 1005–1011 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f3b70a5b-61de-5e22-84b4-2fa509bf8c60', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Versões especializadas de um mesmo operador devem:', '["Produzir qualquer resultado do mesmo tamanho físico.","Usar obrigatoriamente o mesmo algoritmo.","Trocar o nome do supertipo.","Ignorar restrições do subtipo.","Manter o contrato semântico comum aplicável."]'::jsonb, 4, 'Compatibilidade de tipagem não garante, sozinha, correção do comportamento.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.7, páginas 1005–1011 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d017c8bd-da61-5163-b2fe-bee4153262f9', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Difícil', 'Alterar apenas um semieixo de uma variável declarada CÍRCULO pode ser inválido porque:', '["Círculos não possuem dimensões.","Operadores de atualização são sempre proibidos no banco.","A variável muda automaticamente para qualquer supertipo.","Pode violar a igualdade dos semieixos exigida pelo subtipo.","Toda elipse exige semieixos distintos."]'::jsonb, 3, 'Restrições da variável precisam ser preservadas em atualizações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.8, páginas 1012–1017 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9aeda4dc-670c-5166-939e-2ba67422fcf7', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Difícil', 'Por que substituição de valores e substituição de variáveis atualizáveis não são equivalentes?', '["Porque leitura sempre altera os dados.","Porque valores possuem endereços permanentes.","Porque subtipos só podem ser usados em texto.","Atualizações precisam respeitar o conjunto de valores permitido pela variável.","Porque variáveis nunca têm tipos."]'::jsonb, 3, 'Uma operação válida para variáveis de supertipo pode produzir valor proibido para uma variável de subtipo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.8, páginas 1012–1017 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d91cfd75-877c-5ced-9e29-8f84336c8163', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Fácil', 'Herança múltipla significa que um tipo pode possuir:', '["Mais de um usuário autorizado.","Mais de um valor, apenas.","Mais de uma variável.","Mais de um índice físico.","Mais de um supertipo imediato."]'::jsonb, 4, 'A quantidade de supertipos imediatos distingue herança simples e múltipla.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.2, páginas 979–984 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('418d18ce-c50d-528d-9ed0-daa5241cb225', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Polimorfismo por inclusão e sobrecarga de nomes são necessariamente o mesmo mecanismo?', '["Não, porque polimorfismo não admite operadores.","Não; inclusão decorre da hierarquia de subtipos.","Sim, qualquer nome repetido cria subtipos.","Sim, porque tipos são representações físicas.","Sim, desde que o nome tenha parâmetros."]'::jsonb, 1, 'Operadores homônimos não estabelecem, por si só, relação de subtipagem.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.3, páginas 985–989 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e5513636-aeb3-549a-9e82-8117d51b6906', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Um banco de dados distribuído envolve dados logicamente relacionados mantidos:', '["Apenas no terminal de um usuário.","Somente em um arquivo local por definição.","Sem qualquer comunicação entre componentes.","Em múltiplos sites com gerenciamento coordenado.","Exclusivamente em memória transitória."]'::jsonb, 3, 'A distribuição dos dados deve ser tratada como um sistema integrado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.1, páginas 1040 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e7b32aeb-b23a-50f9-9180-cc1bd01c1fc8', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Autonomia local significa principalmente:', '["Eliminação dos administradores locais.","Ausência de qualquer política de integridade.","Obrigação de copiar tudo para um único centro.","Proibição de acesso remoto.","Controle local dos dados e operações do site, dentro da coordenação do sistema."]'::jsonb, 4, 'Autonomia não deve ser confundida com isolamento absoluto entre os sites.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.3, páginas 1047–1057 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8ed727b8-3972-5b93-9c21-3472a7882c37', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'O objetivo de não depender de um site central busca evitar:', '["A existência de chaves candidatas.","Qualquer catálogo distribuído.","Toda comunicação entre sites.","Toda transação local.","Que um componente central seja indispensável à operação de todo o sistema."]'::jsonb, 4, 'A organização deve reduzir dependências centrais que limitem autonomia e disponibilidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.3, páginas 1047–1057 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ca20225c-8aa6-57a3-ad18-1f5b4f47c715', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Independência de localização procura permitir que a aplicação:', '["Elimine a necessidade de comunicação.","Leia sem qualquer autorização.","Atualize somente dados locais.","Acesse dados sem depender de seu site físico específico.","Ignore o significado dos atributos."]'::jsonb, 3, 'Transparência de localização separa nomes e interfaces da posição física.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.3, páginas 1047–1057 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('220ed127-4d44-5a2c-9ad5-14aafef544fc', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Fácil', 'Fragmentação horizontal corresponde principalmente a dividir uma relação por:', '["Subconjuntos de tuplas.","Subconjuntos de atributos apenas.","Índices de usuário.","Tipos de senha.","Versões de aplicação."]'::jsonb, 0, 'É associada à restrição relacional sobre grupos de linhas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.3, páginas 1047–1057 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c950402a-2914-5808-bd47-6ea000fb0b13', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Fácil', 'Fragmentação vertical corresponde principalmente a dividir uma relação por:', '["Permissões de consulta.","Subconjuntos de atributos, preservando a reconstrução necessária.","Subconjuntos de usuários.","Grupos de transações.","Datas de commit apenas."]'::jsonb, 1, 'A projeção é a operação relacional associada à fragmentação vertical.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.3, páginas 1047–1057 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('424ce931-40ef-573b-8d85-d3fb46ff3557', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Uma fragmentação vertical adequada deve permitir:', '["Descartar os atributos de ligação necessários.","Eliminar todas as chaves compartilhadas.","Aceitar combinações espúrias por padrão.","Reconstruir somente metade das tuplas.","Recompor a informação original sem perdas."]'::jsonb, 4, 'Os fragmentos precisam conservar informação suficiente para sua recomposição.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.3, páginas 1047–1057 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c7339a85-f1f8-5f3e-90c2-60eee66db2d5', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Fácil', 'Replicação significa manter:', '["Cópias de dados em mais de um local.","Uma chave primária diferente para cada consulta.","Somente um nome alternativo para uma visão.","Apenas atributos distintos em cada site.","Dados sem qualquer redundância."]'::jsonb, 0, 'Replicação é um caso de redundância que precisa ser controlada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.3, páginas 1047–1057 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('837bceaa-4e84-5fc5-8ff4-48833f4c8f13', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Uma vantagem potencial de réplicas locais é:', '["Eliminar todos os conflitos de atualização.","Reduzir acesso remoto e melhorar disponibilidade em certas condições.","Substituir qualquer backup.","Garantir dados sempre atuais sem coordenação.","Dispensar comunicação em qualquer situação."]'::jsonb, 1, 'Benefícios de leitura e disponibilidade exigem considerar também manutenção e falhas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.3, páginas 1047–1057 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c90e6d73-2d04-58be-b116-b09e56ce115b', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Qual problema acompanha atualizações em dados replicados?', '["Propagar e coordenar alterações entre as cópias.","Impossibilidade de ler dados locais.","Desaparecimento dos tipos.","Ausência de qualquer redundância.","Obrigação de remover todas as chaves."]'::jsonb, 0, 'Cópias divergentes precisam ser tratadas pela estratégia de replicação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.4, páginas 1058–1073 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('40f1103b-b996-5dc5-807d-0b99e8a3e55d', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Em consultas distribuídas, qual custo pode dominar a execução?', '["A ordem alfabética das tabelas.","Transferência de dados e troca de mensagens entre sites.","A cor do resultado.","O nome do servidor.","Somente a quantidade de caracteres do SELECT."]'::jsonb, 1, 'Latência e volume transmitido tornam a comunicação uma parte importante da otimização.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.4, páginas 1058–1073 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7e17b6d2-0bff-558a-acab-d336c63bd1a4', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Aplicar filtros no site de origem antes de transmitir resultados pode:', '["Eliminar necessariamente toda comunicação.","Impedir qualquer junção.","Reduzir o volume trafegado.","Garantir latência zero.","Mudar a condição da consulta."]'::jsonb, 2, 'A estratégia é útil quando preserva a semântica e diminui dados transferidos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.4, páginas 1058–1073 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d558a14a-23f9-5576-aa86-dbda176a7e69', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Uma semijunção pode ajudar uma consulta distribuída por:', '["Replicar obrigatoriamente todo o banco.","Eliminar o predicado de correspondência.","Confirmar transações sem participantes.","Transformar linhas em senhas.","Restringir candidatos antes de transferir tuplas completas."]'::jsonb, 4, 'Trocar informação de correspondência pode custar menos que transportar relações integrais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.4, páginas 1058–1073 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3e072279-9c28-557a-9af4-ae0a6071db2f', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Uma transação que altera dados em dois sites exige atenção especial a:', '["Um backup de tela.","Somente ordenação de colunas.","Recuperação e decisão de confirmação coordenadas.","Eliminação das chaves locais.","Apenas o nome dos índices."]'::jsonb, 2, 'A atomicidade precisa abranger os participantes, não somente cada alteração isolada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.4, páginas 1058–1073 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b14a3cbf-9530-5aa4-bf5c-af6046157aff', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Deadlocks em sistemas distribuídos podem envolver:', '["Somente recursos de um único processo local.","Dependências de espera que atravessam vários sites.","Apenas consultas sem qualquer bloqueio.","Necessariamente falhas físicas.","Somente arquivos de impressão."]'::jsonb, 1, 'A detecção e resolução podem exigir informação além da visão de um único site.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.4, páginas 1058–1073 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('582527fa-7c2d-5cb2-aedc-5fb4d6c71b5a', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Independência de SGBD busca permitir integração entre:', '["Somente tabelas do mesmo usuário.","Arquivos sem qualquer esquema.","Sistemas que podem usar produtos de banco diferentes.","Apenas réplicas idênticas em um único produto.","Aplicações sem dados."]'::jsonb, 2, 'Heterogeneidade exige tratar diferenças de interfaces, tipos e semântica.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.6, páginas 1079–1085 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5574eb12-ebc9-5d69-8818-d0efb328a58f', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Qual papel pode exercer um gateway de acesso a dados?', '["Impedir qualquer comunicação.","Substituir toda regra de negócio.","Adaptar requisições e resultados entre sistemas diferentes.","Eliminar automaticamente todas as divergências semânticas.","Criar uma única transação sem coordenação."]'::jsonb, 2, 'Adaptação de interface não resolve por si só todos os problemas de heterogeneidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.6, páginas 1079–1085 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1823ab8f-d2d7-5d03-9d3c-bead782e25b6', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Em uma arquitetura cliente/servidor, buscar uma linha por mensagem pode ser caro porque:', '["Garante uso ótimo da rede.","Sempre elimina processamento no servidor.","Transforma cada linha em chave candidata.","Multiplica a quantidade de viagens entre cliente e servidor.","Impede a existência de SQL."]'::jsonb, 3, 'Operações em conjuntos podem reduzir a sobrecarga de comunicação de acessos repetitivos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.5, páginas 1074–1078 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('acee7947-c7f1-53d4-ac9c-99a5cb820d3d', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Executar um procedimento armazenado no servidor pode ajudar a:', '["Agrupar trabalho próximo dos dados e reduzir mensagens.","Dispensar tratamento de falhas.","Tornar todos os dados públicos.","Garantir que qualquer código seja correto.","Eliminar a necessidade de autorização."]'::jsonb, 0, 'Localizar processamento no servidor pode diminuir interações, mas não remove demais requisitos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.5, páginas 1074–1078 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('35bd69b8-ba12-506e-8a7f-87ac57ebf115', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Operação contínua como objetivo distribuído significa que a falha de um site deve, idealmente:', '["Paralisar obrigatoriamente todo o sistema.","Apagar todas as réplicas.","Confirmar todas as transações incompletas.","Permitir funcionamento possível dos demais, ainda que com serviço reduzido.","Eliminar a segurança."]'::jsonb, 3, 'A disponibilidade efetiva depende da arquitetura e das dependências entre componentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 21, seção 21.3, páginas 1047–1057 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f55dee65-2d2d-5feb-92c0-7d14413d4873', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Uma carga típica de apoio à decisão se destaca por:', '["Somente pequenas atualizações unitárias previsíveis.","Ausência de agregações.","Obrigação de escrever em todas as consultas.","Impossibilidade de usar histórico.","Consultas analíticas complexas sobre grandes conjuntos de dados."]'::jsonb, 4, 'O perfil analítico difere da rotina operacional de transações curtas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.2, páginas 1105–1107 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a11e036b-6f17-5ffb-ae16-7de755a018d0', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Um banco predominantemente de leitura voltado à análise não significa que:', '["Possa manter histórico.","Nunca precise de carga ou renovação dos dados.","Seja adequado a consultas agregadas.","Possa usar índices.","Possa reunir informação de várias fontes."]'::jsonb, 1, 'O perfil de uso não elimina operações de manutenção.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.2, páginas 1105–1107 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('af38d137-83da-5e29-9ecd-3637bccc4a1c', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'No projeto analítico, a preocupação com desempenho deve ser conciliada com:', '["Ausência de documentação.","Remoção obrigatória de toda restrição.","Bom projeto lógico e controle da redundância.","Proibição de chaves.","Descarte da semântica dos dados."]'::jsonb, 2, 'Date alerta contra confundir requisitos físicos de desempenho com decisões lógicas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.3, páginas 1108–1119 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1b16ee7a-a27a-5ebd-8a98-1784f478fef5', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'A etapa de extração obtém dados:', '["Somente após apagar as fontes.","Apenas de tabelas sem chaves.","Somente de relatórios impressos.","Das fontes que alimentarão o ambiente analítico.","Exclusivamente do catálogo de senhas."]'::jsonb, 3, 'Extração integra o processo de preparação, junto de limpeza, transformação e carga.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.4, páginas 1120–1123 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9244fbf0-cc97-5ab8-83d7-3a0d5546e10c', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Padronizar códigos de município usados de formas diferentes em duas fontes é exemplo de:', '["Criptografia obrigatória.","Projeção sem atributos.","Bloqueio exclusivo global.","Transformação e consolidação de dados.","Commit de duas fases necessariamente."]'::jsonb, 3, 'A integração exige compatibilizar representações e significados das fontes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.4, páginas 1120–1123 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f01463d7-d4d7-53ca-bdb3-d67ec11e172f', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Fácil', 'Identificar datas inválidas e registros inconsistentes pertence principalmente à:', '["Classificação de índices.","Limpeza de dados.","Definição de senhas.","Fragmentação física.","Assinatura digital."]'::jsonb, 1, 'Qualidade dos dados precisa ser tratada antes e durante sua incorporação analítica.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.4, páginas 1120–1123 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('654d9241-f51c-5c48-b6c8-12d1b7d1a233', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Uma área intermediária de preparação pode servir para:', '["Organizar a integração antes da carga no destino analítico.","Garantir ausência de qualquer falha.","Eliminar a necessidade de transformação.","Substituir automaticamente o banco de origem.","Guardar somente privilégios."]'::jsonb, 0, 'O capítulo discute depósitos operacionais também como apoio à preparação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.4, páginas 1120–1123 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('be6dd5c1-61c2-5705-89d5-68a5dce8bc94', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Um data mart pode ser entendido como:', '["Um ambiente analítico especializado em determinado domínio ou finalidade.","Uma linguagem de consulta.","Um backup sem possibilidade de leitura.","Um índice obrigatório de todo warehouse.","Uma transação não confirmada."]'::jsonb, 0, 'O recorte especializado o distingue de um warehouse de alcance mais amplo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.5, páginas 1124–1132 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('762c09b1-96a4-5f43-bc3f-14a54fe88c4e', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Uma razão para separar processamento operacional e analítico é:', '["Evitar conflitos entre cargas com perfis diferentes.","A impossibilidade matemática de consultar dados operacionais.","A ausência de tipos em ambientes operacionais.","A obrigação de usar produtos diferentes.","A proibição de manter dados históricos."]'::jsonb, 0, 'Consultas analíticas extensas podem competir com transações operacionais por recursos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.5, páginas 1124–1132 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5a625490-88bf-541d-ae96-60c8ede507dd', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Em um esquema em estrela, a tabela de fatos contém principalmente:', '["Somente nomes de usuários.","Exclusivamente permissões.","Medidas e referências às dimensões no grão escolhido.","Somente programas de carga.","Apenas definições de tipos."]'::jsonb, 2, 'Fatos representam eventos ou observações analisáveis em determinado nível de detalhe.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.5, páginas 1124–1132 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('361634d4-224a-5543-90ea-ef2bac924b19', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Uma dimensão representa principalmente:', '["Apenas totais gerais sem descrição.","Contextos de análise, como tempo, produto ou local.","Um mecanismo de autenticação.","Uma transação distribuída.","Somente a quantidade física de discos."]'::jsonb, 1, 'Dimensões organizam perspectivas pelas quais as medidas podem ser analisadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.5, páginas 1124–1132 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cfbd5f6c-4c3e-513d-a8fd-9cbe3441a6a9', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Definir o grão de uma tabela de fatos significa estabelecer:', '["A ordem física obrigatória das linhas.","O tamanho do nome da tabela.","A senha do processo de carga.","A quantidade de usuários.","O que cada linha de fato representa."]'::jsonb, 4, 'Misturar níveis de detalhe sem controle pode produzir agregações incorretas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.5, páginas 1124–1132 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d9145c03-74ba-580e-903b-6566b7d74093', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Guardar totais diários e mensais como se fossem fatos do mesmo nível pode causar:', '["Eliminação da redundância.","Garantia automática de exatidão.","Ausência de necessidade de filtros.","Dupla contagem em agregações inadequadas.","Independência de qualquer dimensão."]'::jsonb, 3, 'É necessário distinguir o grão e a semântica dos valores agregados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.5, páginas 1124–1132 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('73cd5b30-bbe1-59b7-b091-38f103dc227f', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'OLAP está associado à análise de dados por:', '["Múltiplas dimensões e níveis de agregação.","Apenas verificação de senhas.","Exclusivamente recuperação de mídia.","Navegação física por ponteiros.","Somente edição unitária de registros."]'::jsonb, 0, 'A perspectiva multidimensional pode ser apoiada por diferentes representações e implementações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.6, páginas 1133–1143 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('17c06e3f-3483-50ff-98da-0960813e1263', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Passar de totais anuais para mensais corresponde a:', '["Roll-up.","Revoke.","Rollback.","Checkpoint.","Drill-down."]'::jsonb, 4, 'O detalhamento desce na hierarquia da dimensão temporal.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.6, páginas 1133–1143 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('06653966-5e5c-5074-b270-bf59802a930a', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Fácil', 'Consolidar totais municipais em totais estaduais corresponde a:', '["Drill-down.","Criação de savepoint.","Roll-up.","Undo.","Semijunção obrigatória."]'::jsonb, 2, 'A operação sobe para um nível mais agregado da dimensão.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.6, páginas 1133–1143 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5144ba57-3a92-5201-813e-95064e59f9f3', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'O CUBE sobre duas dimensões permite calcular:', '["Apenas produtos cartesianos.","Apenas a dimensão escolhida como chave.","Somente o total mais detalhado.","Agregações para todas as combinações de subconjuntos dessas dimensões.","Somente uma soma sem agrupamento."]'::jsonb, 3, 'Inclui agrupamentos detalhados, parciais e total geral conforme a semântica da agregação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.6, páginas 1133–1143 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8fa7bc35-9492-531f-9800-ac2eb7ed2f22', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Duas dimensões independentes de agrupamento admitem quantos subconjuntos para um CUBE completo?', '["2.","5.","3.","8.","4."]'::jsonb, 4, 'Os subconjuntos são vazio, primeira dimensão, segunda dimensão e ambas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.6, páginas 1133–1143 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7ea5b47b-3154-50f4-a559-12a6403e1852', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Fácil', 'Mineração de dados procura principalmente:', '["Somente a definição de visões.","Somente uma linha por sua chave.","Padrões interessantes em grandes coleções de dados.","Apenas concessões de privilégio.","Exclusivamente arquivos corrompidos."]'::jsonb, 2, 'A análise exploratória pode apoiar decisões e detectar comportamentos incomuns.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.7, páginas 1144–1146 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7f2458b1-b652-533f-aed0-2bc495879ea5', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Detectar um aumento incomum de operações de um cartão é exemplo de:', '["Normalização até FNBC.","Busca de padrões ou anomalias para apoiar investigação.","Uma dependência funcional trivial.","Prova definitiva de fraude em qualquer caso.","Restauração de backup."]'::jsonb, 1, 'O padrão é um indício para análise, não uma conclusão automática sobre sua causa.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 22, seção 22.7, páginas 1144–1146 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fb5d4de9-d85f-5d2e-ac3c-bc391f379e14', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Um banco temporal registra, além dos fatos:', '["A referência temporal de sua validade ou ocorrência conforme o modelo.","Somente valores agregados.","Exclusivamente datas de backups.","Somente o horário de login do DBA.","Apenas o tempo de execução do SELECT."]'::jsonb, 0, 'O capítulo trata de fatos associados a pontos e períodos temporais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.1, páginas 1159–1164 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('910f29a3-6253-5087-a443-7e7497d8a4ec', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Guardar apenas o departamento atual de um empregado impede responder diretamente:', '["Quantos empregados atuais estão cadastrados.","Se o registro atual existe.","Qual é seu departamento atual.","Qual identificador ele possui.","Em quais departamentos ele trabalhou no passado."]'::jsonb, 4, 'Estado atual e histórico são conteúdos informacionais diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.1, páginas 1159–1164 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('59617176-3cfe-5550-b207-8902e829eb33', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Acrescentar colunas de início e fim a tabelas resolve toda complexidade temporal?', '["Sim, elimina sobreposições automaticamente.","Sim, garante consistência de todos os períodos.","Não, porque datas não podem ser atributos.","Não; consultas e restrições ainda podem tornar-se complexas.","Sim, dispensa qualquer validação."]'::jsonb, 3, 'O capítulo usa essa dificuldade para motivar suporte explícito a intervalos e operadores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.2, páginas 1165–1173 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('09fbc6a2-6e03-5146-94d3-3495fd6c81c2', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'Tratar [d04:d10] como um único valor permite:', '["Definir operadores e restrições próprios de intervalos.","Dispensar tipos.","Eliminar a ordem temporal.","Transformar todo período em texto sem semântica.","Ignorar seus limites."]'::jsonb, 0, 'O intervalo é um valor de tipo apropriado, não apenas dois campos sem operações comuns.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6d50f705-f577-5055-a7fc-b47f5074c419', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Qual requisito básico deve ser definido para o tipo de ponto considerado no capítulo?', '["Um índice físico obrigatório.","Uma ordenação total dos valores.","Uma chave estrangeira em cada valor.","Uma operação de commit por data.","Um nome de usuário por ponto."]'::jsonb, 1, 'Comparar pontos é fundamental para definir início, fim e relações entre intervalos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ce09b2f3-bf28-58f5-914d-6c9a990750cf', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'Um intervalo fechado com início maior que o fim deve ser:', '["Confirmado sem restrições.","Aceito como intervalo de duração negativa.","Rejeitado como intervalo inválido nessa convenção.","Tratado como uma chave candidata.","Convertido em NULL automaticamente."]'::jsonb, 2, 'A validade dos limites integra a definição do tipo de intervalo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('df1ee074-2dfb-5ebd-9fb7-8c7f8254ddf4', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Fácil', 'Nos intervalos fechados de dias inteiros, [2:5] INTERSECT [4:8] é:', '["[2:3].","[2:8].","[4:5].","[1:8].","[6:8]."]'::jsonb, 2, 'A interseção contém os pontos presentes em ambos os intervalos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b3db1102-e0fd-5b40-a3ee-9faa02d69bb8', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Nos intervalos fechados de dias inteiros, [2:5] e [6:8] são:', '["Iguais.","Adjacentes, sem ponto em comum.","Necessariamente inválidos.","Um contido no outro.","Sobrepostos nos pontos 5 e 6."]'::jsonb, 1, 'Com granularidade diária, o ponto seguinte a 5 é 6; a convenção dos limites importa.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f113a777-6df9-5e68-ae52-90f107c71830', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Nos intervalos fechados de dias inteiros, unir [2:5] e [4:8] como período contínuo resulta em:', '["[2:8].","[4:5].","[6:8].","[4:8] apenas.","[2:3]."]'::jsonb, 0, 'Os intervalos se sobrepõem e sua união forma um único intervalo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b5a6c38a-57b7-5550-a911-310507bb04c8', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Fácil', 'O intervalo fechado [3:3], na convenção apresentada, representa:', '["Um intervalo vazio obrigatoriamente.","Um período infinito.","Uma variável sem valor.","Um intervalo inválido.","Um intervalo unitário com um ponto."]'::jsonb, 4, 'Limites iguais podem representar um único ponto do tipo considerado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('39e288b2-75e3-57d5-9017-21567c12f7fe', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'O operador EXPAND transforma intervalos de uma relação unária em:', '["Somente seus pontos finais.","Cópias de todas as tabelas.","Intervalos unitários para os pontos cobertos.","Linhas sem qualquer tipo.","Uma contagem sem relação de resultado."]'::jsonb, 2, 'A forma expandida explicita a cobertura ponto a ponto.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.4, páginas 1182–1196 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6a87eec5-bfc5-5404-95be-f227dcac085c', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'COLLAPSE procura representar a mesma cobertura temporal usando:', '["Números sem ordenação.","Uma linha para cada usuário.","Somente o primeiro ponto.","A exclusão de todos os intervalos sobrepostos.","Intervalos máximos resultantes da consolidação apropriada."]'::jsonb, 4, 'A consolidação preserva os pontos cobertos e reduz representações redundantes ou fragmentadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.4, páginas 1182–1196 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7ac20306-34b8-54c5-b704-2fa4363afdd1', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'PACK e UNPACK generalizam o tratamento de intervalos para:', '["Apenas logs de recuperação.","Dados sem qualquer tempo.","Tipos sem comparação.","Somente tabelas sem atributos.","Relações que podem conter outros atributos além do intervalo."]'::jsonb, 4, 'O processamento considera os demais atributos ao agrupar ou expandir a informação temporal.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.4, páginas 1182–1196 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9ed07f89-4c4a-5c48-80b2-212b1f19a8eb', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Consolidar períodos adjacentes do mesmo empregado e mesmo cargo pode:', '["Eliminar a necessidade de identificar o empregado.","Criar um novo ponto sem data.","Mudar o cargo para todos os empregados.","Preservar a informação temporal com uma representação menos fragmentada.","Apagar necessariamente o histórico."]'::jsonb, 3, 'A consolidação depende de os demais valores e a cobertura temporal serem compatíveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.4, páginas 1182–1196 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a1c54fe3-02d0-5610-ad26-d1b0531cd8e1', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Difícil', 'Por que operadores temporais generalizados são úteis?', '["Dispensam a semântica das consultas.","Eliminam qualquer referência ao tempo.","Substituem autenticação.","Abreviam padrões de desempacotar, operar e reempacotar, com possibilidade de otimização.","Obrigam expansão física de todos os dias."]'::jsonb, 3, 'A semântica pode ser definida por expansão sem exigir uma implementação ingênua dessa expansão.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.5, páginas 1197–1203 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d8569a93-4726-5384-9973-ba9f9cf31658', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Históricos de nome e endereço mudam em datas diferentes. Separá-los temporalmente pode evitar:', '["Toda junção de consultas.","A existência de identificadores.","Qualquer restrição temporal.","Repetição e fragmentação desnecessárias de fatos com ritmos distintos de mudança.","A necessidade de armazenar datas."]'::jsonb, 3, 'O projeto deve considerar quais atributos variam juntos e quais possuem históricos independentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.6, páginas 1204–1212 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4d0ef74f-0d33-5f3d-8933-5d55eb7b5632', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Dois cargos exclusivos para o mesmo empregado em períodos sobrepostos podem representar:', '["Somente uma diferença de ordenação.","Contradição temporal, conforme a regra de exclusividade.","Uma DF trivial garantida.","Um backup duplicado.","Ausência de integridade referencial apenas."]'::jsonb, 1, 'A restrição precisa proibir estados simultâneos incompatíveis no período relevante.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.7, páginas 1213–1220 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4d876c86-17b0-55b2-84dd-a465d422b17f', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Difícil', 'Uma chave (empregado, intervalo) impede sozinha toda sobreposição de períodos do empregado?', '["Não, porque chaves não existem em dados temporais.","Não; intervalos diferentes ainda podem compartilhar pontos.","Sim, desde que o empregado seja numérico.","Sim, pois intervalos distintos nunca se cruzam.","Sim, se houver duas colunas."]'::jsonb, 1, 'Unicidade da combinação não é uma restrição de não sobreposição.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.7, páginas 1213–1220 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('51e6fa85-5b0d-52ac-b4a9-424130f5cde7', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Difícil', 'Uma referência temporal entre dependente e entidade exige atenção a:', '["Cobertura dos períodos em que a entidade referenciada precisa existir.","Somente quantidade de índices.","A ordem de criação das tabelas.","Apenas existência atual, em qualquer cenário.","Somente igualdade textual dos nomes."]'::jsonb, 0, 'Referência temporal pode exigir existência durante todo o intervalo relevante, não em um instante arbitrário.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.7, páginas 1213–1220 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4922856b-09e7-5f9d-ae60-c05b940fa78c', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Ao escrever uma questão sobre sobreposição de períodos, por que declarar limites e granularidade?', '["Para ocultar a semântica do intervalo.","Para eliminar todos os pontos finais.","Para evitar respostas diferentes decorrentes de convenções temporais distintas.","Para transformar datas em índices.","Para tornar dispensável a comparação."]'::jsonb, 2, 'Intervalos abertos, fechados e diferentes unidades de tempo podem alterar relações de adjacência e interseção.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 23, seção 23.3, páginas 1174–1181 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('63b6fd20-48b5-507c-959f-063d1af3e7ca', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Fácil', 'Na lógica clássica, uma tautologia é uma fórmula:', '["Verdadeira em exatamente uma interpretação.","Que representa uma chave estrangeira.","Falsa em toda interpretação.","Verdadeira em toda interpretação pertinente.","Sem conectivos."]'::jsonb, 3, 'Validade lógica não depende de um estado particular do banco.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.3, páginas 1234–1240 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c1b4e645-41b0-5285-acef-717fb5c0e2cb', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Qual expressão é uma tautologia da lógica bivalorada?', '["P OR NOT P.","P AND Q, para quaisquer valores.","P AND NOT P.","P AND FALSE.","NOT TRUE."]'::jsonb, 0, 'A lei do terceiro excluído é válida na lógica clássica bivalorada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.3, páginas 1234–1240 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8bc80299-298e-5e27-a222-c3305c7132e9', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'A implicação P ⇒ Q é falsa somente quando:', '["P é falsa e Q é verdadeira.","P é verdadeira e Q é falsa.","Ambas são verdadeiras.","P é falsa, independentemente de Q.","Ambas são falsas."]'::jsonb, 1, 'A implicação material equivale a NOT P OR Q.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.3, páginas 1234–1240 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c2949645-5d65-5210-bb9d-95e7d2a8ea15', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'De P e P ⇒ Q, inferir Q corresponde a:', '["Modus ponens.","Comutatividade da união.","Replicação.","Normalização.","Controle de acesso."]'::jsonb, 0, 'A regra permite aplicar uma implicação cuja premissa foi estabelecida.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.3, páginas 1234–1240 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0012514b-ad0d-57bf-83c4-0f630401adb8', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Uma fórmula satisfatível é aquela que:', '["Não possui variáveis por definição.","É verdadeira em todas obrigatoriamente.","É falsa em todas.","Contém apenas nomes de tabelas.","É verdadeira em pelo menos uma interpretação."]'::jsonb, 4, 'Satisfatibilidade é mais fraca que validade universal.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.3, páginas 1234–1240 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ec408cd9-ab28-56f4-ba6b-2c271bef6215', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'O cálculo de predicados acrescenta ao cálculo proposicional, entre outros recursos:', '["Páginas físicas e trilhas.","Variáveis e quantificadores.","Senhas e permissões.","Somente novos nomes para AND e OR.","Backups e logs."]'::jsonb, 1, 'Esses recursos permitem descrever objetos e propriedades de forma mais expressiva.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.4, páginas 1241–1250 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('33c4b8cf-0237-5dd8-8bff-2730151df3b0', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Uma interpretação atribui significado a símbolos em relação a:', '["Um plano de junção exclusivo.","Um índice agrupado.","Uma sessão obrigatoriamente autenticada.","Um universo de discurso.","Uma ordem física fixa de disco."]'::jsonb, 3, 'Constantes, predicados e funções precisam ser interpretados sobre um domínio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.4, páginas 1241–1250 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('88a29770-3a7f-5e1d-b13e-c3436ead6122', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Um modelo de um conjunto de fórmulas é uma interpretação em que:', '["Pelo menos uma delas é obrigatoriamente falsa.","Os valores estão fisicamente ordenados.","Todas essas fórmulas são verdadeiras.","Todas são nomes de arquivos.","Nenhuma fórmula pode ter quantificadores."]'::jsonb, 2, 'Satisfazer conjuntamente os axiomas caracteriza o modelo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.4, páginas 1241–1250 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e98ec565-f733-509b-a1f0-18ba61868d81', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'No contexto lógico, unificar termos procura:', '["Criar uma senha única.","Confirmar transações.","Eliminar todo predicado.","Ordenar linhas em disco.","Uma substituição que os torne correspondentes."]'::jsonb, 4, 'A substituição de variáveis permite aplicar regras de inferência a termos compatíveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.4, páginas 1241–1250 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6bad8809-b16b-5bdd-ab9d-16d6e5cdbba0', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Difícil', 'Ao unificar p(X,3) com p(2,Y), uma substituição adequada é:', '["X=Y=0.","Nenhuma, pois predicados nunca se unificam.","X=3 e Y=2.","X=3 e Y=3.","X=2 e Y=3."]'::jsonb, 4, 'A correspondência exige igualar os argumentos nas mesmas posições.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.4, páginas 1241–1250 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ae4d2cb1-4796-504d-9b75-0c8d2fd3bd39', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Na visão da teoria da prova, responder uma consulta equivale conceitualmente a:', '["Percorrer somente endereços físicos.","Desativar restrições.","Demonstrar consequências dos axiomas do banco.","Executar apenas uma projeção.","Ordenar todas as tabelas."]'::jsonb, 2, 'A resposta decorre de fatos e regras, não apenas de tuplas explicitamente armazenadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.5, páginas 1251–1255 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9613d221-3075-5ce1-b9ce-19d731b11d89', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'O banco extensional contém principalmente:', '["Fatos básicos explícitos.","Apenas predicados sem argumentos.","Apenas planos de consulta.","Exclusivamente senhas.","Somente regras recursivas."]'::jsonb, 0, 'O extensional contrasta com a parte intensional formada por regras e restrições.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.6, páginas 1256–1263 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1aa004f1-5989-536e-92f1-411ca5622fb8', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'O banco intensional reúne principalmente:', '["Apenas registros de acesso.","Somente instruções de backup.","Somente cópias físicas das linhas básicas.","Exclusivamente índices.","Regras de dedução e restrições."]'::jsonb, 4, 'A combinação de base factual e regras permite deduzir novos fatos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.6, páginas 1256–1263 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0c787852-a86b-5968-a542-72425d1aeba7', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Um SGBD dedutivo distingue-se por poder:', '["Aceitar qualquer contradição sem efeito.","Inferir fatos a partir de fatos básicos e regras declaradas.","Armazenar apenas texto.","Confirmar automaticamente qualquer suposição.","Dispensar toda base de dados."]'::jsonb, 1, 'A capacidade dedutiva amplia o conteúdo consultável além dos fatos explicitamente inseridos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.6, páginas 1256–1263 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7efb6ff5-d68b-5271-9959-fdde383a7bb2', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Considere ligado(a,b) e ligado(b,c), com regra de transitividade para alcança. Qual fato pode ser deduzido?', '["b=c.","a=b.","alcança(a,c).","ligado(a,c), como fato básico necessariamente inserido.","ligado(c,a), obrigatoriamente."]'::jsonb, 2, 'Alcançabilidade indireta pode ser derivada sem afirmar uma ligação direta básica.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.6, páginas 1256–1263 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3a05f48a-3d91-5e3e-afa3-96564a172cd3', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Difícil', 'Uma cláusula de Horn admite, na forma de cláusulas, no máximo:', '["Um literal positivo.","Duas variáveis no total.","Um símbolo em toda a fórmula.","Zero predicados.","Um argumento por predicado."]'::jsonb, 0, 'Essa restrição é importante para a programação lógica e sistemas dedutivos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.6, páginas 1256–1263 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d9f7f3b3-5da9-57e8-8472-4eb0425059b9', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Uma regra dedutiva e uma restrição de integridade têm papéis distintos porque:', '["A regra nunca possui premissas.","A regra substitui qualquer validação.","A regra deriva fatos; a restrição limita estados admissíveis.","A restrição sempre insere linhas.","Ambas são arquivos físicos."]'::jsonb, 2, 'O banco intensional pode conter ambas, sem que suas funções sejam idênticas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.6, páginas 1256–1263 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dbc4ae84-eb43-5d2b-af0e-ad3f598020b6', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Fácil', 'Uma definição de ancestral em termos de pai e ancestral exemplifica:', '["Autenticação.","Recursão.","Criptografia.","Somente projeção sem composição.","Fragmentação."]'::jsonb, 1, 'A regra faz referência ao próprio predicado derivado e precisa de casos básicos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.7, páginas 1264–1271 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3ee96128-2de3-5c24-bc72-24ed0d565836', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Avaliação por ponto fixo de regras positivas termina quando:', '["O primeiro fato foi encontrado.","Uma tupla é renomeada.","Um usuário fecha a tela.","Uma nova aplicação das regras não acrescenta fatos.","A ordem das colunas muda."]'::jsonb, 3, 'Sobre domínio finito, o processo monotônico pode estabilizar no conjunto de consequências.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.7, páginas 1264–1271 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('24cc2698-c846-5c37-8b21-0d8b19b94778', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Difícil', 'Uma técnica que usa a estrutura de uma consulta para limitar derivações irrelevantes busca principalmente:', '["Mudar fatos básicos arbitrariamente.","Eliminar a regra recursiva do significado.","Ignorar os parâmetros da consulta.","Reduzir o trabalho de avaliação recursiva preservando as respostas.","Substituir o resultado por uma estimativa."]'::jsonb, 3, 'O capítulo discute estratégias de processamento recursivo voltadas à eficiência.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 24, seção 24.7, páginas 1264–1271 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f9aa5560-52bb-5083-9ff6-561058440c3b', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Na correspondência terminológica proposta por Date, objetos imutáveis aproximam-se de:', '["Sessões.","Valores.","Índices físicos.","Logs.","Variáveis atualizáveis."]'::jsonb, 1, 'O autor distingue valores imutáveis de variáveis que podem assumir valores diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ab703467-3c9e-5977-a185-da2ca3926f24', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Objetos mutáveis aproximam-se, na terminologia tradicional usada pelo autor, de:', '["Variáveis.","Somente strings imutáveis.","Apenas funções booleanas.","Tipos sem instâncias.","Constantes matemáticas."]'::jsonb, 0, 'A possibilidade de alterar estado corresponde à noção de variável.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d593ceeb-b7ec-5d64-991f-03951a97e20e', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Fácil', 'Encapsular um objeto significa principalmente:', '["Proibir qualquer operação de leitura.","Controlar seu acesso por uma interface, ocultando detalhes de representação.","Expor todos os endereços internos.","Copiar o objeto para cada usuário.","Transformar toda variável em constante."]'::jsonb, 1, 'A interface permite usar o objeto sem depender de sua implementação interna.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('63745ed4-4372-576c-a845-30c303cefc9a', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Alterar a representação interna preservando métodos e contratos públicos favorece:', '["Ausência de qualquer abstração.","Independência das aplicações em relação à implementação.","Dependência de ponteiros físicos.","Eliminação de todos os tipos.","Obrigação de reescrever cada cliente."]'::jsonb, 1, 'O encapsulamento protege consumidores quando a interface permanece compatível.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('90378e5b-0a23-50e6-8756-28ecdad08c6f', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Fácil', 'Um método é comparado no capítulo a:', '["Um operador aplicável aos objetos correspondentes.","Um índice obrigatório.","Uma página física.","Uma chave estrangeira por definição.","Uma cópia de backup."]'::jsonb, 0, 'Métodos descrevem operações; dados e operações não devem ser confundidos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1880d781-044f-5411-8e70-64ee5fe6da51', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'Enviar uma mensagem a um objeto corresponde, essencialmente, a:', '["Alterar a chave primária.","Criar um esquema externo.","Confirmar uma transação.","Invocar uma operação com um destinatário destacado.","Copiar todo o banco pela rede necessariamente."]'::jsonb, 3, 'Mensagem, nesse contexto, é um conceito de invocação, não necessariamente de transporte em rede.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('91a49ec9-34a4-57fb-bfe6-dc927d3820c6', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Uma classe e a coleção atual de suas instâncias são conceitos idênticos?', '["Sim, se houver um único método.","Sim, somente em bancos persistentes.","Não, porque classes não podem ter instâncias.","Não; é preciso distinguir definição de tipo e coleção de objetos.","Sim, toda classe é apenas seu conteúdo atual."]'::jsonb, 3, 'A confusão entre tipo e coleção reaparece na crítica relacional/objeto do capítulo seguinte.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.2, páginas 1294–1299 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cb31f6c1-42cd-5d37-a12f-e678823ee11e', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Fácil', 'Qual é a finalidade de uma identidade de objeto, OID?', '["Confirmar suas alterações.","Somar seus atributos numéricos.","Distinguir e referenciar um objeto independentemente de seus atributos de negócio.","Validar automaticamente regras do domínio.","Ordenar todos os nomes."]'::jsonb, 2, 'Identidade do objeto e valores de suas propriedades são noções diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.3, páginas 1300–1311 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d57eeec4-7e50-5724-89d8-93cb145cf286', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Dois objetos possuem atributos de negócio iguais. Isso implica necessariamente a mesma identidade?', '["Sim, caso existam métodos.","Sim, se os atributos forem texto.","Sim, sempre.","Não, porque objetos nunca possuem atributos.","Não, em um sistema com identidade de objetos."]'::jsonb, 4, 'A igualdade do estado observado não exige identidade do objeto.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.3, páginas 1300–1311 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('01612ac2-6794-54f0-acb9-72e6a247ea04', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Se um objeto altera seu nome e mantém a mesma OID, isso ilustra:', '["Ausência de referência.","Mudança obrigatória de identidade.","Criação automática de outro tipo.","Persistência da identidade apesar de mudança de estado.","Imutabilidade do objeto."]'::jsonb, 3, 'A identidade não precisa ser calculada a partir do nome de negócio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.3, páginas 1300–1311 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('22a6617d-e205-53ac-a16e-764d5d410d18', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Expor diretamente variáveis internas de um objeto pode enfraquecer:', '["O número de usuários.","A ordenação de nomes de classes.","O encapsulamento da representação.","A possibilidade de ter métodos.","A existência de qualquer valor."]'::jsonb, 2, 'Clientes podem tornar-se dependentes de detalhes que deveriam permanecer internos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.3, páginas 1300–1311 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a9bc25ea-e68a-5436-9076-180212dcab4a', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Médio', 'Referências entre objetos permitem representar:', '["Apenas tabelas sem tipo.","Sempre relacionamentos um para um.","Exclusivamente restrições de acesso.","Somente valores sem identidade.","Associações navegáveis entre suas instâncias."]'::jsonb, 4, 'A cardinalidade e a integridade dessas associações ainda precisam ser especificadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.3, páginas 1300–1311 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('866b6c17-e56d-581b-9707-620dda816e1b', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'A existência de referências a objetos garante automaticamente qualquer regra de exclusão do domínio?', '["Não; é preciso definir e implementar a política apropriada.","Sim, se os nomes forem únicos.","Não, porque objetos não podem ser excluídos em nenhum sistema.","Sim, referências implementam toda regra de negócio.","Sim, desde que haja uma OID."]'::jsonb, 0, 'Gerenciamento de referências não equivale a um conjunto completo de restrições declarativas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.4, páginas 1312–1325 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fc09ed4f-ff72-5a6d-9fd0-828681e7c3c7', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Excluir um objeto pai deve necessariamente excluir todos os objetos que ele referencia?', '["Sim, qualquer referência implica propriedade exclusiva.","Não; propriedade, compartilhamento e regras de exclusão precisam ser considerados.","Sim, inclusive objetos compartilhados por outros pais.","Não, porque exclusões são proibidas.","Sim, em todos os modelos de objetos."]'::jsonb, 1, 'Uma associação por referência não determina, sozinha, o ciclo de vida dos objetos relacionados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.4, páginas 1312–1325 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3d43e118-cb19-5c0c-9f60-7ebb053c00b2', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Qual limitação pode surgir se apenas métodos predefinidos permitirem acesso aos objetos?', '["Proibição de objetos imutáveis.","Eliminação da necessidade de índices.","Impossibilidade de definir classes.","Garantia automática de toda consulta futura.","Dificuldade de formular consultas ad hoc não previstas."]'::jsonb, 4, 'A interface de operações precisa atender também a necessidades de consulta não antecipadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.5, páginas 1326–1336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7e01df4d-e47c-5997-b2cd-0fde65e48bfc', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Implementar integridade somente em métodos escritos pela aplicação exige atenção a:', '["Correção do código e cobertura de todos os caminhos de atualização.","Somente a quantidade de letras do método.","Apenas o nome da classe.","Exclusivamente a ordem dos arquivos.","A ausência de qualquer regra."]'::jsonb, 0, 'Um caminho que contorne a validação pode permitir estado inválido.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.5, páginas 1326–1336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d13b1d2c-ecdc-5346-9675-a6ccd9fb363a', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Manter referências nos dois sentidos entre objetos exige:', '["Confirmar cada campo separadamente.","Ignorar uma das direções.","Criar identidades iguais para todos os objetos.","Eliminar todos os métodos.","Coordenar alterações para preservar sua consistência."]'::jsonb, 4, 'Referências inversas não devem divergir quando a associação muda.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.5, páginas 1326–1336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d653999f-24d6-52ed-9636-8b60f7f54b42', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Coleta de lixo de objetos inalcançáveis equivale a implementar todas as regras de integridade referencial do negócio?', '["Sim, se houver uma classe raiz.","Não, porque coleta de lixo nunca remove objetos.","Não; a política de alcançabilidade não cobre necessariamente essas regras.","Sim, desde que não existam índices.","Sim, são conceitos idênticos."]'::jsonb, 2, 'Gerenciar memória ou persistência por referências não substitui a semântica de exclusão exigida pelo domínio.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.5, páginas 1326–1336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f1cd8cd4-6f80-573b-9bb2-d18668623169', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Uma linguagem unificada para programa e banco busca reduzir:', '["A necessidade de qualquer tipo.","A possibilidade de usar consultas.","A existência de dados persistentes.","O descasamento entre os modelos e formas de acesso usados nessas camadas.","A necessidade de regras de negócio."]'::jsonb, 3, 'A integração pode reduzir conversões conceituais, sem eliminar os demais requisitos de um SGBD.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.5, páginas 1326–1336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('15d1550e-209a-5337-b188-053e2e1e6e7a', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Qual avaliação respeita a análise crítica de Date sobre sistemas de objetos?', '["Métodos substituem a necessidade de dados.","Persistência dispensa recuperação.","Tipos, operadores e encapsulamento são úteis, mas não dispensam integridade e consultas adequadas.","Identidade resolve automaticamente qualquer restrição.","Objetos tornam toda consulta ad hoc desnecessária."]'::jsonb, 2, 'O capítulo examina tanto recursos úteis quanto insuficiências de certas abordagens.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 25, seção 25.5, páginas 1326–1336 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('82c71ce3-42d2-56f8-9925-8ea66c4a5de4', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Na aproximação defendida por Date, recursos de objetos devem ser integrados sobre:', '["Tabelas sem restrições.","Ausência de tipos definidos pelo usuário.","Um arquivo exclusivo por aplicação.","Navegação física obrigatória.","Uma base conceitual relacional coerente."]'::jsonb, 4, 'O autor sustenta a manutenção dos princípios relacionais na integração.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.1, páginas 1357–1360 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a145b459-1490-5f29-aaab-2f032fc42df8', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Qual recurso é central para a visão relacional/objeto defendida pelo autor?', '["Remoção de visões.","Exclusão de chaves candidatas.","Tipos definidos pelo usuário com operadores apropriados.","Ponteiros obrigatórios visíveis ao usuário.","Uma tabela por método."]'::jsonb, 2, 'Suporte adequado a domínios permite lidar com valores de maior complexidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.1, páginas 1357–1360 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5f27b585-b5e5-5135-8492-158e10486435', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Qual equivalência é identificada como o primeiro grande erro?', '["Valor = valor.","Relação = valor relacional.","Classe de objetos = tipo, na interpretação de domínio.","Classe de objetos = relvar.","Operador de leitura = operação sem atualização."]'::jsonb, 3, 'O autor critica confundir o conceito de tipo com uma variável de relação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.2, páginas 1361–1371 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d305277f-3b90-5500-957c-dd90cc122b33', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Na equivalência preferida pelo autor, a classe de objetos aproxima-se de:', '["Um índice físico.","Um domínio ou tipo.","Um arquivo de log.","Uma relvar obrigatoriamente.","Uma transação."]'::jsonb, 1, 'Essa leitura separa a definição de valores das coleções armazenadas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.2, páginas 1361–1371 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f2c87215-fd96-56cd-9aad-717e30e2d28b', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'Por que uma relvar não deve ser tratada simplesmente como um tipo?', '["Porque tipos são sempre arquivos.","Porque relvars não admitem restrições.","Porque relvars não possuem valores.","Porque tipos nunca possuem operadores.","Ela é uma variável que assume valores relacionais, não o conjunto de valores admissíveis de um domínio."]'::jsonb, 4, 'A distinção tipo/variável é essencial à crítica do capítulo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.2, páginas 1361–1371 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('287606eb-812a-58f1-9ff1-e177ab3ed63d', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Difícil', 'Uma projeção gera uma nova relação. Isso exige definir automaticamente uma nova classe com métodos próprios?', '["Sim, toda consulta exige uma nova classe persistente.","Sim, antes de qualquer leitura.","Não; o resultado possui tipo relacional inferível sem essa equivalência artificial.","Não, porque projeções não produzem relações.","Sim, apenas quando há uma coluna."]'::jsonb, 2, 'O fechamento relacional deve continuar natural para resultados derivados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.2, páginas 1361–1371 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2f6e79f4-fa71-597b-b3a9-1a8577d8833a', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Uma tabela armazena valores de vários atributos tipados. Seus tipos devem ser confundidos com a própria tabela?', '["Não; os domínios dos atributos e a relvar exercem papéis distintos.","Sim, pois tipo e variável são sinônimos.","Sim, apenas em sistemas com métodos.","Não, porque tabelas não possuem atributos.","Sim, toda coluna é uma cópia da tabela."]'::jsonb, 0, 'Uma tabela pode usar tipos definidos pelo usuário sem se tornar equivalente a um desses tipos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.2, páginas 1361–1371 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dbf68a9e-9555-5356-a35e-4d9ea5465b08', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'O segundo grande erro, na terminologia de Date, consiste em:', '["Manter índices internamente.","Misturar ponteiros e relações no nível do modelo.","Usar valores numéricos em atributos.","Permitir expressões relacionais aninhadas.","Definir tipos próprios."]'::jsonb, 1, 'A crítica é à exposição conceitual de ponteiros, não a toda técnica física de implementação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.3, páginas 1372–1377 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2f3eeae4-3445-51d2-9a71-646a1847abd2', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Um SGBD usa ponteiros internamente em um índice. Isso, sozinho, comete o segundo grande erro?', '["Sim, qualquer implementação com ponteiros deixa de ser relacional.","Não, porque índices não podem conter referências.","Sim, se o índice for usado em consulta.","Não; a crítica se refere aos ponteiros expostos no modelo de dados.","Sim, mesmo sem exposição ao usuário."]'::jsonb, 3, 'Modelo lógico e organização física precisam ser distinguidos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.3, páginas 1372–1377 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d93f58eb-e634-502a-902d-aadb7272b354', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Difícil', 'O princípio da informação estabelece, em termos relacionais, que a informação seja representada por:', '["Valores em relações.","Somente nomes de arquivos.","Endereços físicos manipulados pelas aplicações.","Métodos sem valores.","Ponteiros externos obrigatórios."]'::jsonb, 0, 'A crítica à mistura de ponteiros considera a uniformidade da representação informacional.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.3, páginas 1372–1377 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5f2ec4d1-923f-5503-b2f4-1fccc41f2572', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Por que exigir navegação por referências pode enfraquecer a uniformidade relacional?', '["Porque garante fechamento automaticamente.","Cria formas de acesso distintas das operações sobre valores em relações.","Porque elimina todos os tipos escalares.","Porque toda referência é uma chave primária.","Porque impede qualquer armazenamento."]'::jsonb, 1, 'O capítulo questiona a introdução de um segundo mecanismo conceitual de associação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.3, páginas 1372–1377 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9f135694-68c8-58bd-8f53-36b6dc196a14', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Difícil', 'Substituir uma relvar básica por uma visão equivalente deve preservar, idealmente:', '["A possibilidade de uso compatível pelas aplicações.","Os endereços físicos de cada tupla.","A localização de todas as cópias.","A ordem de todas as páginas.","A identidade dos arquivos do sistema operacional."]'::jsonb, 0, 'O princípio da permutabilidade busca evitar dependências artificiais do caráter básico ou derivado.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.3, páginas 1372–1377 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1107c6c8-9cab-58ee-b644-2be03898437e', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Um pacote de tipos geoespaciais acrescenta principalmente:', '["Apenas cópias físicas das tabelas.","Somente temas visuais.","Somente logs de auditoria.","Tipos e operadores específicos de um domínio de aplicação.","Exclusivamente usuários."]'::jsonb, 3, 'Extensibilidade de tipos permite incorporar novas categorias de valores e operações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.4, páginas 1378–1381 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fb3f6698-af58-5055-96a9-ca6cbe725c97', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Adicionar novos tipos pode exigir integração com quais componentes?', '["Exclusivamente a tabela de usuários.","Somente o editor de texto.","Compilador, otimizador e gerenciador de armazenamento.","Apenas a tela de login.","Somente o serviço de impressão."]'::jsonb, 2, 'O suporte adequado não se limita a reconhecer um nome de tipo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.4, páginas 1378–1381 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dabfb682-e4d9-5789-9984-61e7183ee0ae', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Por que o otimizador pode precisar conhecer operadores de um novo pacote de tipos?', '["Para estimar custos e escolher formas adequadas de execução.","Para remover a tipagem.","Para alterar os valores retornados arbitrariamente.","Para decidir o significado de todas as regras de negócio.","Para desativar transações."]'::jsonb, 0, 'Operadores especializados podem possuir custos e possibilidades de acesso específicos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.4, páginas 1378–1381 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bf6894b0-a23c-52bd-bd0e-eeee8dfb92e8', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Armazenar um conteúdo complexo como bloco opaco garante boa consulta a suas propriedades?', '["Sim, qualquer bloco expõe todos os seus campos.","Sim, pela mera presença de uma chave.","Não, porque tipos complexos não podem existir.","Sim, desde que tenha muitos bytes.","Não; operações e suporte de consulta precisam estar disponíveis."]'::jsonb, 4, 'Armazenar bytes e oferecer operações úteis sobre seus valores são capacidades diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.4, páginas 1378–1381 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d318df0a-1733-56d2-b6db-650af4d8fdf3', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Qual combinação expressa a aproximação considerada útil no capítulo?', '["Somente navegação física e ausência de predicados.","Relvars sem tipos.","Ponteiros sem restrições.","Métodos sem persistência nem consultas.","Valores complexos bem tipados e consultas relacionais sobre coleções."]'::jsonb, 4, 'Tipos e relações atendem a necessidades complementares.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.5, páginas 1382–1384 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3afc2578-d118-5347-b90d-142c09a3bf54', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Segundo os recursos SQL descritos, tipos definidos pelo usuário podem servir para:', '["Eliminar a definição de esquemas.","Criar senhas automáticas.","Definir tipos de colunas em tabelas.","Substituir obrigatoriamente todos os SELECTs.","Impedir qualquer restrição."]'::jsonb, 2, 'O capítulo menciona tipos DISTINCT e estruturados no suporte SQL.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.6, páginas 1385–1393 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c5b5545c-cfe2-503e-930b-facb449a4ec0', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Médio', 'Qual par de categorias de tipos definidos pelo usuário é discutido no suporte SQL?', '["Logs físicos e lógicos.","Tipos DISTINCT e tipos estruturados.","Bloqueios compartilhados e exclusivos.","Transações locais e globais.","Índices primários e secundários."]'::jsonb, 1, 'As categorias de tipos são diferentes dos mecanismos de índice ou transação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.6, páginas 1385–1393 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3568ba74-ad0a-5856-a6bb-750df01f5dee', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'O rótulo comercial relacional/objeto garante, segundo a crítica de Date, fidelidade conceitual ao modelo defendido?', '["Sim, se houver interface gráfica.","Sim, se o banco tiver muitas tabelas.","Não, porque tipos próprios são proibidos no modelo.","Não; é necessário examinar os recursos e sua semântica.","Sim, o nome é uma prova suficiente."]'::jsonb, 3, 'O autor distingue propostas conceituais e implementações comercializadas sob o mesmo rótulo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 26, seção 26.1, páginas 1357–1360 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2727a23e-b259-55b6-a2cf-b40c2c32a599', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Fácil', 'World Wide Web e Internet são conceitos idênticos?', '["Não, porque a Web dispensa redes.","Sim, ambos são um SGBD.","Sim, ambos são uma linguagem de consulta.","Sim, os dois nomes designam exclusivamente HTML.","Não; a Web é um sistema de serviços que utiliza a infraestrutura da Internet."]'::jsonb, 4, 'A infraestrutura de comunicação não deve ser confundida com um de seus serviços.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.2, páginas 1410–1412 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('903c4411-0f77-5a50-a839-45caa5629374', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Fácil', 'XML é apresentada principalmente como uma metalinguagem para:', '["Gerenciar permissões do sistema operacional.","Definir vocabulários e estruturas de documentos marcados.","Definir apenas páginas com aparência fixa.","Substituir toda linguagem de programação.","Executar transações por conta própria."]'::jsonb, 1, 'A extensibilidade permite criar marcações específicas de diferentes domínios.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.3, páginas 1413–1426 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4b7535e0-96a3-557c-9f73-10971965de8a', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Qual estrutura caracteriza um documento XML bem formado?', '["Apenas texto sem qualquer marcação em todos os casos.","Vários elementos raiz independentes no mesmo documento.","Tags que podem se cruzar livremente.","Atributos sem nomes.","Elementos corretamente aninhados sob um elemento raiz."]'::jsonb, 4, 'As regras de boa formação governam a organização sintática do documento.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.3, páginas 1413–1426 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7f9ddf3d-905f-524f-99d3-446c071a9826', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'Qual fragmento possui aninhamento correto?', '["<a><b/></a>.","<a></b>.","<a><b></a>.","<a><b></a></b>.","<a><b/>."]'::jsonb, 0, 'Um elemento vazio pode usar a forma abreviada; os limites dos demais elementos precisam corresponder.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.3, páginas 1413–1426 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('74afa5a7-e6aa-5479-b713-c578334b552b', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Fácil', 'Em <curso codigo="7">Redes</curso>, codigo é:', '["Um método de recuperação.","Um atributo do elemento curso.","O elemento raiz de outro documento.","Um namespace necessariamente.","Uma instrução SQL."]'::jsonb, 1, 'Atributos aparecem na tag inicial e possuem valores associados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.3, páginas 1413–1426 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a93d8966-e790-53c2-bcec-1c2c640596f5', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'Qual distinção entre elemento e atributo XML está correta?', '["Atributos sempre contêm árvores completas de elementos.","Elementos podem conter outros elementos; atributos possuem valores na tag de início.","Elementos não podem conter texto.","Elementos e atributos são sempre intercambiáveis sem efeitos.","Atributos exigem uma tag de fechamento própria."]'::jsonb, 1, 'As formas de representação e suas possibilidades estruturais diferem.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.3, páginas 1413–1426 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('60d009da-b12d-53f3-a2ad-81bb4efbe11d', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Fácil', 'Qual finalidade têm os namespaces XML?', '["Eliminar a necessidade de tags.","Distinguir nomes de vocabulários que poderiam colidir.","Cifrar todo o documento.","Confirmar alterações em tabelas.","Converter XML em índice."]'::jsonb, 1, 'Qualificação de nomes evita confundir termos iguais de contextos diferentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.3, páginas 1413–1426 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('eec150ba-431e-56fe-aeb6-769c2690b9cd', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'A ordem dos elementos filhos em XML pode ser significativa?', '["Não, XML é sempre um conjunto matemático de tuplas.","Somente se os nomes forem numéricos.","Somente após um COMMIT.","Não, porque elementos não possuem pais.","Sim; a estrutura documental pode preservar essa ordem."]'::jsonb, 4, 'A ordenação documental distingue XML da ausência de ordem entre tuplas relacionais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.3, páginas 1413–1426 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('555b5ea1-3bdb-5af4-8315-5f878fbdbd96', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Boa formação e validade de XML são sinônimos?', '["Sim, porque DTD é uma tabela.","Sim, qualquer aninhamento correto garante qualquer esquema.","Não; validade exige conformidade com a definição estrutural aplicável.","Sim, desde que exista uma raiz.","Não, porque XML não tem regras sintáticas."]'::jsonb, 2, 'Um documento bem formado pode não satisfazer as regras de uma DTD ou esquema.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.4, páginas 1427–1438 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6134050d-519d-599e-a2a2-24a29d6f59fd', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Uma DTD descreve principalmente:', '["O conteúdo de todos os backups.","Uma transação de leitura.","Planos físicos de junção.","Estruturas e declarações admitidas para uma classe de documentos.","Somente senhas."]'::jsonb, 3, 'A DTD fornece descritores para verificar os documentos correspondentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.4, páginas 1427–1438 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d3eafc17-c80b-5dc0-a7bf-9a553490bdd6', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'XML Schema amplia a descrição de documentos com recursos como:', '["Tipagem mais rica de valores e estruturas.","Criptografia obrigatória.","Eliminação de todos os elementos.","Confirmação automática de transações SQL.","Substituição do sistema operacional."]'::jsonb, 0, 'O esquema pode expressar condições mais ricas que a declaração básica de marcação.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.4, páginas 1427–1438 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c18b2c7e-1723-5411-8caa-f3e5e7d06276', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Difícil', 'Um documento satisfaz a sintaxe XML, mas omite elemento obrigatório do esquema. Ele é:', '["Uma relação matemática obrigatoriamente.","Inválido sintaticamente em qualquer contexto.","Bem formado, porém inválido em relação àquele esquema.","Um banco de dados completo.","Sempre válido, pois possui tags."]'::jsonb, 2, 'Validação precisa ser avaliada contra as regras do esquema pertinente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.4, páginas 1427–1438 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8d05f1bf-b947-5cc1-afc7-24baebf4cb6c', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'XPath é associado principalmente a:', '["Gerenciar logs.","Definir chaves físicas de disco.","Expressar caminhos e selecionar partes da estrutura XML.","Confirmar transações.","Normalizar tabelas."]'::jsonb, 2, 'Expressões de caminho navegam na estrutura lógica dos dados XML.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.5, páginas 1439–1449 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6fbf57d0-8c8a-556d-a352-1bd8712933ee', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'XQuery é discutida como linguagem para:', '["Substituir toda DTD.","Executar somente backups.","Consultar e construir resultados a partir de dados XML.","Conceder apenas privilégios SQL.","Gerenciar exclusivamente hardware."]'::jsonb, 2, 'O capítulo apresenta sua proposta e seu estágio histórico de desenvolvimento.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.5, páginas 1439–1449 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0418c912-3097-5378-8d37-85e01f39248d', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Na forma FLWOR discutida, FOR permite principalmente:', '["Iterar sobre itens ligados a uma variável.","Eliminar a ordenação por definição.","Conceder privilégios.","Confirmar um commit.","Definir uma DTD."]'::jsonb, 0, 'A construção combina vinculações, filtros, ordenação e produção de resultados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.5, páginas 1439–1449 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('92f65f0b-a306-579e-b85d-51054d20bb12', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Uma representação analisada de XML é útil porque:', '["Dispensa todas as regras de tipagem.","Transforma tags em senhas.","Elimina a informação do documento.","Permite operar sobre sua estrutura informacional, além do texto bruto.","Torna qualquer documento automaticamente válido."]'::jsonb, 3, 'Consultas e APIs trabalham com modelos estruturados do conteúdo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.5, páginas 1439–1449 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5b2706eb-e6fb-5708-bae1-452e7312094b', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Qual necessidade justifica integrar XML a bancos de dados?', '["Substituir toda transação por uma tag.","Garantir que XML não tenha estrutura.","Impedir consultas sobre documentos.","Eliminar permanentemente o modelo relacional.","Armazenar e consultar dados XML e também exportar dados relacionais nesse formato."]'::jsonb, 4, 'O fluxo pode ocorrer nos dois sentidos entre representação documental e dados do banco.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.6, páginas 1450–1454 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('92fa7a74-12a5-5c04-93ae-21d03311eb2d', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'Armazenar XML como uma única coluna e decompor seu conteúdo em tabelas são:', '["Operações sempre impossíveis em bancos.","Formas de eliminar qualquer esquema.","Sinônimos de autenticação.","Estratégias diferentes, com compromissos de consulta e representação.","Duas grafias da mesma organização física."]'::jsonb, 3, 'A escolha depende do conteúdo, das operações desejadas e do suporte oferecido.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.6, páginas 1450–1454 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('888502ac-0cb3-511a-a00c-be469721625e', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Difícil', 'Representar uma relação como sequência de elementos XML introduz qual cuidado?', '["Não confundir ordem documental com ordem lógica obrigatória das tuplas.","Proibir a representação de valores.","Exigir que a relação possua duplicatas.","Eliminar todos os nomes de atributos.","Transformar cada chave em senha."]'::jsonb, 0, 'A serialização pode impor uma ordem que não integra o valor relacional original.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.6, páginas 1450–1454 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ffdc58e5-4be0-5a48-8ab6-cb948fa8fa0d', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'As previsões sobre SQL/XML feitas no livro devem ser lidas como:', '["Prova de que XML substituiu todas as tabelas.","Uma especificação sem possibilidade de mudança.","Documentação atualizada automaticamente de qualquer SGBD.","Descrição situada no contexto histórico da edição, não garantia do estado atual de produtos.","Regras que tornam todo SQL independente de versão."]'::jsonb, 3, 'O próprio capítulo avisa que a proposta de suporte discutida ainda estava sujeita a alterações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 27, seção 27.7, páginas 1455–1460 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
